INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c4b0f6c-bd0e-4270-bbb4-9629acbaaf38', '湖上作', '湖上作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["我竟胡爲者，嘮嘮但愛吟。","身中多病在，湖上住年深。","山霤穿苔壁，風鐘度雪林。","近來心更苦，誰復是知音。"]', '["我竟胡爲者，嘮嘮但愛吟。","身中多病在，湖上住年深。","山霤穿苔壁，风鐘度雪林。","近来心更苦，誰复是知音。"]', '诗', 'shi', '', NULL, '湖上作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c047d8a4-35fa-4b1d-9244-4e32dd842048', '送僧歸天台寺', '送僧归天台寺', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["天台四絕寺，歸去見師真。","莫折枸杞葉，令他十得嗔。","天空聞聖磬，瀑細落花巾。","必若雲中老，他時得有鄰。"]', '["天台四絕寺，归去见師真。","莫折枸杞葉，令他十得嗔。","天空闻聖磬，瀑細落花巾。","必若云中老，他时得有鄰。"]', '诗', 'shi', '', NULL, '送僧歸天台寺 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cbe66fe-efd2-4132-9383-71b3e8318a1b', '壽春節進', '壽春節進', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["聖運關天紀，龍飛古帝基。","振搖三蜀地，聳發萬年枝。","出震同中古，承乾動四夷。","恩頒新命廣，淚向舊朝垂。","大寶歸玄讖，殊祥出遠池。","法天深罔測，體聖妙難知。","儉德爲全德，無思契十思。","丕圖非力至，英武悉天資。","正直方親切，回邪豈敢窺。","將排頗與牧，相得稷兼夔。","鹽出符真主，麟來合大規。","賡歌隨羽籥，奕葉斅伊祁。","寡欲情雖泰，憂民色未怡。","盛如唐創業，宛勝晉朝儀。","旰食宮鶯囀，宵衣禁漏遲。","多於湯土地，還有禹胼胝。","視物如傷日，勝殘去殺時。","守文情的的，無逸戒孜孜。","軒頊風重振，皇唐鼎創移。","始聞呈瑞石，又報產靈芝。","覆幬高緣大，包容妙在卑。","兄呼春赫日，師指佛牟尼。","佳氣宸居合，淳風樂府吹。","急賢彰帝業，解網見天慈。","粟赤千千窖，軍雄萬萬兒。","八蠻須稽顙，四海仰昌期。","玉輦嬪嬙擁，宮花錦繡欹。","堯雲同靉靆，漢祖太驅馳。","氛祲根株盡，澆訛朕兆隳。","山河方有截，野逸詔無遺。","境靜消鋒鏑，田香熟稻𪎭。","夢中逢傅說，殿上見辛毗。","金鏡懸千古，彤雲起四維。","盛行唐典法，再覩舜雍熙。","祝壽乾文動，郊天太一隨。","煌煌還宿衛，亹亹叶聲詩。","飲醴和甘雨，非煙遶御帷。","銀輪隨寶馬，玉沼見金龜。","杳杳聞韶濩，重重降撫綏。","魏徵須却出，葛亮更何之。","簡約逾前古，昇平美不疑。","觸邪羊唅唅，鼓腹叟嘻嘻。","邁五方云大，超三始見奇。","錦霞連紫極，仙鳥下峨眉。","謝傅還爲傅，周師又作師。","納隍爲永任，從諫契無爲。","子子寰瀛主，孫孫日月旗。","壽春嗟壽域，萬國盡虔祈。","捧日三車子，恭思八彩眉。","願將七萬歲，匍匐拜瑤墀。"]', '["聖運关天紀，龙飞古帝基。","振搖三蜀地，聳發万年枝。","出震同中古，承乾动四夷。","恩頒新命廣，泪向旧朝垂。","大寶归玄讖，殊祥出远池。","法天深罔測，體聖妙难知。","儉德爲全德，無思契十思。","丕圖非力至，英武悉天資。","正直方親切，回邪豈敢窺。","將排頗與牧，相得稷兼夔。","鹽出符真主，麟来合大規。","賡歌隨羽籥，奕葉斅伊祁。","寡欲情雖泰，憂民色未怡。","盛如唐創業，宛勝晉朝儀。","旰食宮鶯囀，宵衣禁漏遲。","多於湯土地，還有禹胼胝。","視物如傷日，勝殘去殺时。","守文情的的，無逸戒孜孜。","軒頊风重振，皇唐鼎創移。","始闻呈瑞石，又報產靈芝。","覆幬高緣大，包容妙在卑。","兄呼春赫日，師指佛牟尼。","佳氣宸居合，淳风乐府吹。","急賢彰帝業，解網见天慈。","粟赤千千窖，軍雄万万兒。","八蠻須稽顙，四海仰昌期。","玉輦嬪嬙擁，宮花錦繡欹。","堯云同靉靆，漢祖太驱驰。","氛祲根株尽，澆訛朕兆隳。","山河方有截，野逸詔無遺。","境静消鋒鏑，田香熟稻𪎭。","梦中逢傅说，殿上见辛毗。","金镜懸千古，彤云起四維。","盛行唐典法，再覩舜雍熙。","祝壽乾文动，郊天太一隨。","煌煌還宿衛，亹亹叶声诗。","饮醴和甘雨，非煙遶御帷。","銀輪隨寶马，玉沼见金龟。","杳杳闻韶濩，重重降撫綏。","魏徵須却出，葛亮更何之。","簡約逾前古，昇平美不疑。","觸邪羊唅唅，鼓腹叟嘻嘻。","邁五方云大，超三始见奇。","錦霞連紫極，仙鸟下峨眉。","謝傅還爲傅，周師又作師。","納隍爲永任，從諫契無爲。","子子寰瀛主，孫孫日月旗。","壽春嗟壽域，万国尽虔祈。","捧日三车子，恭思八彩眉。","願將七万歲，匍匐拜瑤墀。"]', '诗', 'shi', '', NULL, '壽春節進 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71cf5a48-286d-4038-ab39-a3753fb48425', '送僧之安南', '送僧之安南', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["安南千萬里，師去趣何長。","鬢有炎州雪，心爲異國香。","退牙山象惡，過海布帆荒。","早作歸吳計，無忘父母鄉。"]', '["安南千万里，師去趣何长。","鬢有炎州雪，心爲異国香。","退牙山象惡，過海布帆荒。","早作归吳計，無忘父母乡。"]', '诗', 'shi', '', NULL, '送僧之安南 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5390c99-dbb3-4082-b090-a2993accba44', '送僧歸剡山', '送僧归剡山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["遠逃爲亂處，寺與石城連。","木落歸山路，人初刈剡田。","荒林猴咬栗，戰地鬼多年。","好去楞伽子，精修莫偶然。"]', '["远逃爲亂处，寺與石城連。","木落归山路，人初刈剡田。","荒林猴咬栗，戰地鬼多年。","好去楞伽子，精修莫偶然。"]', '诗', 'shi', '', NULL, '送僧歸剡山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bfb6de0-ca15-4efb-a45d-a40f1000ed32', '送僧入幽州', '送僧入幽州', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["高士高無敵，騰騰話入燕。","無人知爾意，向我道非禪。","栗逕穿蕃冢，狼聲隔遠煙。","槃山多道侶，應未有歸年。"]', '["高士高無敵，腾腾話入燕。","無人知爾意，向我道非禪。","栗逕穿蕃冢，狼声隔远煙。","槃山多道侶，應未有归年。"]', '诗', 'shi', '', NULL, '送僧入幽州 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66717e3a-7e92-4e45-866d-1b3040663704', '送僧遊五臺', '送僧游五台', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["羨師遊五頂，乞食值年豐。","去去誰爲侶，栖栖力已充。","濁河高岸拆，衰草古城空。","必到華嚴寺，憑師問辨公。"]', '["羨師游五頂，乞食值年豐。","去去誰爲侶，栖栖力已充。","濁河高岸拆，衰草古城空。","必到华嚴寺，憑師问辨公。"]', '诗', 'shi', '', NULL, '送僧遊五臺 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd159603-2350-4133-ae6d-5c348aba8c25', '送僧入五洩', '送僧入五洩', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["五洩江山寺，禪林境最奇。","九年喫菜粥，此事少人知。","山響僧擔穀，林香豹乳兒。","伊余頭已白，不去更何之。"]', '["五洩江山寺，禪林境最奇。","九年喫菜粥，此事少人知。","山响僧擔穀，林香豹乳兒。","伊余头已白，不去更何之。"]', '诗', 'shi', '', NULL, '送僧入五洩 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa4c2d7c-010e-4cf1-98b2-dd230dbfe621', '題令宣和尚院', '題令宣和尚院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["軒窗領嵐翠，師得世情忘。","惟愛談諸祖，曾經宿大荒。","泉聲淹臥榻，雲片犯鑪香。","寄語題門者，看經在上方。"]', '["軒窗領嵐翠，師得世情忘。","惟愛談諸祖，曾經宿大荒。","泉声淹臥榻，云片犯鑪香。","寄語題门者，看經在上方。"]', '诗', 'shi', '', NULL, '題令宣和尚院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('771a895b-913a-415f-a75e-8b4112333e61', '寄四明閭丘道士二首 一', '寄四明閭丘道士二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["淮海兵荒日，分飛直至今。","知擔諸子出，却入四明深。","衣必編仙草，僧應共栗林。","秋風溪上路，應得一相尋。"]', '["淮海兵荒日，分飞直至今。","知擔諸子出，却入四明深。","衣必編仙草，僧應共栗林。","秋风溪上路，應得一相尋。"]', '诗', 'shi', '', NULL, '寄四明閭丘道士二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5007e8b-4da7-4ec3-8c63-07bb32b86b76', '寄四明閭丘道士二首 二', '寄四明閭丘道士二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["三千功未了，大道本無程。","好共禪師好，牆將藥犬行。","石門紅蘚剝，柘塢白雲生。","莫認無名是，無名已是名。"]', '["三千功未了，大道本無程。","好共禪師好，牆將藥犬行。","石门紅蘚剝，柘塢白云生。","莫認無名是，無名已是名。"]', '诗', 'shi', '', NULL, '寄四明閭丘道士二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f216211-6e9e-4ca8-b22f-6309fabbe25c', '經士馬中作', '經士马中作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["偷兒成大寇，處處起煙塵。","黃葉滿空宅，青山見俗人。","妖星芒刺越，鬼哭勢連秦。","惆悵還惆悵，茫茫江海濱。"]', '["偷兒成大寇，处处起煙塵。","黄葉满空宅，青山见俗人。","妖星芒刺越，鬼哭勢連秦。","惆悵還惆悵，茫茫江海濱。"]', '诗', 'shi', '', NULL, '經士馬中作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37087c5a-4952-4cac-addd-29b4f2369899', '士馬後見赤松舒道士', '士马後见赤松舒道士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["滿眼盡瘡痍，相逢相對悲。","亂階猶未已，一柱若爲支。","堰茗蒸紅棗，看花似好時。","不知今日後，吾道竟何之。"]', '["满眼尽瘡痍，相逢相对悲。","亂階猶未已，一柱若爲支。","堰茗蒸紅棗，看花似好时。","不知今日後，吾道竟何之。"]', '诗', 'shi', '', NULL, '士馬後見赤松舒道士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('522876a2-be3b-4275-a0ea-b3238c20e796', '題方公院寄夏侯明府', '題方公院寄夏侯明府', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["銀地有餘光，方公道益芳。","誰分修藏力，頂有剃頭霜。","經勘松風燥，簷垂塢茗香。","終須結西社，此縣似柴桑。"]', '["銀地有餘光，方公道益芳。","誰分修藏力，頂有剃头霜。","經勘松风燥，簷垂塢茗香。","終須結西社，此縣似柴桑。"]', '诗', 'shi', '', NULL, '題方公院寄夏侯明府 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b89c776e-a8ff-4142-89bb-ad7eb1607de8', '與劉象正字', '與劉象正字', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["獨居三島上，花竹映柴關。","道廣羣仙惜，名成萬事閑。","病多唯縱酒，靜極不思山。","唯有逍遙子，時時自往還。"]', '["独居三島上，花竹映柴关。","道廣羣仙惜，名成万事闲。","病多唯縱酒，静極不思山。","唯有逍遙子，时时自往還。"]', '诗', 'shi', '', NULL, '與劉象正字 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aee9d96-68d9-4f98-8e8c-7398592228ad', '懷智體道人', '懷智體道人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["栖碧思吾友，庭鶯百囀時。","唯應一處住，方得不相思。","雲水淹門閫，春雷在樹枝。","平生無限事，不獨白雲知。"]', '["栖碧思吾友，庭鶯百囀时。","唯應一处住，方得不相思。","云水淹门閫，春雷在樹枝。","平生無限事，不独白云知。"]', '诗', 'shi', '', NULL, '懷智體道人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fbc473c-0e44-4473-a652-e2d492942c4c', '贈晦公禪人', '贈晦公禪人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["流陽爲役者，相訪葉紛紛。","有句雖如我，無心未似君。","搆林青及竹，茆屋暖於雲。","何日相將去，千山麋鹿羣。"]', '["流陽爲役者，相訪葉紛紛。","有句雖如我，無心未似君。","搆林青及竹，茆屋暖於云。","何日相將去，千山麋鹿羣。"]', '诗', 'shi', '', NULL, '贈晦公禪人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('175506e9-c38f-4ce1-be8a-f4622fe46631', '寄靜林別墅胡進士兄弟', '寄静林別墅胡進士兄弟', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["見說山居好，書樓被翠侵。","燒熛汀島境，月色弟兄吟。","犬吠黃椑落，牛歸紅樹深。","仍聞多白菌，應許一相尋。"]', '["见说山居好，书楼被翠侵。","燒熛汀島境，月色弟兄吟。","犬吠黄椑落，牛归紅樹深。","仍闻多白菌，應許一相尋。"]', '诗', 'shi', '', NULL, '寄靜林別墅胡進士兄弟 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4273dd44-be33-493c-8b2a-8e56844c678a', '懷赤松故舒道士', '懷赤松故舒道士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["可惜復可惜，如今何所之。","信來堪大慟，余復用生爲。","亂世今交鬬，玄宮玉柱隳。","春風五陵道，迴首不勝悲。"]', '["可惜复可惜，如今何所之。","信来堪大慟，余复用生爲。","亂世今交鬬，玄宮玉柱隳。","春风五陵道，迴首不勝悲。"]', '诗', 'shi', '', NULL, '懷赤松故舒道士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9462fbdb-3e82-4c66-9664-4a9a48f26145', '偶作', '偶作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["無端爲五字，字字鬢星星。","祗覺人情薄，空餘鶴眼青。","砌莎藏墜果，窗雪浸殘經。","祗有歸山計，茫茫何所營。"]', '["無端爲五字，字字鬢星星。","祗覺人情薄，空餘鹤眼青。","砌莎藏墜果，窗雪浸殘經。","祗有归山計，茫茫何所營。"]', '诗', 'shi', '', NULL, '偶作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96febb86-fd57-4d6f-a5fe-eff5eb405508', '春日許徵君見訪', '春日許徵君见訪', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["龍鍾多病後，日望遇昇平。","遠念穿嵩雪，前林囀早鶯。","廚香烹瓠葉，道友扣門聲。","還似青溪上，微吟踏葉行。"]', '["龙鍾多病後，日望遇昇平。","远念穿嵩雪，前林囀早鶯。","廚香烹瓠葉，道友扣门声。","還似青溪上，微吟踏葉行。"]', '诗', 'shi', '', NULL, '春日許徵君見訪 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('252eeb01-543e-4090-92d0-ee1e07104815', '經先主廟作', '經先主廟作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["古廟積煙蘿，威靈及物多。","因知曹孟德，爭奈此公何。","樹古雷痕剝，碑荒篆畫訛。","今朝冥禱祝，祗望息干戈。"]', '["古廟積煙蘿，威靈及物多。","因知曹孟德，爭奈此公何。","樹古雷痕剝，碑荒篆畫訛。","今朝冥禱祝，祗望息干戈。"]', '诗', 'shi', '', NULL, '經先主廟作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc2dae4f-0088-4da7-b321-684daa48de3e', '寄中條道者', '寄中條道者', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["柏梯杉影裏，頭白藥山孫。","今古管不得，是非爭肯論。","虎鬚懸瀑滴，禪衲帶苔痕。","常恨龍鍾也，無因接話言。"]', '["柏梯杉影裏，头白藥山孫。","今古管不得，是非爭肯論。","虎鬚懸瀑滴，禪衲带苔痕。","常恨龙鍾也，無因接話言。"]', '诗', 'shi', '', NULL, '寄中條道者 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9b20a13-863b-4ef4-b123-acf03a25c13c', '夏日晚望', '夏日晚望', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["登臨聊一望，不覺意恞然。","陶侃寒溪寺，如今何處邊。","汀沙生旱霧，山火照平川。","終事東歸去，干戈滿許田。"]', '["登臨聊一望，不覺意恞然。","陶侃寒溪寺，如今何处邊。","汀沙生旱霧，山火照平川。","終事东归去，干戈满許田。"]', '诗', 'shi', '', NULL, '夏日晚望 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96f2b887-08cf-48cd-bf65-e6ca0804651c', '送僧歸山', '送僧归山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["眼青禪帔赤，氣岸出塵埃。","霞外終須去，人間作麽來。","崖香泉吐乳，塢燥燒□靁。","他日終相覓，山門何處開。"]', '["眼青禪帔赤，氣岸出塵埃。","霞外終須去，人间作麽来。","崖香泉吐乳，塢燥燒□靁。","他日終相覓，山门何处开。"]', '诗', 'shi', '', NULL, '送僧歸山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d149d11-0994-4c0e-ac02-5e83fe7326ee', '覽皎然渠南鄉集', '覽皎然渠南乡集', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["學力不相敵，清還彷彿同。","高于寶月月，誰得射鵰弓。","至鑒封姚監，良工遇魯公。","如斯深可慕，千古共清風。"]', '["学力不相敵，清還彷彿同。","高于寶月月，誰得射鵰弓。","至鑒封姚監，良工遇魯公。","如斯深可慕，千古共清风。"]', '诗', 'shi', '', NULL, '覽皎然渠南鄉集 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad271a01-f877-47f3-ae99-62dd84891260', '覽姚合極玄集', '覽姚合極玄集', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["至覽如日月，今時即古時。","髮如邊草白，誰念射聲□。","好鳥挨花落，清風出院遲。","知音郭有道，始爲一吟之。"]', '["至覽如日月，今时即古时。","髮如邊草白，誰念射声□。","好鸟挨花落，清风出院遲。","知音郭有道，始爲一吟之。"]', '诗', 'shi', '', NULL, '覽姚合極玄集 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51dc8948-fd9c-45fd-a69d-fb15c8e59589', '大駕西幸秋日聞雷', '大駕西幸秋日闻雷', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["軍書日日催，處處起塵埃。","黎庶何由泰，鑾輿早晚回。","夏租方減食，秋日更聞雷。","莫道蒼蒼意，蒼蒼眼甚開。"]', '["軍书日日催，处处起塵埃。","黎庶何由泰，鑾輿早晚回。","夏租方減食，秋日更闻雷。","莫道蒼蒼意，蒼蒼眼甚开。"]', '诗', 'shi', '', NULL, '大駕西幸秋日聞雷 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a2d484d-209e-44ba-82b2-1967f8adcb1e', '詩', '诗', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["經天緯地物，動必計仙才。","幾處覓不得，有時還自來。","真風含素髮，秋色入靈臺。","吟向霜蟾下，終須神鬼哀。"]', '["經天緯地物，动必計仙才。","幾处覓不得，有时還自来。","真风含素髮，秋色入靈台。","吟向霜蟾下，終須神鬼哀。"]', '诗', 'shi', '', NULL, '詩 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0255decc-b5bb-4da3-98a0-a4cb948840a8', '秋末江上望', '秋末江上望', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["莽莽古江濱，紛紛墜葉頻。","煙霞誰是主，丘隴自傷神。","吞併寧唯漢，淒涼莫問陳。","盡隨流水去，寂寞野花春。"]', '["莽莽古江濱，紛紛墜葉頻。","煙霞誰是主，丘隴自傷神。","吞併寧唯漢，淒涼莫问陳。","尽隨流水去，寂寞野花春。"]', '诗', 'shi', '', NULL, '秋末江上望 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a6ca5c-3e98-4fda-a295-c362713e692b', '乞食僧', '乞食僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["擎鉢貌清羸，天寒出寺遲。","朱門當大路，風雪立多時。","似月心常淨，如麻事不知。","行人莫輕誚，古佛盡如斯。"]', '["擎鉢貌清羸，天寒出寺遲。","朱门當大路，风雪立多时。","似月心常淨，如麻事不知。","行人莫轻誚，古佛尽如斯。"]', '诗', 'shi', '', NULL, '乞食僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f254cac9-e2dc-4085-af8b-e40a895c0032', '寒望九峰作', '寒望九峰作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["九朵碧芙蕖，王維圖未圖。","層層皆有瀑，一一合吾居。","雨歇如爭出，霜嚴不例枯。","世猶多事在，爲爾久躊躇。"]', '["九朵碧芙蕖，王維圖未圖。","層層皆有瀑，一一合吾居。","雨歇如爭出，霜嚴不例枯。","世猶多事在，爲爾久躊躇。"]', '诗', 'shi', '', NULL, '寒望九峰作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49741534-bb7c-488a-8d2a-be1507a461b3', '薊北寒月作', '薊北寒月作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["薊門寒到骨，戰磧鴈相悲。","古屋不勝雪，嚴風欲斷髭。","清吟得冷句，遠念失佳期。","寂莫誰相問，迢迢天一涯。"]', '["薊门寒到骨，戰磧鴈相悲。","古屋不勝雪，嚴风欲斷髭。","清吟得冷句，远念失佳期。","寂莫誰相问，迢迢天一涯。"]', '诗', 'shi', '', NULL, '薊北寒月作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61bf19ab-bb91-4333-a986-aea3dc04b191', '新猨', '新猨', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["尋常看不見，花落樹多苔。","忽向高枝發，又從何處來？","風清聲更揭，月苦意彌哀。","多少求名者，年年被爾催。"]', '["尋常看不见，花落樹多苔。","忽向高枝發，又從何处来？","风清声更揭，月苦意彌哀。","多少求名者，年年被爾催。"]', '诗', 'shi', '', NULL, '新猨 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c900276a-a8ca-4dea-866a-478a565f5fb2', '懷南岳隱士二首 一', '懷南岳隐士二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["千峰映碧湘，真隱此中藏。","餅不煮石喫，眉應似髮長。","風榸支酒甕，鶴蝨落琴床。","雖斅忘機者，斯人尚未忘。"]', '["千峰映碧湘，真隐此中藏。","餅不煮石喫，眉應似髮长。","风榸支酒甕，鹤蝨落琴床。","雖斅忘機者，斯人尚未忘。"]', '诗', 'shi', '', NULL, '懷南岳隱士二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ae6173-c0a7-48eb-9389-93a839d8a133', '懷南岳隱士二首 二', '懷南岳隐士二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["見說祝融峰，擎天勢似騰。","藏千尋瀑布，出十八高僧。","古路無人跡，新霞出石稜。","終期將爾叟，一一月中登。"]', '["见说祝融峰，擎天勢似腾。","藏千尋瀑布，出十八高僧。","古路無人跡，新霞出石稜。","終期將爾叟，一一月中登。"]', '诗', 'shi', '', NULL, '懷南岳隱士二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab617656-3109-4691-8035-bb1c072e35b2', '追憶馮少常', '追憶馮少常', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["盛德方清貴，旋聞逐逝波。","令人翻不會，積善合如何。","直道登朝晚，分憂及物多。","至今新定郡，猶詠袴襦歌。"]', '["盛德方清貴，旋闻逐逝波。","令人翻不會，積善合如何。","直道登朝晚，分憂及物多。","至今新定郡，猶詠袴襦歌。"]', '诗', 'shi', '', NULL, '追憶馮少常 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d5769b1-7767-4a07-bd05-fbc09bef304b', '聞閔廷言周璉下第', '闻閔廷言周璉下第', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["前牓年年見，高名日日聞。","常因不平事，便欲見吾君。","兄弟居清島，園林生白雲。","相思空悵望，庭葉赤紛紛。"]', '["前牓年年见，高名日日闻。","常因不平事，便欲见吾君。","兄弟居清島，园林生白云。","相思空悵望，庭葉赤紛紛。"]', '诗', 'shi', '', NULL, '聞閔廷言周璉下第 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8edf0d94-af14-4e33-bee9-b72de300b828', '寄景地判官', '寄景地判官', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["渚宮江上別，倏忽十餘年。","舉世唯攻說，多君即不然。","浦珠爲履重，園柳助詩玄。","勉力酬知己，昌朝正急賢。"]', '["渚宮江上別，倏忽十餘年。","舉世唯攻说，多君即不然。","浦珠爲履重，园柳助诗玄。","勉力酬知己，昌朝正急賢。"]', '诗', 'shi', '', NULL, '寄景地判官 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4709ba-359c-4c74-af9a-2723ea82799b', '讀賈區賈島集', '读賈區賈島集', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["區終不下島，島亦不多區。","冷格俱無敵，貧根亦似愚。","青雲終歎命，白閣久圍鑪。","今日成名者，還堪爲爾吁。"]', '["區終不下島，島亦不多區。","冷格俱無敵，貧根亦似愚。","青云終歎命，白閣久圍鑪。","今日成名者，還堪爲爾吁。"]', '诗', 'shi', '', NULL, '讀賈區賈島集 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5b63a09-77d3-43e3-bd65-ff0b6aa43843', '送衲僧之江西', '送衲僧之江西', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["索索復索索，無憑却有憑。","過溪遭惡雨，乞食得乾菱。","祗有山相伴，終無事可仍。","如逢梅嶺旦，向道祗寧馨。"]', '["索索复索索，無憑却有憑。","過溪遭惡雨，乞食得乾菱。","祗有山相伴，終無事可仍。","如逢梅嶺旦，向道祗寧馨。"]', '诗', 'shi', '', NULL, '送衲僧之江西 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c9f354c-2295-4388-9f19-4b5921e744fc', '故林偶作', '故林偶作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["朗吟無一事，孤坐瀔江濆。","媚世非吾道，良圖有白雲。","蠹魚開卷落，啄木隔花聞。","唯寄壺中客，金丹許共分。"]', '["朗吟無一事，孤坐瀔江濆。","媚世非吾道，良圖有白云。","蠹鱼开卷落，啄木隔花闻。","唯寄壺中客，金丹許共分。"]', '诗', 'shi', '', NULL, '故林偶作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('add5fcf7-82bd-47c4-aba9-706a2dfce502', '寄栖白大師二首 一', '寄栖白大師二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["流浪江湖久，攀緣歲月闌。","高名當世重，好句逼人寒。","月苦蟬聲嗄，鐘清柿葉乾。","龍鍾千萬里，擬欲訪師難。"]', '["流浪江湖久，攀緣歲月闌。","高名當世重，好句逼人寒。","月苦蟬声嗄，鐘清柿葉乾。","龙鍾千万里，擬欲訪師难。"]', '诗', 'shi', '', NULL, '寄栖白大師二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70e0bd29-19cc-47be-9c51-656fb0cccdf6', '寄栖白大師二首 二', '寄栖白大師二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蒼蒼龍闕晚，九陌雜香塵。","方外無他事，僧中有近臣。","青門玉露滴，紫閣錦霞新。","莫話三峰去，澆風正蕩淳。"]', '["蒼蒼龙闕晚，九陌杂香塵。","方外無他事，僧中有近臣。","青门玉露滴，紫閣錦霞新。","莫話三峰去，澆风正蕩淳。"]', '诗', 'shi', '', NULL, '寄栖白大師二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e890fa8f-ef38-4559-bf37-41f23fbb986f', '送人之渤海', '送人之渤海', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["國之東北角，有國每朝天。","海力浸不盡，夷風常宛然。","山藏羅剎宅，水雜巨鼇涎。","好去吳鄉子，歸來莫隔年。"]', '["国之东北角，有国每朝天。","海力浸不尽，夷风常宛然。","山藏羅剎宅，水杂巨鼇涎。","好去吳乡子，归来莫隔年。"]', '诗', 'shi', '', NULL, '送人之渤海 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3243f69c-2781-43db-94fc-80d9ff2619f2', '寄李道士', '寄李道士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常見高人說，猶來不偶然。","致身同槁木，話道出忘詮。","長嘯仙鐘外，眠楂海月邊。","倘修陰奼奼，一望寄余焉。"]', '["常见高人说，猶来不偶然。","致身同槁木，話道出忘詮。","长嘯仙鐘外，眠楂海月邊。","倘修陰奼奼，一望寄余焉。"]', '诗', 'shi', '', NULL, '寄李道士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('285410fe-e0ee-4048-8da3-ea16725ce326', '秋送夏郢歸錢塘', '秋送夏郢归錢塘', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["歸客指吳國，風帆幾日程。","新詩陶雪字，玄髮有霜莖。","微月生滄海，殘濤傍石城。","從茲江島意，應續子陵名。"]', '["归客指吳国，风帆幾日程。","新诗陶雪字，玄髮有霜莖。","微月生滄海，殘濤傍石城。","從茲江島意，應續子陵名。"]', '诗', 'shi', '', NULL, '秋送夏郢歸錢塘 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ebb584-ba83-444f-88ae-08edaf422888', '送僧歸翠微', '送僧归翠微', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["祗衲一箇衲，翠微歸舊岑。","不知何歲月，即得到師心。","逕遶千峰細，菴開亂木深。","倘然雲外老，他日亦相尋。"]', '["祗衲一箇衲，翠微归旧岑。","不知何歲月，即得到師心。","逕遶千峰細，菴开亂木深。","倘然云外老，他日亦相尋。"]', '诗', 'shi', '', NULL, '送僧歸翠微 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e66327a-4ad6-4149-9049-0a3a16707d17', '經友生墳', '經友生墳', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["多君墳在此，令我過悲涼。","可惜爲人好，剛須被數將。","白雲從冢出，秋草爲誰荒。","不覺頻回首，西風滿白楊。"]', '["多君墳在此，令我過悲涼。","可惜爲人好，剛須被數將。","白云從冢出，秋草爲誰荒。","不覺頻回首，西风满白楊。"]', '诗', 'shi', '', NULL, '經友生墳 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c433894-b8ad-4808-b9d0-7969988a6c80', '懷洛下盧縉雲', '懷洛下盧縉云', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一減三張價，幽居少室前。","豈應貧似我，不得信經年。","木落多詩藁，山枯見墨煙。","何時深夜坐，共話草堂禪。"]', '["一減三張價，幽居少室前。","豈應貧似我，不得信經年。","木落多诗藁，山枯见墨煙。","何时深夜坐，共話草堂禪。"]', '诗', 'shi', '', NULL, '懷洛下盧縉雲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df6803fd-a80d-436f-8843-8805fbfacfff', '送李鉶赴舉', '送李鉶赴舉', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["詩業務經綸，新皆意外新。","因知登第牓，不著不平人。","句得孤舟月，心飛九陌塵。","明年相賀日，應到曲江濱。"]', '["诗業務經綸，新皆意外新。","因知登第牓，不著不平人。","句得孤舟月，心飞九陌塵。","明年相賀日，應到曲江濱。"]', '诗', 'shi', '', NULL, '送李鉶赴舉 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6b97eb-7117-4ef1-948c-0e09955607a8', '寶禪師見訪', '寶禪師见訪', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山兄心似我，岸谷亦難交。","不見還相憶，來唯添寂寥。","茶煙黏衲葉，雲水透蘅茆。","因話流年事，斯須不可拋。"]', '["山兄心似我，岸谷亦难交。","不见還相憶，来唯添寂寥。","茶煙黏衲葉，云水透蘅茆。","因話流年事，斯須不可拋。"]', '诗', 'shi', '', NULL, '寶禪師見訪 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a93b2ba2-9953-44b2-bfec-d3eb0443bb92', '觀碁', '观碁', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["逸格格難及，半先相遇稀。","落花方滿地，一局到斜暉。","褚胤死不死，將軍飛已飛。","今朝慙一行，無以造玄微。"]', '["逸格格难及，半先相遇稀。","落花方满地，一局到斜暉。","褚胤死不死，將軍飞已飞。","今朝慙一行，無以造玄微。"]', '诗', 'shi', '', NULL, '觀碁 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf79bf91-0526-4cf8-b359-acfab4c88ea1', '題一上人經閣', '題一上人經閣', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鳥外何須去，衣如蘚亦從。","但能無一事，即是住孤峰。","雨歇雲埋閣，月明霜灑松。","師心多似我，所以訪師重。"]', '["鸟外何須去，衣如蘚亦從。","但能無一事，即是住孤峰。","雨歇云埋閣，月明霜灑松。","師心多似我，所以訪師重。"]', '诗', 'shi', '', NULL, '題一上人經閣 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60ba02ca-1661-4bcc-8c0a-81f1ff06cc42', '和毛學士舍人早春', '和毛学士舍人早春', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["陋巷冬將盡，東風細雜籃。","解牽窗夢遠，先是澗梅諳。","茶癖金鐺快，松香玉露含。","書齋山帚撅，盤饌藥花甘。","雅得琴中妙，常挼臉似酣。","雪消聞苦蟄，氣候似宜蠶。","密勿須清甲，朝歸遶碧潭。","丹心空拱北，新作繼周南。","竹杖無斑點，紗巾不著簪。","大朝名益重，後進力皆覃。","至理雖亡一，臣時亦說三。","不知門下客，誰上晏嬰驂。"]', '["陋巷冬將尽，东风細杂籃。","解牽窗梦远，先是澗梅諳。","茶癖金鐺快，松香玉露含。","书斋山帚撅，盤饌藥花甘。","雅得琴中妙，常挼臉似酣。","雪消闻苦蟄，氣候似宜蠶。","密勿須清甲，朝归遶碧潭。","丹心空拱北，新作繼周南。","竹杖無斑点，紗巾不著簪。","大朝名益重，後進力皆覃。","至理雖亡一，臣时亦说三。","不知门下客，誰上晏嬰驂。"]', '诗', 'shi', '', NULL, '和毛學士舍人早春 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be4ea984-34ba-4689-b7b4-3846ca440d03', '壽春進祝聖七首 千載降祥', '壽春進祝聖七首 千載降祥', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["九天宮上聖，降世共昭回。","萬彙須亭毓，羣仙送下來。","承乾當否極，庶事盡康哉。","祗有羲軒比，其餘不可陪。"]', '["九天宮上聖，降世共昭回。","万彙須亭毓，羣仙送下来。","承乾當否極，庶事尽康哉。","祗有羲軒比，其餘不可陪。"]', '诗', 'shi', '', NULL, '壽春進祝聖七首 千載降祥 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb48b6a9-020f-4bb7-a038-8c4178f14a3d', '壽春進祝聖七首 文有武備', '壽春進祝聖七首 文有武備', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["武宿與文星，常如掌上擎。","孫吳機不動，周邵事多行。","旰食爐煙細，宵衣隙月明。","還聞夔進曲，吹出泰階平。"]', '["武宿與文星，常如掌上擎。","孫吳機不动，周邵事多行。","旰食爐煙細，宵衣隙月明。","還闻夔進曲，吹出泰階平。"]', '诗', 'shi', '', NULL, '壽春進祝聖七首 文有武備 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb629c4-f793-4628-94d7-f75c5dea1f44', '壽春進祝聖七首 從諫如流', '壽春進祝聖七首 從諫如流', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["及霤龍鱗動，君臣道義深。","萬年軒后鏡，一片漢高心。","北狄皆輸欵，南夷盡貢琛。","從茲千萬歲，枝葉玉森森。"]', '["及霤龙鱗动，君臣道義深。","万年軒后镜，一片漢高心。","北狄皆輸欵，南夷尽貢琛。","從茲千万歲，枝葉玉森森。"]', '诗', 'shi', '', NULL, '壽春進祝聖七首 從諫如流 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4b31556-2fae-40ca-9409-359c7793c986', '壽春進祝聖七首 搜揚草澤', '壽春進祝聖七首 搜揚草澤', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["俟時兼待價，垂棘出塵埃。","仄席三旌切，移山萬里來。","煙霞衣上落，閶闔雪中開。","壽酒今朝進，無非出世才。"]', '["俟时兼待價，垂棘出塵埃。","仄席三旌切，移山万里来。","煙霞衣上落，閶闔雪中开。","壽酒今朝進，無非出世才。"]', '诗', 'shi', '', NULL, '壽春進祝聖七首 搜揚草澤 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02db6361-eca2-424a-807a-0c1b7861f39e', '壽春進祝聖七首 守在四夷', '壽春進祝聖七首 守在四夷', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["天將興大蜀，有道遂君臨。","四塞同諸子，三邊共一心。","闍婆香似雪，迴鶻馬如林。","曾讀前皇傳，巍巍冠古今。"]', '["天將兴大蜀，有道遂君臨。","四塞同諸子，三邊共一心。","闍婆香似雪，迴鶻马如林。","曾读前皇傳，巍巍冠古今。"]', '诗', 'shi', '', NULL, '壽春進祝聖七首 守在四夷 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a717cfb6-f815-42d1-bd45-761be72bb35d', '壽春進祝聖七首 大興三教', '壽春進祝聖七首 大兴三教', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["曈曈懸佛日，天俁動雲韶。","縫掖諸生集，麟洲羽客朝。","非煙生玉砌，御柳吐金條。","擊壤翁知否，吾皇即帝堯。"]', '["曈曈懸佛日，天俁动云韶。","縫掖諸生集，麟洲羽客朝。","非煙生玉砌，御柳吐金條。","擊壤翁知否，吾皇即帝堯。"]', '诗', 'shi', '', NULL, '壽春進祝聖七首 大興三教 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d543fc0-87fd-4499-b023-e7b9ec10a29a', '壽春進祝聖七首 山呼萬歲', '壽春進祝聖七首 山呼万歲', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["聲教無爲日，山呼萬歲聲。","隆隆如谷響，合合似雷鳴。","翠拔爲天柱，根盤倚鳳城。","恭唯千萬歲，歲歲致昇平。"]', '["声教無爲日，山呼万歲声。","隆隆如谷响，合合似雷鳴。","翠拔爲天柱，根盤倚鳳城。","恭唯千万歲，歲歲致昇平。"]', '诗', 'shi', '', NULL, '壽春進祝聖七首 山呼萬歲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d1c3b2f-07c9-45d9-9bf7-fbc564e38a07', '早秋夜坐', '早秋夜坐', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["微涼砧滿城，林下石牀平。","髮豈無端白，詩須出世清。","鄰僧同樹影，砌月浸蛩聲。","獨自更深坐，無人知此情。"]', '["微涼砧满城，林下石牀平。","髮豈無端白，诗須出世清。","鄰僧同樹影，砌月浸蛩声。","独自更深坐，無人知此情。"]', '诗', 'shi', '', NULL, '早秋夜坐 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a462560-cf31-4b31-8ee4-750840065796', '早起', '早起', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["夜坐還早起，寂寥多病身。","神清尋夢在，香極覺花新。","樹露繁於雨，溪雲動似人。","又知何處客，軋軋轉征輪。"]', '["夜坐還早起，寂寥多病身。","神清尋梦在，香極覺花新。","樹露繁於雨，溪云动似人。","又知何处客，軋軋轉征輪。"]', '诗', 'shi', '', NULL, '早起 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('087be504-e02f-456d-9862-961c7dc55a9d', '秋晚野步', '秋晚野步', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["閑步不覺遠，蕭蕭木落初。","詩情拋閫閾，江影動襟裾。","閣北鴻行出，霞西雨脚疎。","金峰秋更好，乞取又何如。"]', '["闲步不覺远，蕭蕭木落初。","诗情拋閫閾，江影动襟裾。","閣北鴻行出，霞西雨脚疎。","金峰秋更好，乞取又何如。"]', '诗', 'shi', '', NULL, '秋晚野步 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26cd082-0c0b-41cb-98a1-2a13389b22ea', '晚望', '晚望', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["曠望危橋上，微吟落照前。","煙霞濃浸海，川岳闊連天。","白鳥格不俗，孤雲態可憐。","終期將爾輩，歸去舊江邊。"]', '["曠望危橋上，微吟落照前。","煙霞濃浸海，川岳闊連天。","白鸟格不俗，孤云態可怜。","終期將爾輩，归去旧江邊。"]', '诗', 'shi', '', NULL, '晚望 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('586f5ce1-3b73-4d88-8bbc-de3891ad2e48', '寄翰林陸學士', '寄翰林陸学士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["顏冉商參甲，鸞凰密勿才。","簾垂仙鳥下，吟次聖人來。","寶輦千官捧，宮花九色開。","何時重一見，爲我話蓬萊。"]', '["顏冉商參甲，鸾凰密勿才。","簾垂仙鸟下，吟次聖人来。","寶輦千官捧，宮花九色开。","何时重一见，爲我話蓬萊。"]', '诗', 'shi', '', NULL, '寄翰林陸學士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f66ede0-1e60-49d0-82d4-c007469decd1', '贈造微禪師院', '贈造微禪師院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["薝蔔氣雍雍，門深聖澤重。","七絲奔小蟹，五字逼雕龍。","藥轉紅金鼎，茶開紫閣封。","圭峰爭去得，卿相日憧憧。"]', '["薝蔔氣雍雍，门深聖澤重。","七絲奔小蟹，五字逼雕龙。","藥轉紅金鼎，茶开紫閣封。","圭峰爭去得，卿相日憧憧。"]', '诗', 'shi', '', NULL, '贈造微禪師院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c92b7f80-2183-45e3-8b19-2209b4a9be24', '南海晚望', '南海晚望', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["海上聊一望，舶帆天際飛。","狂蠻莫挂甲，聖主正垂衣。","風惡巨魚出，山昏羣獠歸。","無人知此意，吟到月騰輝。"]', '["海上聊一望，舶帆天際飞。","狂蠻莫挂甲，聖主正垂衣。","风惡巨鱼出，山昏羣獠归。","無人知此意，吟到月腾輝。"]', '诗', 'shi', '', NULL, '南海晚望 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b15167ff-7ef9-43e4-879b-4e5d66447f56', '寄廬山大願和尚', '寄廬山大願和尚', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["石上桂成叢，師菴在桂中。","皆云習鑿齒，未可扣真風。","雪洗香鑪碧，霞藏瀑布紅。","何時甘露偈，一寄剡山東。"]', '["石上桂成叢，師菴在桂中。","皆云習鑿齒，未可扣真风。","雪洗香鑪碧，霞藏瀑布紅。","何时甘露偈，一寄剡山东。"]', '诗', 'shi', '', NULL, '寄廬山大願和尚 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b68df73-e583-47ce-ac8b-ff76445646f8', '懷薛尚書兼呈東陽王使君', '懷薛尚书兼呈东陽王使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["得力未得力，高吟夏又殘。","二毛非自出，萬事到詩難。","蟬見木葉落，雷將雨氣寒。","何妨槌琢後，更獻至公看。"]', '["得力未得力，高吟夏又殘。","二毛非自出，万事到诗难。","蟬见木葉落，雷將雨氣寒。","何妨槌琢後，更獻至公看。"]', '诗', 'shi', '', NULL, '懷薛尚書兼呈東陽王使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb0322ad-df37-4932-b240-3dbb7b36ad88', '上馮使君水晶數珠', '上馮使君水晶數珠', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["泠泠瀑滴清，貫串有規程。","將諷觀空偈，全勝照乘明。","龍神多共惜，金玉比終輕。","願在玄暉手，常資物外情。"]', '["泠泠瀑滴清，貫串有規程。","將諷观空偈，全勝照乘明。","龙神多共惜，金玉比終轻。","願在玄暉手，常資物外情。"]', '诗', 'shi', '', NULL, '上馮使君水晶數珠 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79e090ac-1376-4d6c-adec-6069b28da39d', '送明覺大師兼寄鄭山人', '送明覺大師兼寄鄭山人', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["去去楞伽子，春深道路長。","鳥啼青嶂險，花落紫衣香。","此去非餘事，還歸內道場。","憑師將老倒，一向說滎陽。"]', '["去去楞伽子，春深道路长。","鸟啼青嶂險，花落紫衣香。","此去非餘事，還归內道場。","憑師將老倒，一向说滎陽。"]', '诗', 'shi', '', NULL, '送明覺大師兼寄鄭山人 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a4e4d59-759d-4007-8025-2ab7f56716b5', '廬山尋靈紀不遇', '廬山尋靈紀不遇', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["久別稀相見，深山道益孤。","葉全離大朴，君尚在新吳。","鐘嗄聲飄驛，山頑氣噴湖。","留詩如和得，一望寄前途。"]', '["久別稀相见，深山道益孤。","葉全離大朴，君尚在新吳。","鐘嗄声飄驛，山頑氣噴湖。","留诗如和得，一望寄前途。"]', '诗', 'shi', '', NULL, '廬山尋靈紀不遇 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f449a6b-eb57-4303-9220-5313d7846672', '題曹溪祖師堂', '題曹溪祖師堂', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["皎潔曹溪月，嵯峨七寶林。","空傳智藥記，豈見祖禪心。","信衣非苧麻，白雲無知音。","大哉雙峰溪，萬古青沈沈。"]', '["皎潔曹溪月，嵯峨七寶林。","空傳智藥記，豈见祖禪心。","信衣非苧麻，白云無知音。","大哉雙峰溪，万古青沈沈。"]', '诗', 'shi', '', NULL, '題曹溪祖師堂 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73480f2d-300a-455f-9a5c-777d6f40f3a6', '懷匡山道侶', '懷匡山道侶', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常憶將吾友，穿雲過瀑西。","有碑皆讀徹，無處不相攜。","檉桂株株濕，猨猱箇箇啼。","等閑成遠別，窗月又如珪。"]', '["常憶將吾友，穿云過瀑西。","有碑皆读徹，無处不相携。","檉桂株株濕，猨猱箇箇啼。","等闲成远別，窗月又如珪。"]', '诗', 'shi', '', NULL, '懷匡山道侶 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('553f082e-b6b0-4583-8296-1902d013a9ba', '懷盧延讓', '懷盧延讓', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["冥搜忍飢凍，嗟爾不能休。","幾歎不得力，到頭還白頭。","姓名歸紫府，妻子在滄洲。","又是蟬聲也，如今何處遊。"]', '["冥搜忍飢凍，嗟爾不能休。","幾歎不得力，到头還白头。","姓名归紫府，妻子在滄洲。","又是蟬声也，如今何处游。"]', '诗', 'shi', '', NULL, '懷盧延讓 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f1f4e41-ea61-4c6c-9d42-6c5e769d8ede', '春晚訪鏡湖方干', '春晚訪镜湖方干', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["幽居湖北濱，相訪值殘春。","路遠諸峰雨，時多擉鼈人。","蒸花初釀酒，漁艇劣容身。","莫訝頻來此，伊余亦隱淪。"]', '["幽居湖北濱，相訪值殘春。","路远諸峰雨，时多擉鼈人。","蒸花初釀酒，漁艇劣容身。","莫訝頻来此，伊余亦隐淪。"]', '诗', 'shi', '', NULL, '春晚訪鏡湖方干 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b852117-3c03-433f-9c8e-1d3b7c9ee392', '秋過相思寺', '秋過相思寺', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["見說相思寺，今來似有期。","瘴鄉終有出，天意固難欺。","晝雨先花島，秋雲挂戍旗。","故人多在蜀，不去更何之。"]', '["见说相思寺，今来似有期。","瘴乡終有出，天意固难欺。","晝雨先花島，秋云挂戍旗。","故人多在蜀，不去更何之。"]', '诗', 'shi', '', NULL, '秋過相思寺 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff97bdaf-a4d5-40a5-b55b-53e233cd4beb', '蜀王入大慈寺聽講', '蜀王入大慈寺听講', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["玉節金珂響似雷，水晶宮殿步裴回。","祗緣支遁談經妙，所以許詢都講來。","帝釋鏡中遙仰止，魔軍殿上動崔巍。","千重香擁龍鱗立，五種風生錦繡開。","寬似大溟生日月，秀如四岳出塵埃。","一條紫氣隨高步，九色仙花落古臺。","謝太傅須同八凱，姚梁公可並三台。","登樓喜色禾將熟，望國誠明首不迴。","駕馭英雄如赤子，雌黃賢哲貢瓊瑰。","六條消息心常苦，一劒晶熒敵盡摧。","木鐸聲中天降福，景星光裏地無災。","百千民擁聽經座，始見重天社稷才。"]', '["玉節金珂响似雷，水晶宮殿步裴回。","祗緣支遁談經妙，所以許詢都講来。","帝釋镜中遙仰止，魔軍殿上动崔巍。","千重香擁龙鱗立，五種风生錦繡开。","寬似大溟生日月，秀如四岳出塵埃。","一條紫氣隨高步，九色仙花落古台。","謝太傅須同八凱，姚梁公可並三台。","登楼喜色禾將熟，望国誠明首不迴。","駕馭英雄如赤子，雌黄賢哲貢瓊瑰。","六條消息心常苦，一劒晶熒敵尽摧。","木鐸声中天降福，景星光裏地無災。","百千民擁听經座，始见重天社稷才。"]', '诗', 'shi', '', NULL, '蜀王入大慈寺聽講 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38257a71-72af-4dd8-8120-cee65750abf7', '蜀王登福感寺塔三首 一', '蜀王登福感寺塔三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["天資忠孝佐金輪，香火空王有宿因。","此世喜登金骨塔，前生應是育王身。","封疆歲暮笙歌合，襦袴正初錦繡新。","釋子沾恩無以報，祗擎章句貢平津。"]', '["天資忠孝佐金輪，香火空王有宿因。","此世喜登金骨塔，前生應是育王身。","封疆歲暮笙歌合，襦袴正初錦繡新。","釋子沾恩無以報，祗擎章句貢平津。"]', '诗', 'shi', '', NULL, '蜀王登福感寺塔三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58774bdc-c259-487e-8897-587a215626d1', '蜀王登福感寺塔三首 二', '蜀王登福感寺塔三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["似聖悲增道不窮，憂民憂國契堯聰。","兩髯有雪丹霄外，萬里無塵一望中。","南照微明連莽蒼，峨嵋擁秀接崆峒。","林僧歲月知何幸，還似支公見謝公。"]', '["似聖悲增道不窮，憂民憂国契堯聰。","兩髯有雪丹霄外，万里無塵一望中。","南照微明連莽蒼，峨嵋擁秀接崆峒。","林僧歲月知何幸，還似支公见謝公。"]', '诗', 'shi', '', NULL, '蜀王登福感寺塔三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c383e645-eb47-40e1-b5e5-1471574063e5', '蜀王登福感寺塔三首 三', '蜀王登福感寺塔三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["步步層層孰可陪，相輪邊日照三台。","喜歡烝庶皆相逐，惆悵鑾輿尚未迴。","金鐸撼風天樂近，仙花含露瑞煙開。","一年一度常如此，願見文翁百度來。"]', '["步步層層孰可陪，相輪邊日照三台。","喜歡烝庶皆相逐，惆悵鑾輿尚未迴。","金鐸撼风天乐近，仙花含露瑞煙开。","一年一度常如此，願见文翁百度来。"]', '诗', 'shi', '', NULL, '蜀王登福感寺塔三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f732099-b457-4858-905d-eeda486117f3', '少監三首 一', '少監三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["器琢仙珪美有餘，席珍國寶比難如。","銜花乳燕看調瑟，衣錦佳人侍讀書。","荀氏門風龍變化，謝家庭樹玉扶疎。","即期寰海隆平日，歸佐吾皇侍玉除。"]', '["器琢仙珪美有餘，席珍国寶比难如。","銜花乳燕看調瑟，衣錦佳人侍读书。","荀氏门风龙变化，謝家庭樹玉扶疎。","即期寰海隆平日，归佐吾皇侍玉除。"]', '诗', 'shi', '', NULL, '少監三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d5945e-454b-43ad-9f48-7b44430b5b12', '少監三首 二', '少監三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["益友相隨益自強，趨庭問禮日昭彰。","袍新宮錦千人目，馬駿桃花一巷香。","偏愛曾顏終必及，或如韓白亦無妨。","八龍三虎森如也，萬古千秋瑞聖唐。"]', '["益友相隨益自強，趨庭问禮日昭彰。","袍新宮錦千人目，马駿桃花一巷香。","偏愛曾顏終必及，或如韓白亦無妨。","八龙三虎森如也，万古千秋瑞聖唐。"]', '诗', 'shi', '', NULL, '少監三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e859272-53c0-4bd2-814f-9e5551983999', '少監三首 三', '少監三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["具體而微太少年，鳳毛五色帶非煙。","倚天長劒看無敵，遶樹號猨已應弦。","接士開襟清聖熟，分題得句落花前。","即應出將傳家法，聖澤恩波浩浩然。"]', '["具體而微太少年，鳳毛五色带非煙。","倚天长劒看無敵，遶樹號猨已應弦。","接士开襟清聖熟，分題得句落花前。","即應出將傳家法，聖澤恩波浩浩然。"]', '诗', 'shi', '', NULL, '少監三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc53e776-58ad-4b45-99d6-1798cade7a04', '再到鍾陵作', '再到鍾陵作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["六七年來到豫章，舊遊知己半凋傷。","春風還有花千樹，往事都如夢一場。","無限丘墟侵郭路，幾多臺榭浸湖光。","祗應唯有西山色，依舊崔巍上寺牆。"]', '["六七年来到豫章，旧游知己半凋傷。","春风還有花千樹，往事都如梦一場。","無限丘墟侵郭路，幾多台榭浸湖光。","祗應唯有西山色，依旧崔巍上寺牆。"]', '诗', 'shi', '', NULL, '再到鍾陵作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5ee3dc2-2581-413e-ac6e-643033f074d5', '經弟妹墳', '經弟妹墳', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["淚不曾垂此日垂，山前弟妹塚離離。","年長於吾未得力，家貧拋爾去多時。","鴻衝□□霜中斷，蕙雜黃蒿冢上衰。","恩愛苦情拋未得，不堪回首步遲遲。"]', '["泪不曾垂此日垂，山前弟妹塚離離。","年长於吾未得力，家貧拋爾去多时。","鴻衝□□霜中斷，蕙杂黄蒿冢上衰。","恩愛苦情拋未得，不堪回首步遲遲。"]', '诗', 'shi', '', NULL, '經弟妹墳 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d85496ee-d568-44d2-a8c8-edd45f16bcca', '到蜀與鄭中丞相遇', '到蜀與鄭中丞相遇', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["深隱猶爲未死灰，遠尋知己遇三台。","如何麋鹿群中出，又見鵷鸞天上來。","劒閣霞黏殘雪在，錦江香甚百花開。","謾期王謝來相訪，不是支公出世才。"]', '["深隐猶爲未死灰，远尋知己遇三台。","如何麋鹿群中出，又见鵷鸾天上来。","劒閣霞黏殘雪在，錦江香甚百花开。","謾期王謝来相訪，不是支公出世才。"]', '诗', 'shi', '', NULL, '到蜀與鄭中丞相遇 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c7c7ccf-328c-402f-b249-1e1bdd418372', '別馮使君', '別馮使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["瓦礫文章豈有媒，兩三年祗在金臺。","本師頭白須歸去，太守門清願再來。","皓皓玉霜孤鴈遠，蕭蕭松島片帆開。","從茲林下終無事，唯祗焚香祝上台。"]', '["瓦礫文章豈有媒，兩三年祗在金台。","本師头白須归去，太守门清願再来。","皓皓玉霜孤鴈远，蕭蕭松島片帆开。","從茲林下終無事，唯祗焚香祝上台。"]', '诗', 'shi', '', NULL, '別馮使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86928a21-0110-4362-9446-47d22a7290e3', '上新定宋使君', '上新定宋使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["禪坐吟行誰與同，杉松共在寂寥中。","碧雲詩裏終難到，白藕花經講始終。","水疊山層擎草疏，砧清月苦立霜風。","十年勤苦今酬了，得句桐江識謝公。"]', '["禪坐吟行誰與同，杉松共在寂寥中。","碧云诗裏終难到，白藕花經講始終。","水叠山層擎草疏，砧清月苦立霜风。","十年勤苦今酬了，得句桐江識謝公。"]', '诗', 'shi', '', NULL, '上新定宋使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56f08311-ac21-4463-9892-c25b72fbeef8', '和李判官見新榜爲兄下第', '和李判官见新榜爲兄下第', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["失意荆枝滴淚頻，陟岡何翅不知春。","心中岐路平如砥，天上文章妙入神。","休說宋風迴鷁首，即看雷火燎龍鱗。","從茲相次紅霞裏，留取方書與世人。"]', '["失意荆枝滴泪頻，陟岡何翅不知春。","心中岐路平如砥，天上文章妙入神。","休说宋风迴鷁首，即看雷火燎龙鱗。","從茲相次紅霞裏，留取方书與世人。"]', '诗', 'shi', '', NULL, '和李判官見新榜爲兄下第 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f61dd74-db33-4bea-88a8-f8f6f1ce640d', '送羅鄴赴許昌辟', '送羅鄴赴許昌辟', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["方得論心又別離，黯然江上步遲遲。","不堪迴首崎嶇路，正是寒風皴錯時。","美似郄超終有日，去依劉表更何疑。","前程不少南飛鴈，聊寄新詩慰所思。"]', '["方得論心又別離，黯然江上步遲遲。","不堪迴首崎嶇路，正是寒风皴錯时。","美似郄超終有日，去依劉表更何疑。","前程不少南飞鴈，聊寄新诗慰所思。"]', '诗', 'shi', '', NULL, '送羅鄴赴許昌辟 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e65314-b712-4f10-9886-d9b22f0363ae', '酬韋相公見寄', '酬韋相公见寄', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鹽梅金鼎美調和，詩寄空林問訊多。","秦客弈棊拋已久，楞嚴禪髓更無過。","萬般如幻希先覺，一丈臨山且奈何。","空諷平津好珠玉，不知更得及門麽。"]', '["鹽梅金鼎美調和，诗寄空林问訊多。","秦客弈棊拋已久，楞嚴禪髓更無過。","万般如幻希先覺，一丈臨山且奈何。","空諷平津好珠玉，不知更得及门麽。"]', '诗', 'shi', '', NULL, '酬韋相公見寄 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba5041b-9af1-48f4-bfff-bafa8a9fccb3', '酬張相公見寄', '酬張相公见寄', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["周郎懷抱好知音，常愛山僧物外心。","閉戶不知芳草歇，無能唯擬住山深。","感通未合三生石，騷雅歡擎九轉金。","但似前朝蕭與蔣，老僧風雪亦相尋。"]', '["周郎懷抱好知音，常愛山僧物外心。","閉戶不知芳草歇，無能唯擬住山深。","感通未合三生石，騷雅歡擎九轉金。","但似前朝蕭與蔣，老僧风雪亦相尋。"]', '诗', 'shi', '', NULL, '酬張相公見寄 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d3ec8cc-4c6c-4b3b-9bf1-a308e25e44b5', '酬王相公見贈', '酬王相公见贈', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["孤拙將來豈偶然，不能爲漏滴青蓮。","一從麟筆題牆後，常祗冥心古像前。","九德陶鎔空有跡，六窗清淨始通禪。","今朝幸捧瓊瑤贈，始見玄中更有玄。"]', '["孤拙將来豈偶然，不能爲漏滴青蓮。","一從麟笔題牆後，常祗冥心古像前。","九德陶鎔空有跡，六窗清淨始通禪。","今朝幸捧瓊瑤贈，始见玄中更有玄。"]', '诗', 'shi', '', NULL, '酬王相公見贈 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb6e48a5-51b8-4e70-ae3e-e4f916e1ce26', '酬周相公見贈', '酬周相公见贈', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["三界無家是出家，豈宜拊鳳覩新麻。","幸生白髮逢今聖，曾夢青蓮映玉沙。","境陟名山烹錦水，睡忘東白洞平茶。","喜擎繡段攀金鼎，謝朓餘霞始是霞。"]', '["三界無家是出家，豈宜拊鳳覩新麻。","幸生白髮逢今聖，曾梦青蓮映玉沙。","境陟名山烹錦水，睡忘东白洞平茶。","喜擎繡段攀金鼎，謝朓餘霞始是霞。"]', '诗', 'shi', '', NULL, '酬周相公見贈 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dd0b5f7-7d20-430f-9c63-929fbfce0f3b', '道情偈三首 一', '道情偈三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["崆峒老人專一一，黃梅真叟却無無。","獨坐松根石頭上，四溟無限月輪孤。"]', '["崆峒老人專一一，黄梅真叟却無無。","独坐松根石头上，四溟無限月輪孤。"]', '诗', 'shi', '', NULL, '道情偈三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93a1ed0f-23ff-4e61-809e-d70932a8999f', '道情偈三首 二', '道情偈三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["非色非空非不空，空中真色不玲瓏。","可憐盧大擔柴者，拾得驪珠橐籥中。"]', '["非色非空非不空，空中真色不玲瓏。","可怜盧大擔柴者，拾得驪珠橐籥中。"]', '诗', 'shi', '', NULL, '道情偈三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('817d2135-66c1-49c6-87ee-e350e6309e6f', '道情偈三首 三', '道情偈三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["優鉢羅花萬劫春，頻犂田地絕纖塵。","道吾道者相招好，不是香林採葉人。"]', '["優鉢羅花万劫春，頻犂田地絕纖塵。","道吾道者相招好，不是香林採葉人。"]', '诗', 'shi', '', NULL, '道情偈三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7b5502a-a589-4039-b865-9284dd01a693', '馬上作', '马上作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["柳岸花堤夕照紅，風清襟袖轡璁瓏。","行人莫訝頻迴首，家在凝嵐一點中。"]', '["柳岸花堤夕照紅，风清襟袖轡璁瓏。","行人莫訝頻迴首，家在凝嵐一点中。"]', '诗', 'shi', '', NULL, '馬上作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5399642f-0c00-4bcd-96d7-8108ae7f9a0b', '道中逢乞食老僧', '道中逢乞食老僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["赤椶櫚笠眉毫垂，拄楖栗杖行遲遲。","時人祗施盂中飯，心似白蓮那得知。"]', '["赤椶櫚笠眉毫垂，拄楖栗杖行遲遲。","时人祗施盂中飯，心似白蓮那得知。"]', '诗', 'shi', '', NULL, '道中逢乞食老僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c29e31f6-eb93-4bbf-a61b-9a192baf9ae0', '秋末寄武昌一公', '秋末寄武昌一公', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["見說武昌江上住，柏枯槐朽戰時風。","知師詩癖難醫也，霜灑蘆花明月中。"]', '["见说武昌江上住，柏枯槐朽戰时风。","知師诗癖难醫也，霜灑蘆花明月中。"]', '诗', 'shi', '', NULL, '秋末寄武昌一公 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5d91570-6811-4b44-9bcc-84fd8a3e3817', '陋巷', '陋巷', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["墜葉如花欲滿溝，破籬荒井一蟬幽。","亦知希驥無希者，作麽令人強轉頭。"]', '["墜葉如花欲满溝，破籬荒井一蟬幽。","亦知希驥無希者，作麽令人強轉头。"]', '诗', 'shi', '', NULL, '陋巷 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eabbb105-ed66-40ed-8d2d-c1b4b9e14c49', '終南僧', '終南僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["聲利掀天竟不聞，草衣木食度朝昏。","遙思山雪深一丈，時有仙人來打門。"]', '["声利掀天竟不闻，草衣木食度朝昏。","遙思山雪深一丈，时有仙人来打门。"]', '诗', 'shi', '', NULL, '終南僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad89a50f-b5b7-4342-b3e7-609eb2687613', '聽僧彈琴', '听僧彈琴', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["家近吳王古戰城，海風終日打牆聲。","今朝鄉思渾堆積，琴上聞師大蟹行。"]', '["家近吳王古戰城，海风終日打牆声。","今朝乡思渾堆積，琴上闻師大蟹行。"]', '诗', 'shi', '', NULL, '聽僧彈琴 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ad54d0c-1041-463d-8c8f-d3877fb1792f', '漁者', '漁者', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["風惡波狂身似閑，滿頭霜雪背青山。","相逢略問家何在，回指蘆花滿舍間。"]', '["风惡波狂身似闲，满头霜雪背青山。","相逢略问家何在，回指蘆花满舍间。"]', '诗', 'shi', '', NULL, '漁者 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42bdc79-8105-4556-8ef6-fad6d1d7ac82', '大蜀皇帝潛龍日述聖德詩五首 一', '大蜀皇帝潛龙日述聖德诗五首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["嶽瀆殊祥日月精，入堯金鏡佐休明。","衣嚴黻黼皇恩重，劒折芙蓉紫氣橫。","玉甃金湯山岳峻，花藏臺榭管弦清。","已聞圖上凌煙閣，寵渥穹窿玉不名。"]', '["嶽瀆殊祥日月精，入堯金镜佐休明。","衣嚴黻黼皇恩重，劒折芙蓉紫氣橫。","玉甃金湯山岳峻，花藏台榭管弦清。","已闻圖上凌煙閣，寵渥穹窿玉不名。"]', '诗', 'shi', '', NULL, '大蜀皇帝潛龍日述聖德詩五首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea2d1b3-cb59-4206-bc94-eb0ffa6f1377', '大蜀皇帝潛龍日述聖德詩五首 二', '大蜀皇帝潛龙日述聖德诗五首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["扶持社稷似齊桓，百萬雄師貴可觀。","神智發中真莫測，貢輸天下學應難。","風清鼙角□□□，□肅神龍草木寒。","堪羨蜀民恆有福，太平時節一般般。"]', '["扶持社稷似齊桓，百万雄師貴可观。","神智發中真莫測，貢輸天下学應难。","风清鼙角□□□，□肅神龙草木寒。","堪羨蜀民恆有福，太平时節一般般。"]', '诗', 'shi', '', NULL, '大蜀皇帝潛龍日述聖德詩五首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a901d11-ad9f-4c89-8677-c2423625f016', '大蜀皇帝潛龍日述聖德詩五首 三', '大蜀皇帝潛龙日述聖德诗五首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["珠履三千侍玉除，宮花飄錦早鶯初。","雖然周孔心相似，其奈龔黃政不如。","浩浩歌謠聞禁掖，重重襦袴滿樵漁。","若論朝野艱難日，第一之功美有餘。"]', '["珠履三千侍玉除，宮花飄錦早鶯初。","雖然周孔心相似，其奈龔黄政不如。","浩浩歌謠闻禁掖，重重襦袴满樵漁。","若論朝野艱难日，第一之功美有餘。"]', '诗', 'shi', '', NULL, '大蜀皇帝潛龍日述聖德詩五首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b150e9a4-ca5e-49de-add0-95699f47b394', '大蜀皇帝潛龍日述聖德詩五首 四', '大蜀皇帝潛龙日述聖德诗五首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["紫髯青眼代天才，韓白孫吳稍可陪。","祗見赤心堯日下，豈知真氣梵天來。","聽經瑞雪時時落，登塔天花步步開。","盡祝莊椿同壽考，人間歲月豈能催。"]', '["紫髯青眼代天才，韓白孫吳稍可陪。","祗见赤心堯日下，豈知真氣梵天来。","听經瑞雪时时落，登塔天花步步开。","尽祝莊椿同壽考，人间歲月豈能催。"]', '诗', 'shi', '', NULL, '大蜀皇帝潛龍日述聖德詩五首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8a389cf-4094-41d4-ab89-0c4d5efa24b4', '大蜀皇帝潛龍日述聖德詩五首 五', '大蜀皇帝潛龙日述聖德诗五首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["丈夫勛業正乾坤，麟鳳龜龍盡在門。","西伯最憐耕讓畔，曹參空愛酒盈樽。","心慈爲受金仙囑，髮白緣酬玉砌恩。","從此于門轉高大，可憐子子與孫孫。"]', '["丈夫勛業正乾坤，麟鳳龟龙尽在门。","西伯最怜耕讓畔，曹參空愛酒盈樽。","心慈爲受金仙囑，髮白緣酬玉砌恩。","從此于门轉高大，可怜子子與孫孫。"]', '诗', 'shi', '', NULL, '大蜀皇帝潛龍日述聖德詩五首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e4bb2c4-aa18-4a7e-8600-f459d9933dcf', '陳情獻蜀皇帝', '陳情獻蜀皇帝', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["河北江東處處災，唯聞全蜀勿塵埃。","一缾一鉢垂垂老，千水千山得得來。","奈菀幽棲多勝景，巴歈陳貢媿非才。","自慙林藪龍鍾者，亦得親登郭隗臺。"]', '["河北江东处处災，唯闻全蜀勿塵埃。","一缾一鉢垂垂老，千水千山得得来。","奈菀幽棲多勝景，巴歈陳貢媿非才。","自慙林藪龙鍾者，亦得親登郭隗台。"]', '诗', 'shi', '', NULL, '陳情獻蜀皇帝 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bcec78a-c7c4-4d02-ab9e-0afa04f290ed', '壽春節進大蜀皇帝五首 一', '壽春節進大蜀皇帝五首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["上玄大帝降坤維，箕尾爲臣副聖期。","豈比赤光盈室日，全同白象下天時。","文經武緯包三古，日角龍顏遏四夷。","今日降神天上會，願將天福比須彌。"]', '["上玄大帝降坤維，箕尾爲臣副聖期。","豈比赤光盈室日，全同白象下天时。","文經武緯包三古，日角龙顏遏四夷。","今日降神天上會，願將天福比須彌。"]', '诗', 'shi', '', NULL, '壽春節進大蜀皇帝五首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcf8b768-0c7a-42ad-9470-e1a5b10b55d7', '壽春節進大蜀皇帝五首 二', '壽春節進大蜀皇帝五首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["異香滴露降紛紛，紫電環樞照禁門。","先冠百王臨億兆，後稱十號震乾坤。","羲軒之道方爲道，草木沾恩始是恩。","今以謏才歌睿德，猶如飲海妙難論。"]', '["異香滴露降紛紛，紫電环樞照禁门。","先冠百王臨億兆，後稱十號震乾坤。","羲軒之道方爲道，草木沾恩始是恩。","今以謏才歌睿德，猶如饮海妙难論。"]', '诗', 'shi', '', NULL, '壽春節進大蜀皇帝五首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4288f550-33e5-4ae8-99aa-5db9976c067d', '壽春節進大蜀皇帝五首 三', '壽春節進大蜀皇帝五首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["茂祉遐宣勝事幷，薰風微入舜弦清。","四洲不必歸王化，一統那能計聖情。","合合鼓鐘膏雨滴，峨峨宮闕瑞煙橫。","西逾昆岳東連海，誰不梯山賀聖明。"]', '["茂祉遐宣勝事幷，薰风微入舜弦清。","四洲不必归王化，一統那能計聖情。","合合鼓鐘膏雨滴，峨峨宮闕瑞煙橫。","西逾昆岳东連海，誰不梯山賀聖明。"]', '诗', 'shi', '', NULL, '壽春節進大蜀皇帝五首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6fb92d5-4635-447d-b8d9-91bec5b341d0', '壽春節進大蜀皇帝五首 四', '壽春節進大蜀皇帝五首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["遠人玉帛盡來歸，及物天慈物物肥。","春力遍時皆甲拆，王言聞者盡光輝。","家家錦繡香醪熟，處處笙歌乳燕飛。","爲報蜀皇勤禱祝，聖明天子古今稀。"]', '["远人玉帛尽来归，及物天慈物物肥。","春力遍时皆甲拆，王言闻者尽光輝。","家家錦繡香醪熟，处处笙歌乳燕飞。","爲報蜀皇勤禱祝，聖明天子古今稀。"]', '诗', 'shi', '', NULL, '壽春節進大蜀皇帝五首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d21a3e31-5782-409b-aea0-4f978a64de1b', '壽春節進大蜀皇帝五首 五', '壽春節進大蜀皇帝五首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["積劫修來似煉金，爲皇爲帝萬靈欽。","能當濁世爲清世，始見君心是佛心。","九野黎民耕浩浩，百蠻朝騎日駸駸。","今朝獻壽將何比，願似莊椿一萬尋。"]', '["積劫修来似煉金，爲皇爲帝万靈欽。","能當濁世爲清世，始见君心是佛心。","九野黎民耕浩浩，百蠻朝騎日駸駸。","今朝獻壽將何比，願似莊椿一万尋。"]', '诗', 'shi', '', NULL, '壽春節進大蜀皇帝五首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4bbb7b1-783a-4766-a175-baf5d41ae7bc', '對雪寄新定馮使君二首 一', '对雪寄新定馮使君二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["仙掌空思歸未能，焚香冥目對殘燈。","豈知瑞雪千山合，空覺春寒半夜增。","翳月素雲埋粉堞，堆巢孤鶴下金繩。","因思太守憂民切，吟對瓊枝喜不勝。"]', '["仙掌空思归未能，焚香冥目对殘灯。","豈知瑞雪千山合，空覺春寒半夜增。","翳月素云埋粉堞，堆巢孤鹤下金繩。","因思太守憂民切，吟对瓊枝喜不勝。"]', '诗', 'shi', '', NULL, '對雪寄新定馮使君二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ad7074-b7ac-4a3d-9e06-dbdb29b4fd40', '對雪寄新定馮使君二首 二', '对雪寄新定馮使君二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["政化由來通上靈，豐年祥瑞滿窗明。","氣嚴坐久燈凝燄，片大更深屋作聲。","飄掩煙霞何處去，欹斜杉竹向簾傾。","雪林中客雖無事，還有新詩半夜成。"]', '["政化由来通上靈，豐年祥瑞满窗明。","氣嚴坐久灯凝燄，片大更深屋作声。","飄掩煙霞何处去，欹斜杉竹向簾傾。","雪林中客雖無事，還有新诗半夜成。"]', '诗', 'shi', '', NULL, '對雪寄新定馮使君二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4cdbedc-53b2-48d8-ab71-3f428ee8728d', '送劉相公朝覲二首 一', '送劉相公朝覲二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["九苞仙瑞曜垂衣，一品高標百辟師。","魏相十思常自切，曹溪一句幾生知。","久交玉帳雖難別，須佐金輪去已遲。","唯杜荆州最惆悵，柳門迴首落花時。"]', '["九苞仙瑞曜垂衣，一品高標百辟師。","魏相十思常自切，曹溪一句幾生知。","久交玉帳雖难別，須佐金輪去已遲。","唯杜荆州最惆悵，柳门迴首落花时。"]', '诗', 'shi', '', NULL, '送劉相公朝覲二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f734d6d5-611d-452a-a638-354e2555cbba', '送劉相公朝覲二首 二', '送劉相公朝覲二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["急徵祗是再登庸，生意人心萬國同。","燮理久徵殷傅說，譚真欲過李玄通。","程穿峴首春光老，馬速商於曙色紅。","從此龍顏又應瘦，寰瀛俱荷代天功。"]', '["急徵祗是再登庸，生意人心万国同。","燮理久徵殷傅说，譚真欲過李玄通。","程穿峴首春光老，马速商於曙色紅。","從此龙顏又應瘦，寰瀛俱荷代天功。"]', '诗', 'shi', '', NULL, '送劉相公朝覲二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba3bf248-f778-4836-8541-71389aed9d6a', '避寇遊成福山院', '避寇游成福山院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["成福僧留不擬歸，獼猴菌嫩豆苗肌。","那堪蠶月偏多雨，況復衢城未解圍。","翠擁槿籬泉亂入，雲開花島雉雙飛。","堪嗟大似悠悠者，祗向詩中話息機。"]', '["成福僧留不擬归，獼猴菌嫩豆苗肌。","那堪蠶月偏多雨，況复衢城未解圍。","翠擁槿籬泉亂入，云开花島雉雙飞。","堪嗟大似悠悠者，祗向诗中話息機。"]', '诗', 'shi', '', NULL, '避寇遊成福山院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d85b30b5-a548-45c0-ae43-d0f1ed57cd45', '別李常侍', '別李常侍', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["楚水和煙海浪通，又擎杯錫去山東。","道情雖擬攀孤鶴，詩業那堪至遠公。","夢入深雲香雨滴，吟搜殘雪石林空。","朱門再到知何日，一片征帆萬里風。"]', '["楚水和煙海浪通，又擎杯錫去山东。","道情雖擬攀孤鹤，诗業那堪至远公。","梦入深云香雨滴，吟搜殘雪石林空。","朱门再到知何日，一片征帆万里风。"]', '诗', 'shi', '', NULL, '別李常侍 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71ba0446-36d4-4537-ad19-1497eff98180', '送鄭閣赴閩辟', '送鄭閣赴閩辟', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["便便書腹德無鄰，健筆從知又入閩。","鸚鵡才須歸紫禁，真珠履不稱清貧。","武夷山夾仙霞薄，螺女潭通海樹春。","從此應多好消息，莫忘江上一閑人。"]', '["便便书腹德無鄰，健笔從知又入閩。","鸚鵡才須归紫禁，真珠履不稱清貧。","武夷山夾仙霞薄，螺女潭通海樹春。","從此應多好消息，莫忘江上一闲人。"]', '诗', 'shi', '', NULL, '送鄭閣赴閩辟 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('604ec555-b453-4d51-ad01-dda96a0012ee', '寄信州張使君', '寄信州張使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["水壇檉殿地含煙，領鶴行吟積翠間。","數閣涼颸終日去，滿懷明月上方還。","時來自有鵷鸞識，道在從如草木閑。","唯羨靈溪賢太守，一麾清坐似深山。"]', '["水壇檉殿地含煙，領鹤行吟積翠间。","數閣涼颸終日去，满懷明月上方還。","时来自有鵷鸾識，道在從如草木闲。","唯羨靈溪賢太守，一麾清坐似深山。"]', '诗', 'shi', '', NULL, '寄信州張使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99af7127-342b-4ed6-a7e5-28037397cad2', '春末寄周璉', '春末寄周璉', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["暮角[含]風雨氣曛，寂寥莓翠上衣巾。","道情不向鶯花薄，詩意自如天地春。","夢入亂峰仍履雪，吟看芳草祗思人。","手中孤桂月中在，來聽泉聲莫厭頻。"]', '["暮角[含]风雨氣曛，寂寥莓翠上衣巾。","道情不向鶯花薄，诗意自如天地春。","梦入亂峰仍履雪，吟看芳草祗思人。","手中孤桂月中在，来听泉声莫厭頻。"]', '诗', 'shi', '', NULL, '春末寄周璉 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97bfe5b2-80fb-405a-b843-931d3bc7d632', '讀吳越春秋', '读吳越春秋', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["猶來吳越盡須慙，背德違盟又信讒。","宰嚭一言終殺伍，大夫七事祗須三。","功成獻壽歌飄雪，誰愛扁舟水似藍。","今日雄圖又何在，野花香徑鳥喃喃。"]', '["猶来吳越尽須慙，背德違盟又信讒。","宰嚭一言終殺伍，大夫七事祗須三。","功成獻壽歌飄雪，誰愛扁舟水似藍。","今日雄圖又何在，野花香徑鸟喃喃。"]', '诗', 'shi', '', NULL, '讀吳越春秋 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('552d7977-f7c8-4c32-9291-596c7f6190b1', '春遊靈泉寺', '春游靈泉寺', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["水蹴危梁翠擁沙，鐘聲微徑入深花。","嘴紅澗鳥啼芳草，頭白山僧自扞茶。","松色摧殘遭賊火，水聲幽咽落人家。","因尋古跡空惆悵，滿袖香風白日斜。"]', '["水蹴危梁翠擁沙，鐘声微徑入深花。","嘴紅澗鸟啼芳草，头白山僧自扞茶。","松色摧殘遭賊火，水声幽咽落人家。","因尋古跡空惆悵，满袖香风白日斜。"]', '诗', 'shi', '', NULL, '春遊靈泉寺 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('671383d6-8372-4465-9b59-ced99aad4d1a', '歸東陽臨岐上杜使君七首 一', '归东陽臨岐上杜使君七首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["小謝清高大謝才，聖君令泰此方來。","一從到後常無事，鈴閣公庭滿綠苔。"]', '["小謝清高大謝才，聖君令泰此方来。","一從到後常無事，鈴閣公庭满綠苔。"]', '诗', 'shi', '', NULL, '歸東陽臨岐上杜使君七首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1c2e8c9-08fa-4b1a-9348-f976a3f13bac', '歸東陽臨岐上杜使君七首 二', '归东陽臨岐上杜使君七首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["紅錦帳中歌白雪，烏皮几畔撫青英。","不知何物爲心地，賽却澄江徹底清。"]', '["紅錦帳中歌白雪，烏皮几畔撫青英。","不知何物爲心地，賽却澄江徹底清。"]', '诗', 'shi', '', NULL, '歸東陽臨岐上杜使君七首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39590d50-ca69-4826-b31b-7021a509798b', '歸東陽臨岐上杜使君七首 三', '归东陽臨岐上杜使君七首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["誰報田中有黑蟲，一家齋戒減仙容。","分憂若也皆如此，天下家家有剩舂。"]', '["誰報田中有黑蟲，一家斋戒減仙容。","分憂若也皆如此，天下家家有剩舂。"]', '诗', 'shi', '', NULL, '歸東陽臨岐上杜使君七首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e3b7a62-8616-4d44-a738-a072f74fe6a9', '歸東陽臨岐上杜使君七首 四', '归东陽臨岐上杜使君七首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["憂民心切出衝炎，禾稼如雲喜氣兼。","林下閑人亦何幸，也隨旌斾到銀尖。"]', '["憂民心切出衝炎，禾稼如云喜氣兼。","林下闲人亦何幸，也隨旌斾到銀尖。"]', '诗', 'shi', '', NULL, '歸東陽臨岐上杜使君七首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b687322-23b5-4f5f-8826-dd5766026a62', '歸東陽臨岐上杜使君七首 五', '归东陽臨岐上杜使君七首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["方恐獄中桃樹出，忽聞枯木却生煙。","褚祥爲郡曾如此，却恐當時是偶然。"]', '["方恐獄中桃樹出，忽闻枯木却生煙。","褚祥爲郡曾如此，却恐當时是偶然。"]', '诗', 'shi', '', NULL, '歸東陽臨岐上杜使君七首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33bb62b-4f4d-499b-af98-c0747eae5db2', '歸東陽臨岐上杜使君七首 六', '归东陽臨岐上杜使君七首 六', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["枯骨縱橫遍水湄，盡收爲冢碧參差。","分明爲報精靈輩，好送旌旗到鳳池。"]', '["枯骨縱橫遍水湄，尽收爲冢碧參差。","分明爲報精靈輩，好送旌旗到鳳池。"]', '诗', 'shi', '', NULL, '歸東陽臨岐上杜使君七首 六 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c869dcf8-cf16-43a1-9e2d-e0f649463b5e', '歸東陽臨岐上杜使君七首 七', '归东陽臨岐上杜使君七首 七', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["捨魯依劉一片雲，好風吹去遠纖塵。","猶期明月清風夜，來作西園第八人。"]', '["捨魯依劉一片云，好风吹去远纖塵。","猶期明月清风夜，来作西园第八人。"]', '诗', 'shi', '', NULL, '歸東陽臨岐上杜使君七首 七 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70eb6649-830c-491b-8286-304cf375d1e3', '春', '春', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["自來自去動洪鑪，無象無私無處無。","迴鴈不多消氣力，染花應最費工夫。","溟濛便恨豪家惜，濃暖深爲政筆驅。","莫訝相逢只添睡，伊余心不在榮枯。"]', '["自来自去动洪鑪，無象無私無处無。","迴鴈不多消氣力，染花應最費工夫。","溟濛便恨豪家惜，濃暖深爲政笔驱。","莫訝相逢只添睡，伊余心不在榮枯。"]', '诗', 'shi', '', NULL, '春 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e110c034-7bad-46d1-b838-25d0a4e57230', '聞迎真身', '闻迎真身', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["四海無波八表臣，恭聞今歲禮真身。","七重鏁未開今鑰，五色光先入紫宸。","丹鳳樓臺飄瑞雪，岐陽草木亞香塵。","可憐優鉢羅花樹，三十年來一度春。"]', '["四海無波八表臣，恭闻今歲禮真身。","七重鏁未开今鑰，五色光先入紫宸。","丹鳳楼台飄瑞雪，岐陽草木亞香塵。","可怜優鉢羅花樹，三十年来一度春。"]', '诗', 'shi', '', NULL, '聞迎真身 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc31113-d522-415b-aac0-71743f16c0b2', '灞陵戰叟', '灞陵戰叟', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["劍刓秋水鬢梳霜，迴首胡天與恨長。","官竟不封右校尉，鬬曾生挾左賢王。","尋班超傳空垂淚，讀李陵書更斷腸。","今日灞陵陵畔見，春風花霧共茫茫。"]', '["劍刓秋水鬢梳霜，迴首胡天與恨长。","官竟不封右校尉，鬬曾生挾左賢王。","尋班超傳空垂泪，读李陵书更斷腸。","今日灞陵陵畔见，春风花霧共茫茫。"]', '诗', 'shi', '', NULL, '灞陵戰叟 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6acd38f-908a-455e-94ab-9c7a18999da6', '遇道者', '遇道者', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鶴骨松筋風貌殊，不言名姓絕榮枯。","尋常藜杖九衢裏，莫是商山一皓無。","身帶煙霞游汗漫，藥兼神鬼在葫蘆。","只應張果支公輩，時復相逢醉海隅。"]', '["鹤骨松筋风貌殊，不言名姓絕榮枯。","尋常藜杖九衢裏，莫是商山一皓無。","身带煙霞游汗漫，藥兼神鬼在葫蘆。","只應張果支公輩，时复相逢醉海隅。"]', '诗', 'shi', '', NULL, '遇道者 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35753cf7-66ca-4520-98be-235ba949a922', '贈鍾陵陳處士', '贈鍾陵陳处士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["否極方生社稷才，唯譚帝道鄙梯媒。","高吟千首精怪動，長嘯一聲天地開。","湖上獨居多草木，山前頻醉過風雷。","吾皇仄席求賢久，莫待徵書兩度來。"]', '["否極方生社稷才，唯譚帝道鄙梯媒。","高吟千首精怪动，长嘯一声天地开。","湖上独居多草木，山前頻醉過风雷。","吾皇仄席求賢久，莫待徵书兩度来。"]', '诗', 'shi', '', NULL, '贈鍾陵陳處士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc32f43-980e-48b2-84f5-27d4db2b3fb0', '懷鄰叟', '懷鄰叟', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常思東溪[龐]眉翁，是非不解兩頰紅。","桔橰打水聲嘎嘎，紫芋白薤肥濛濛。","鷗鴨靜遊深竹裏，兒孫多在好花中。","千門萬戶皆車馬，誰愛如斯太古風。"]', '["常思东溪[龐]眉翁，是非不解兩頰紅。","桔橰打水声嘎嘎，紫芋白薤肥濛濛。","鷗鴨静游深竹裏，兒孫多在好花中。","千门万戶皆车马，誰愛如斯太古风。"]', '诗', 'shi', '', NULL, '懷鄰叟 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6363771-d1dc-446c-b97b-5065a5a05433', '贈軒轅先生', '贈軒轅先生', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["曾親文景上金鑾，語共容城語一般。","久向紅霞居不出，若非清世見應難。","滿鑪藥熟分仙盡，幾局棊終看海乾。","略問先生真甲子，只言弟子是劉安。"]', '["曾親文景上金鑾，語共容城語一般。","久向紅霞居不出，若非清世见應难。","满鑪藥熟分仙尽，幾局棊終看海乾。","略问先生真甲子，只言弟子是劉安。"]', '诗', 'shi', '', NULL, '贈軒轅先生 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43d1a1c6-5d39-4676-954c-afcd0e0f047e', '偶作因懷山中道侶', '偶作因懷山中道侶', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["是是非非竟不真，桃花流水送青春。","姓劉姓項今何在，爭利爭名愁殺人。","必竟輸他常寂默，只應贏得苦沈淪。","深雲道者相思否，歸去來兮湘水濱。"]', '["是是非非竟不真，桃花流水送青春。","姓劉姓項今何在，爭利爭名愁殺人。","必竟輸他常寂默，只應贏得苦沈淪。","深云道者相思否，归去来兮湘水濱。"]', '诗', 'shi', '', NULL, '偶作因懷山中道侶 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('757feaf5-4233-4d55-aa95-744d2a56c94b', '送新羅人及第歸', '送新羅人及第归', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["捧桂香和紫禁煙，遠鄉程徹巨鼇邊。","莫言挂席飛連夜，見說無風即數年。","衣上日光真是火，島旁魚骨大於船。","到鄉必遇來王使，與作唐書寄一篇。"]', '["捧桂香和紫禁煙，远乡程徹巨鼇邊。","莫言挂席飞連夜，见说無风即數年。","衣上日光真是火，島旁鱼骨大於船。","到乡必遇来王使，與作唐书寄一篇。"]', '诗', 'shi', '', NULL, '送新羅人及第歸 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d3f453c-6a9d-4c62-893d-da291b4c1e70', '送新羅衲僧', '送新羅衲僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["扶桑枝西真氣奇，古人呼爲師子兒。","六環金錫輕擺撼，萬仞雪嶠空參差。","枕上已無鄉國夢，囊中猶挈石頭碑。","多慙不便隨高步，正是風清無事時。"]', '["扶桑枝西真氣奇，古人呼爲師子兒。","六环金錫轻擺撼，万仞雪嶠空參差。","枕上已無乡国梦，囊中猶挈石头碑。","多慙不便隨高步，正是风清無事时。"]', '诗', 'shi', '', NULL, '送新羅衲僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('955e7f76-91e8-414d-9925-4eddaa09e2fb', '春晚桐江上閑望作', '春晚桐江上闲望作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["江上車聲落日催，紛紛擾擾起紅埃。","更無人望青山立，空有帆衝夜色來。","沙鳥似雲鐘外去，汀花如火雨中開。","可憐瀟灑鴟夷子，散髮扁舟去不迴。"]', '["江上车声落日催，紛紛擾擾起紅埃。","更無人望青山立，空有帆衝夜色来。","沙鸟似云鐘外去，汀花如火雨中开。","可怜瀟灑鴟夷子，散髮扁舟去不迴。"]', '诗', 'shi', '', NULL, '春晚桐江上閑望作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88bace35-b989-4721-bf37-255f8a673b40', '商山道者', '商山道者', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["五千言外得玄音，石屋寒栖隔雪林。","多傍松風梳綠髮，只燒崖藥點黃金。","澄潭龍氣來縈砌，月冷星精下聽琴。","曾夢先生非此處，碧桃溪上紫煙深。"]', '["五千言外得玄音，石屋寒栖隔雪林。","多傍松风梳綠髮，只燒崖藥点黄金。","澄潭龙氣来縈砌，月冷星精下听琴。","曾梦先生非此处，碧桃溪上紫煙深。"]', '诗', 'shi', '', NULL, '商山道者 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f2ce6c-0e04-4bff-a56d-a32453c6da66', '聞許棠及第因寄桂雍', '闻許棠及第因寄桂雍', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["時清道合出塵埃，清苦爲詩不杖媒。","今日桂枝平折得，幾年春色併將來。","勢扶九萬風初極，名到三山花正開。","更有平人居蟄屋，還應爲作一聲雷。"]', '["时清道合出塵埃，清苦爲诗不杖媒。","今日桂枝平折得，幾年春色併將来。","勢扶九万风初極，名到三山花正开。","更有平人居蟄屋，還應爲作一声雷。"]', '诗', 'shi', '', NULL, '聞許棠及第因寄桂雍 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8de2b80-8047-4533-94de-f08e493d446f', '瀔江秋居作', '瀔江秋居作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["無事相關性自攄，庭前拾葉等閑書。","青山萬里竟不足，好竹數竿涼有餘。","近看老經加澹泊，欲歸少室復何如。","面前小沼清如鏡，終養琴高赤鯉魚。"]', '["無事相关性自攄，庭前拾葉等闲书。","青山万里竟不足，好竹數竿涼有餘。","近看老經加澹泊，欲归少室复何如。","面前小沼清如镜，終養琴高赤鯉鱼。"]', '诗', 'shi', '', NULL, '瀔江秋居作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('841762ef-596e-434e-9c6c-a6761073122a', '上縉雲段使君', '上縉云段使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["清畏人知人盡知，縉雲三載得宣尼。","活民刀尺雖無象，出世文章豈有師。","朮氣芝香粘甕榼，雲痕翠點滿旌旗。","今朝暫到金臺上，頗覺心如太古時。"]', '["清畏人知人尽知，縉云三載得宣尼。","活民刀尺雖無象，出世文章豈有師。","朮氣芝香粘甕榼，云痕翠点满旌旗。","今朝暫到金台上，頗覺心如太古时。"]', '诗', 'shi', '', NULL, '上縉雲段使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('744fa8c8-bf75-46c1-9963-63d7e94ba1b8', '春末蘭谿道中作', '春末蘭谿道中作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山花零落紅與緋，汀煙濛茸江水肥。","人擔犂鋤細雨歇，路入桑柘斜陽微。","深喜東州云寇去，不知西狩何時歸？","清平時節何時是，轉覺人心與道違。"]', '["山花零落紅與緋，汀煙濛茸江水肥。","人擔犂鋤細雨歇，路入桑柘斜陽微。","深喜东州云寇去，不知西狩何时归？","清平时節何时是，轉覺人心與道違。"]', '诗', 'shi', '', NULL, '春末蘭谿道中作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c185ed02-a354-440e-a938-f3c04c9a5bd0', '野居偶作', '野居偶作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["高談清虛即是家，何須須占好煙霞。","無心於道道自得，有意向人人轉賒。","風觸好花文錦落，砌橫流水玉琴斜。","但令如此還如此，誰羨前程未可涯。"]', '["高談清虛即是家，何須須占好煙霞。","無心於道道自得，有意向人人轉賒。","风觸好花文錦落，砌橫流水玉琴斜。","但令如此還如此，誰羨前程未可涯。"]', '诗', 'shi', '', NULL, '野居偶作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dcf75a4-3924-4eae-8185-dd2d0e7cfe83', '再遊東林寺作五首 一', '再游东林寺作五首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["臺殿參差聳瑞煙，桂花飄雪水潺潺。","莫疑遠去無消息，七萬餘年始半年。"]', '["台殿參差聳瑞煙，桂花飄雪水潺潺。","莫疑远去無消息，七万餘年始半年。"]', '诗', 'shi', '', NULL, '再遊東林寺作五首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319369ae-aac6-4019-b076-3984878341e3', '再遊東林寺作五首 二', '再游东林寺作五首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["桓玄舊輦殘雲濕，耶舍孤墳落照遲。","有箇山僧倚松睡，恐人來取白猨兒。"]', '["桓玄旧輦殘云濕，耶舍孤墳落照遲。","有箇山僧倚松睡，恐人来取白猨兒。"]', '诗', 'shi', '', NULL, '再遊東林寺作五首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ebed5e-3909-4a64-908b-cea527a6fe27', '再遊東林寺作五首 三', '再游东林寺作五首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["玉像珠龕香陣橫，錦霞多傍石牆生。","辟蛇行者今何在，花裏唯聞鳩鳥聲。"]', '["玉像珠龕香陣橫，錦霞多傍石牆生。","辟蛇行者今何在，花裏唯闻鳩鸟声。"]', '诗', 'shi', '', NULL, '再遊東林寺作五首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a3843a-37d2-43f1-8555-2714c6b40684', '再遊東林寺作五首 四', '再游东林寺作五首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["愛陶長官醉兀兀，送陸道士行遲遲。","買酒過溪皆破戒，斯何人斯師如斯。"]', '["愛陶长官醉兀兀，送陸道士行遲遲。","買酒過溪皆破戒，斯何人斯師如斯。"]', '诗', 'shi', '', NULL, '再遊東林寺作五首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d43d699b-2166-40fb-8edb-a89ee8a57567', '再遊東林寺作五首 五', '再游东林寺作五首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["白薝蔔花露滴滴，紅苾芻草香濛濛。","田地更無塵一點，是何人合住其中。"]', '["白薝蔔花露滴滴，紅苾芻草香濛濛。","田地更無塵一点，是何人合住其中。"]', '诗', 'shi', '', NULL, '再遊東林寺作五首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83059f64-45b6-4c4d-aa5b-7bef179837d7', '題蘭江言上人院二首 一', '題蘭江言上人院二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一生只著一麻衣，道業還欺習彥威。","手把新詩說山夢，石橋天柱雪霏霏。"]', '["一生只著一麻衣，道業還欺習彥威。","手把新诗说山梦，石橋天柱雪霏霏。"]', '诗', 'shi', '', NULL, '題蘭江言上人院二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('185a314c-a93c-4015-bdb4-2ec7df744c16', '題蘭江言上人院二首 二', '題蘭江言上人院二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["只是危吟坐翠層，門前岐路自崩騰。","青雲名士時相訪，茶煮西峰瀑布冰。"]', '["只是危吟坐翠層，门前岐路自崩腾。","青云名士时相訪，茶煮西峰瀑布冰。"]', '诗', 'shi', '', NULL, '題蘭江言上人院二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d18a79-0381-4cf6-9b51-c73b61b2bcc9', '中秋十五夜月', '中秋十五夜月', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["噀雪噴霜滿碧虛，王孫公子翫相呼。","從來天匠爲輪足，自是人心此夜餘。","靜入萬家危露滴，清埋衆象呌鴻孤。","坐來惟覺情無極，何況三湘與五湖。"]', '["噀雪噴霜满碧虛，王孫公子翫相呼。","從来天匠爲輪足，自是人心此夜餘。","静入万家危露滴，清埋衆象呌鴻孤。","坐来惟覺情無極，何況三湘與五湖。"]', '诗', 'shi', '', NULL, '中秋十五夜月 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c0b41c1-26f3-4792-8b61-34b1d6a29f4b', '鷺鷥有懷', '鷺鷥有懷', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["粉魄霜華爲爾枯，鴛鴦相伴更堪圖。","愛來沙島遺銀屋，終作金籠養雪雛。","栖宿必多清瀨夢，品流還次白猨徒。","今朝不覺頻回首，曾伴瑤花近玉壺。"]', '["粉魄霜华爲爾枯，鴛鴦相伴更堪圖。","愛来沙島遺銀屋，終作金籠養雪雛。","栖宿必多清瀨梦，品流還次白猨徒。","今朝不覺頻回首，曾伴瑤花近玉壺。"]', '诗', 'shi', '', NULL, '鷺鷥有懷 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48cc69b5-d101-4406-85fc-6bc8635d19b1', '東陽罹亂後懷王慥使君五首 一', '东陽罹亂後懷王慥使君五首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["昨來祗對漢諸侯，勝事消磨不自由。","裂地鼓鼙軍□急，連天烽火陣雲秋。","砍毛淬劍雖無數，歃血爲盟不到頭。","誰爲今朝奉明主，使君司戶在隋州。"]', '["昨来祗对漢諸侯，勝事消磨不自由。","裂地鼓鼙軍□急，連天烽火陣云秋。","砍毛淬劍雖無數，歃血爲盟不到头。","誰爲今朝奉明主，使君司戶在隋州。"]', '诗', 'shi', '', NULL, '東陽罹亂後懷王慥使君五首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c510d8ec-3628-4b20-8c48-7c1a81556a88', '東陽罹亂後懷王慥使君五首 二', '东陽罹亂後懷王慥使君五首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["只報精兵過大河，東西南北殺人多。","可憐白日渾如此，來似蝗蟲爭奈何。","天意豈應容版亂，人心都改太凋訛。","不勝惆悵還惆悵，一曲東風月胯歌。"]', '["只報精兵過大河，东西南北殺人多。","可怜白日渾如此，来似蝗蟲爭奈何。","天意豈應容版亂，人心都改太凋訛。","不勝惆悵還惆悵，一曲东风月胯歌。"]', '诗', 'shi', '', NULL, '東陽罹亂後懷王慥使君五首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38145034-fc16-41d1-9911-66ebc4e7e388', '東陽罹亂後懷王慥使君五首 三', '东陽罹亂後懷王慥使君五首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["爲郡無如王使君，一家清冷似雲根。","貨財不入崔洪口，俎豆嘗聞夫子言。","鬚髮坐成三載雪，黎氓空負二天恩。","不堪西望西風起，縱火崑崙誰爲論。"]', '["爲郡無如王使君，一家清冷似云根。","貨財不入崔洪口，俎豆嘗闻夫子言。","鬚髮坐成三載雪，黎氓空負二天恩。","不堪西望西风起，縱火崑崙誰爲論。"]', '诗', 'shi', '', NULL, '東陽罹亂後懷王慥使君五首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f54379d-e75a-4c43-b5b9-ebeeff5321a7', '東陽罹亂後懷王慥使君五首 四', '东陽罹亂後懷王慥使君五首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["魄懾魂飛骨亦銷，此魂此魄亦難招。","黃今白玉家家盡，繡闥雕甍處處燒。","驚動乾坤常黯慘，深藏山岳亦傾搖。","恭聞國有英雄將，擬把何心荅聖朝。"]', '["魄懾魂飞骨亦銷，此魂此魄亦难招。","黄今白玉家家尽，繡闥雕甍处处燒。","驚动乾坤常黯慘，深藏山岳亦傾搖。","恭闻国有英雄將，擬把何心荅聖朝。"]', '诗', 'shi', '', NULL, '東陽罹亂後懷王慥使君五首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba5f771c-102b-4bb2-9cb5-5f5e69558390', '東陽罹亂後懷王慥使君五首 五', '东陽罹亂後懷王慥使君五首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["不是龔黃覆育才，即須清苦遠塵埃。","無人與奏吾皇去，致亂唯因酷吏來。","刳剝生靈爲事業，巧通毫譖作梯媒。","令人轉憶王夫子，一片真風去不迴。"]', '["不是龔黄覆育才，即須清苦远塵埃。","無人與奏吾皇去，致亂唯因酷吏来。","刳剝生靈爲事業，巧通毫譖作梯媒。","令人轉憶王夫子，一片真风去不迴。"]', '诗', 'shi', '', NULL, '東陽罹亂後懷王慥使君五首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92382e59-eaa8-4f9c-b5b7-75790a1fe3a0', '秋夜懷嵩少因寄洛中舊知', '秋夜懷嵩少因寄洛中旧知', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鑪爇旃檀不稱貧，霏霏玉露濕禪巾。","紫金地上三更月，紅藕香中一病身。","少室少年偏入夢，多時多事去無因。","如今憔悴頭成雪，空想嵯峨羨故人。"]', '["鑪爇旃檀不稱貧，霏霏玉露濕禪巾。","紫金地上三更月，紅藕香中一病身。","少室少年偏入梦，多时多事去無因。","如今憔悴头成雪，空想嵯峨羨故人。"]', '诗', 'shi', '', NULL, '秋夜懷嵩少因寄洛中舊知 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ab56be7-54bf-4efe-a025-01a42ab67c64', '避地毘陵寒月上孫徽使君兼寄東陽王使君三首 一', '避地毘陵寒月上孫徽使君兼寄东陽王使君三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一到毘陵心更勞，冷吟閑步擁雲袍。","豈緣思妙塵埃少，自是風清物態高。","野色疎黃連楚甸，故山奇碧隔河橋。","終須愚谷中安致，不是人間好羽毛。"]', '["一到毘陵心更勞，冷吟闲步擁云袍。","豈緣思妙塵埃少，自是风清物態高。","野色疎黄連楚甸，故山奇碧隔河橋。","終須愚谷中安致，不是人间好羽毛。"]', '诗', 'shi', '', NULL, '避地毘陵寒月上孫徽使君兼寄東陽王使君三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daec1866-f2ca-41f1-abf5-d23b024c1eab', '避地毘陵寒月上孫徽使君兼寄東陽王使君三首 二', '避地毘陵寒月上孫徽使君兼寄东陽王使君三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常憶雙溪八詠前，講詩論道接清賢。","文欺白鳳真難及，藥撚紅蕖豈偶然。","花濕瑞煙粘玉磬，簾垂幽鳥啄苔錢。","自憐不是悠悠者，吟嚼真風二十年。"]', '["常憶雙溪八詠前，講诗論道接清賢。","文欺白鳳真难及，藥撚紅蕖豈偶然。","花濕瑞煙粘玉磬，簾垂幽鸟啄苔錢。","自怜不是悠悠者，吟嚼真风二十年。"]', '诗', 'shi', '', NULL, '避地毘陵寒月上孫徽使君兼寄東陽王使君三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af51bc11-f7b7-401b-8136-c936d2180264', '避地毘陵寒月上孫徽使君兼寄東陽王使君三首 三', '避地毘陵寒月上孫徽使君兼寄东陽王使君三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["□雷車雨滴階聲，寂寞焚香獨閉扃。","錦繡文章無路達，袴襦歌詠隔牆聽。","松聲冷浸茶軒碧，苔點狂吞納線青。","唯有孤高江太守，不忘病客在禪靈。"]', '["□雷车雨滴階声，寂寞焚香独閉扃。","錦繡文章無路達，袴襦歌詠隔牆听。","松声冷浸茶軒碧，苔点狂吞納線青。","唯有孤高江太守，不忘病客在禪靈。"]', '诗', 'shi', '', NULL, '避地毘陵寒月上孫徽使君兼寄東陽王使君三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad76517b-cf80-42f1-8ead-bee4e6feda65', '秋末寄上桐江馮使君', '秋末寄上桐江馮使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["山東山色勝諸山，謝守清高不可攀。","薄俗盡于言下泰，苦心唯到醉中閑。","香凝錦帳抄書後，月轉棠陰送客還。","野客霑恩歸未得，蕭蕭霜葉滿柴關。"]', '["山东山色勝諸山，謝守清高不可攀。","薄俗尽于言下泰，苦心唯到醉中闲。","香凝錦帳抄书後，月轉棠陰送客還。","野客霑恩归未得，蕭蕭霜葉满柴关。"]', '诗', 'shi', '', NULL, '秋末寄上桐江馮使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f48698d0-cbf7-40cd-8f1f-7470b9e1e08d', '禪師', '禪師', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["擊鼓求亡益是非，木中生火更何爲。","吾師別是醍醐昧，不是知心人不知。"]', '["擊鼓求亡益是非，木中生火更何爲。","吾師別是醍醐昧，不是知心人不知。"]', '诗', 'shi', '', NULL, '禪師 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c203d62d-b1c5-40c1-bc15-c13ab2b9308a', '道士', '道士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["花島相逢滿袖雲，藉花論道過金巾。","騰騰又入仙山去，只恐是青城丈人。"]', '["花島相逢满袖云，藉花論道過金巾。","腾腾又入仙山去，只恐是青城丈人。"]', '诗', 'shi', '', NULL, '道士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0714809-e500-4946-821b-eb57b43c3006', '風琴', '风琴', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["至境心爲造化功，一枝青竹四弦風。","寥寥雙耳更深後，如在緱山明月中。"]', '["至境心爲造化功，一枝青竹四弦风。","寥寥雙耳更深後，如在緱山明月中。"]', '诗', 'shi', '', NULL, '風琴 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('651dcc84-03cf-4e51-b2cb-cecc0f3f51cc', '庭橘', '庭橘', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蟻踏金苞四五株，洞庭山上味何殊。","不緣松樹稱君子，肯便甘人喚木奴。"]', '["蟻踏金苞四五株，洞庭山上味何殊。","不緣松樹稱君子，肯便甘人喚木奴。"]', '诗', 'shi', '', NULL, '庭橘 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ceb9287-a08a-4b28-9efd-8144f3032cb6', '落花', '落花', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蝶醉蜂癡一簇香，繡葩紅蔕墮殘芳。","因嗟好德人難得，公子王孫盡斷腸。"]', '["蝶醉蜂癡一簇香，繡葩紅蔕墮殘芳。","因嗟好德人难得，公子王孫尽斷腸。"]', '诗', 'shi', '', NULL, '落花 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f141a2-c586-44c2-a485-ea0c6f4a330d', '孤雲', '孤云', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["將比鷺鷥還恐屈，始思殘雪不如多。","清風相引去更遠，皎潔孤高奈爾何。"]', '["將比鷺鷥還恐屈，始思殘雪不如多。","清风相引去更远，皎潔孤高奈爾何。"]', '诗', 'shi', '', NULL, '孤雲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57d7c976-9e10-477d-9e34-9bab3d6532e0', '苦吟', '苦吟', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["河薄星疎雪月孤，松枝清氣入肌膚。","因知好句勝金玉，心極神勞特地無。"]', '["河薄星疎雪月孤，松枝清氣入肌膚。","因知好句勝金玉，心極神勞特地無。"]', '诗', 'shi', '', NULL, '苦吟 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4faef17f-ed0f-4954-80b7-0c16d7012965', '古戰處', '古戰处', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鬼氣蒼黃棘葉紅，昔時人血此時風。","相憐極目無疆地，曾落將軍一陣中。"]', '["鬼氣蒼黄棘葉紅，昔时人血此时风。","相怜極目無疆地，曾落將軍一陣中。"]', '诗', 'shi', '', NULL, '古戰處 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0593420f-6783-49a0-979f-f6f9fa4210a7', '偶然作', '偶然作', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蟬聲引出石中蛩，寂寞門扃葉數重。","誰道思山心不切，等閑盡出兩三峰。"]', '["蟬声引出石中蛩，寂寞门扃葉數重。","誰道思山心不切，等闲尽出兩三峰。"]', '诗', 'shi', '', NULL, '偶然作 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abbb5449-dddd-4ec7-890d-d22180728505', '招友人宿', '招友人宿', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["銀地無塵金菊開，紫梨紅棗墮莓苔。","一泓秋水一輪月，今夜故人來不來。"]', '["銀地無塵金菊开，紫梨紅棗墮莓苔。","一泓秋水一輪月，今夜故人来不来。"]', '诗', 'shi', '', NULL, '招友人宿 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b39981e5-3d2a-4aed-9f01-a4e3dd28fc84', '山居詩二十四首 一', '山居诗二十四首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["休話諠譁事事難，山翁只合住深山。","數聲清磬是非外，一箇閑人天地間。","綠圃空階雲冉冉，異禽靈草水潺潺。","無人與向羣儒說，巖桂枝高亦好扳。"]', '["休話諠譁事事难，山翁只合住深山。","數声清磬是非外，一箇闲人天地间。","綠圃空階云冉冉，異禽靈草水潺潺。","無人與向羣儒说，巖桂枝高亦好扳。"]', '诗', 'shi', '', NULL, '山居詩二十四首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2e57b57-2500-4e95-8375-e6c585c62ba5', '山居詩二十四首 二', '山居诗二十四首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["難是言休即便休，清吟孤作碧溪頭。","三間茆屋無人到，十里松陰獨自遊。","明月清風宗炳社，夕陽秋色庾公樓。","修心未到無心地，萬種千般逐水流。"]', '["难是言休即便休，清吟孤作碧溪头。","三间茆屋無人到，十里松陰独自游。","明月清风宗炳社，夕陽秋色庾公楼。","修心未到無心地，万種千般逐水流。"]', '诗', 'shi', '', NULL, '山居詩二十四首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a917cddc-8152-4b2c-b30f-e44d1ed449d6', '山居詩二十四首 三', '山居诗二十四首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["好鳥聲長睡眼開，好茶擎乳坐莓苔。","不聞榮辱成番盡，只見熊羆作隊來。","詩裏從前欺白雪，道情終遣似嬰孩。","由來此事知音少，不是真風去不迴。"]', '["好鸟声长睡眼开，好茶擎乳坐莓苔。","不闻榮辱成番尽，只见熊羆作隊来。","诗裏從前欺白雪，道情終遣似嬰孩。","由来此事知音少，不是真风去不迴。"]', '诗', 'shi', '', NULL, '山居詩二十四首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bb2b579-c51c-411f-be6a-199f45909911', '山居詩二十四首 四', '山居诗二十四首 四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["萬境忘機是道華，碧芙蓉裏日空斜。","幽深有徑通仙窟，寂寞無人落異花。","掣電浮雲真好喻，如龍似鳳不須誇。","君看江上英雄冢，只有松根與柏槎。"]', '["万境忘機是道华，碧芙蓉裏日空斜。","幽深有徑通仙窟，寂寞無人落異花。","掣電浮云真好喻，如龙似鳳不須誇。","君看江上英雄冢，只有松根與柏槎。"]', '诗', 'shi', '', NULL, '山居詩二十四首 四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2764600-4f3e-492b-9625-8103910621e2', '山居詩二十四首 五', '山居诗二十四首 五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鞭後從他素髮兼，湧清奔碧冷侵簾。","高奇章句無人愛，澹泊身心舉世嫌。","白石橋高吟不足，紅霞影暖臥無厭。","居山別有非山意，莫錯將予比宋纖。"]', '["鞭後從他素髮兼，湧清奔碧冷侵簾。","高奇章句無人愛，澹泊身心舉世嫌。","白石橋高吟不足，紅霞影暖臥無厭。","居山別有非山意，莫錯將予比宋纖。"]', '诗', 'shi', '', NULL, '山居詩二十四首 五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('522f216f-0be5-40b7-b1d8-7030d5ced7d1', '山居詩二十四首 六', '山居诗二十四首 六', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鳥外塵中四十秋，亦曾高挹漢諸侯。","如斯標致雖清拙，大丈夫兒合自由。","紫朮黃菁苗蕺蕺，錦囊香麝語啾啾。","終須心到曹溪叟，千歲櫧根雪滿頭。"]', '["鸟外塵中四十秋，亦曾高挹漢諸侯。","如斯標致雖清拙，大丈夫兒合自由。","紫朮黄菁苗蕺蕺，錦囊香麝語啾啾。","終須心到曹溪叟，千歲櫧根雪满头。"]', '诗', 'shi', '', NULL, '山居詩二十四首 六 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea7cee7e-95fa-43cd-81ff-72e3fac82df4', '山居詩二十四首 七', '山居诗二十四首 七', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["慵甚嵇康竟不迴，何妨方寸似寒灰。","山精日作兒童出，仙者時將玉器來。","筠帚埽花驚睡鹿，地壚燒樹帶枯苔。","不行朝市多時也，許史金張安在哉。"]', '["慵甚嵇康竟不迴，何妨方寸似寒灰。","山精日作兒童出，仙者时將玉器来。","筠帚埽花驚睡鹿，地壚燒樹带枯苔。","不行朝市多时也，許史金張安在哉。"]', '诗', 'shi', '', NULL, '山居詩二十四首 七 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524102ae-bf44-4be2-ac4b-e9d877fe91a3', '山居詩二十四首 八', '山居诗二十四首 八', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["心心心不住希夷，石屋巉巖鬢髮垂。","養竹不除當路筍，愛松留得礙人枝。","焚香開卷霞生砌，捲箔冥心月在池。","多少故人頭盡白，不知今日又何之。"]', '["心心心不住希夷，石屋巉巖鬢髮垂。","養竹不除當路筍，愛松留得礙人枝。","焚香开卷霞生砌，捲箔冥心月在池。","多少故人头尽白，不知今日又何之。"]', '诗', 'shi', '', NULL, '山居詩二十四首 八 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('324eeb50-2980-430b-9e43-79cc55568963', '山居詩二十四首 九', '山居诗二十四首 九', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["龍藏琅函遍九垓，霜鍾金鼓振瓊臺。","堪嗟一句無人得，遂使吾師特地來。","無角鐵牛眠少室，生兒石女老黃梅。","令人轉憶龐居士，天上人間不可陪。"]', '["龙藏琅函遍九垓，霜鍾金鼓振瓊台。","堪嗟一句無人得，遂使吾師特地来。","無角鐵牛眠少室，生兒石女老黄梅。","令人轉憶龐居士，天上人间不可陪。"]', '诗', 'shi', '', NULL, '山居詩二十四首 九 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89221d02-759e-4155-b38f-bc5c12483aaa', '山居詩二十四首 十', '山居诗二十四首 十', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["五嶽煙霞連不斷，三山洞穴去應通。","石窗欹枕疎疎雨，水碓無人浩浩風。","童子念經深竹裏，獼猴拾蝨夕陽中。","因思往事拋心力，六七年來楚水東。"]', '["五嶽煙霞連不斷，三山洞穴去應通。","石窗欹枕疎疎雨，水碓無人浩浩风。","童子念經深竹裏，獼猴拾蝨夕陽中。","因思往事拋心力，六七年来楚水东。"]', '诗', 'shi', '', NULL, '山居詩二十四首 十 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9cb47d-1e85-481c-9d2a-81b36eb2fd7b', '山居詩二十四首 十一', '山居诗二十四首 十一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["塵埃中更有埃塵，時復雙眉十爲顰。","賴有年光飛似箭，是何心地亦稱人。","回賢參孝時時說，蜂蠆狼貪日日新。","天意剛容此徒在，不堪惆悵不堪陳。"]', '["塵埃中更有埃塵，时复雙眉十爲顰。","賴有年光飞似箭，是何心地亦稱人。","回賢參孝时时说，蜂蠆狼貪日日新。","天意剛容此徒在，不堪惆悵不堪陳。"]', '诗', 'shi', '', NULL, '山居詩二十四首 十一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('687ea415-b382-4fef-a2c4-e9eddf033aa4', '山居詩二十四首 十二', '山居诗二十四首 十二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["翠竇煙巖畫不成，桂華瀑沫雜芳馨。","撥霞掃雪和雲母，掘石移松得茯苓。","好鳥傍花窺玉磬，嫩苔和水沒金缾。","從他人說從他笑，地覆天翻也只寧。"]', '["翠竇煙巖畫不成，桂华瀑沫杂芳馨。","撥霞掃雪和云母，掘石移松得茯苓。","好鸟傍花窺玉磬，嫩苔和水沒金缾。","從他人说從他笑，地覆天翻也只寧。"]', '诗', 'shi', '', NULL, '山居詩二十四首 十二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc5f04b-8d45-4041-8336-68ef9105b6e5', '山居詩二十四首 十三', '山居诗二十四首 十三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["騰騰兀兀步遲遲，兆朕消磨只自知。","龍猛金膏雖未作，孫登土窟且相宜。","薜蘿山帔偏能𫃷，橡栗年糧亦且支。","已得真人好消息，人間天上更無疑。"]', '["腾腾兀兀步遲遲，兆朕消磨只自知。","龙猛金膏雖未作，孫登土窟且相宜。","薜蘿山帔偏能𫃷，橡栗年糧亦且支。","已得真人好消息，人间天上更無疑。"]', '诗', 'shi', '', NULL, '山居詩二十四首 十三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c05f6f71-75a8-4205-9696-638f053e1183', '山居詩二十四首 十四', '山居诗二十四首 十四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["嵐嫩風輕似碧紗，雪樓金像隔煙霞。","葛苞玉粉生香壠，菌簇銀釘滿淨楂。","舉世只知嗟逝水，無人微解悟空花。","可憐擾擾塵埃裏，雙鬢如銀事似麻。"]', '["嵐嫩风轻似碧紗，雪楼金像隔煙霞。","葛苞玉粉生香壠，菌簇銀釘满淨楂。","舉世只知嗟逝水，無人微解悟空花。","可怜擾擾塵埃裏，雙鬢如銀事似麻。"]', '诗', 'shi', '', NULL, '山居詩二十四首 十四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d623364d-e154-411f-8f17-5588cfb18bab', '山居詩二十四首 十五', '山居诗二十四首 十五', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["千巖萬壑路傾欹，杉檜濛濛獨掩扉。","斸藥童穿溪𥕕去，採花蜂冒曉煙歸。","閑行放意尋流水，靜坐支頤到落暉。","長憶南泉好言語，如斯癡鈍者還稀。"]', '["千巖万壑路傾欹，杉檜濛濛独掩扉。","斸藥童穿溪𥕕去，採花蜂冒晓煙归。","闲行放意尋流水，静坐支頤到落暉。","长憶南泉好言語，如斯癡鈍者還稀。"]', '诗', 'shi', '', NULL, '山居詩二十四首 十五 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7cd52e2-8188-4b4a-a1f4-10a431f24238', '山居詩二十四首 十六', '山居诗二十四首 十六', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一菴冥目在穹冥，菌枕松牀蘚陣青。","乳鹿暗行檉徑雪，瀑泉微濺石樓經。","閑行不覺過天井，長嘯深能動岳靈。","應恐無人知此意，非凡非聖獨醒醒。"]', '["一菴冥目在穹冥，菌枕松牀蘚陣青。","乳鹿暗行檉徑雪，瀑泉微濺石楼經。","闲行不覺過天井，长嘯深能动岳靈。","應恐無人知此意，非凡非聖独醒醒。"]', '诗', 'shi', '', NULL, '山居詩二十四首 十六 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('649346a9-a04a-439c-bd99-3e77fa032007', '山居詩二十四首 十七', '山居诗二十四首 十七', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["慵刻芙蓉傳永漏，休誇麗藻鄙湯休。","且爲小囤盛紅粟，別有珍禽勝白鷗。","拾栗遠尋深澗底，弄猨多在小峯頭。","不能更出塵中也，百煉剛爲繞指柔。"]', '["慵刻芙蓉傳永漏，休誇丽藻鄙湯休。","且爲小囤盛紅粟，別有珍禽勝白鷗。","拾栗远尋深澗底，弄猨多在小峯头。","不能更出塵中也，百煉剛爲繞指柔。"]', '诗', 'shi', '', NULL, '山居詩二十四首 十七 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0032e555-ef03-45c5-94c8-dcb4a81bfe09', '山居詩二十四首 十八', '山居诗二十四首 十八', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["業薪心火日燒煎，浪死虛生自古然。","陸氏稱龍終妄矣，漢家得鹿更空焉。","白衣居士深深說，青眼胡僧遠遠傳。","剛地無人知此意，不堪惆悵落花前。"]', '["業薪心火日燒煎，浪死虛生自古然。","陸氏稱龙終妄矣，漢家得鹿更空焉。","白衣居士深深说，青眼胡僧远远傳。","剛地無人知此意，不堪惆悵落花前。"]', '诗', 'shi', '', NULL, '山居詩二十四首 十八 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e8845b-da91-4de1-b849-633d568f10e7', '山居詩二十四首 十九', '山居诗二十四首 十九', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["露滴紅蘭玉滿畦，閑拖象屣到峯西。","但令心似蓮花潔，何必身將槁木齊。","古壍細煙紅樹老，半岩殘雪白猨啼。","雖然不是桃源洞，春至桃花亦滿蹊。"]', '["露滴紅蘭玉满畦，闲拖象屣到峯西。","但令心似蓮花潔，何必身將槁木齊。","古壍細煙紅樹老，半岩殘雪白猨啼。","雖然不是桃源洞，春至桃花亦满蹊。"]', '诗', 'shi', '', NULL, '山居詩二十四首 十九 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9542ad78-4178-4d89-beed-e844338927a0', '山居詩二十四首 二十', '山居诗二十四首 二十', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["自休自已自安排，常願居山事偶諧。","僧採樹衣臨絕壑，狖爭山果落空階。","閑擔茶器緣青障，靜衲禪袍坐綠崖。","虛作新詩反招隱，出來多與此心乖。"]', '["自休自已自安排，常願居山事偶諧。","僧採樹衣臨絕壑，狖爭山果落空階。","闲擔茶器緣青障，静衲禪袍坐綠崖。","虛作新诗反招隐，出来多與此心乖。"]', '诗', 'shi', '', NULL, '山居詩二十四首 二十 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2832230e-2df2-4911-aa1c-b938e552a97e', '山居詩二十四首 二十一', '山居诗二十四首 二十一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["石罏金鼎紅蕖嫩，香閣茶棚綠巘齊。","塢燒崩騰奔澗鼠，岩花狼籍鬬山雞。","蒙莊環外知音少，阮籍途窮旨趣低。","應有世人來覓我，水重山疊幾層迷。"]', '["石罏金鼎紅蕖嫩，香閣茶棚綠巘齊。","塢燒崩腾奔澗鼠，岩花狼籍鬬山雞。","蒙莊环外知音少，阮籍途窮旨趣低。","應有世人来覓我，水重山叠幾層迷。"]', '诗', 'shi', '', NULL, '山居詩二十四首 二十一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('940bd761-57ad-458e-a1c3-efd9a61dd32b', '山居詩二十四首 二十二', '山居诗二十四首 二十二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["自古浮華能幾幾，逝波終日去滔滔。","漢王廢苑生秋草，吳主荒宮入夜濤。","滿屋黃金機不息，一頭白髮氣猶高。","豈知知足金仙子，霞外天香滿毳袍。"]', '["自古浮华能幾幾，逝波終日去滔滔。","漢王廢苑生秋草，吳主荒宮入夜濤。","满屋黄金機不息，一头白髮氣猶高。","豈知知足金仙子，霞外天香满毳袍。"]', '诗', 'shi', '', NULL, '山居詩二十四首 二十二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1139583-ba1f-4800-bb7b-8ce53c077dee', '山居詩二十四首 二十三', '山居诗二十四首 二十三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["如愚何止直如弦，只合深藏碧嶂前。","但見山中常有雪，不知世上是何年。","野人愛向菴前笑，赤玃頻來袖畔眠。","只有逍遙好知己，何須更問洞中天。"]', '["如愚何止直如弦，只合深藏碧嶂前。","但见山中常有雪，不知世上是何年。","野人愛向菴前笑，赤玃頻来袖畔眠。","只有逍遙好知己，何須更问洞中天。"]', '诗', 'shi', '', NULL, '山居詩二十四首 二十三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07aa0959-baeb-4482-a39d-1673882accea', '山居詩二十四首 二十四', '山居诗二十四首 二十四', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["支公放鶴情相似，范泰論交趣不同。","有念盡爲煩惱相，無私方稱水晶宮。","香焚薝蔔諸峯曉，珠掐金剛萬境空。","若買山資言不及，恆河沙劫用無窮。"]', '["支公放鹤情相似，范泰論交趣不同。","有念尽爲煩惱相，無私方稱水晶宮。","香焚薝蔔諸峯晓，珠掐金剛万境空。","若買山資言不及，恆河沙劫用無窮。"]', '诗', 'shi', '', NULL, '山居詩二十四首 二十四 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0bdb9ce-ff21-40e6-beb9-8d91dd99b65c', '再逢虛中道士三首 一', '再逢虛中道士三首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["天目西峯古壞壇，壇邊相別雪漫漫。","如今四十餘年也，還共當時恰一般。"]', '["天目西峯古壞壇，壇邊相別雪漫漫。","如今四十餘年也，還共當时恰一般。"]', '诗', 'shi', '', NULL, '再逢虛中道士三首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d21f30c-04c2-466e-acc1-128ee5af716c', '再逢虛中道士三首 二', '再逢虛中道士三首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["囊裏靈龜小似錢，道伊年與我同年。","壺中長挈天相逐，何處昇天更有天。"]', '["囊裏靈龟小似錢，道伊年與我同年。","壺中长挈天相逐，何处昇天更有天。"]', '诗', 'shi', '', NULL, '再逢虛中道士三首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3789544-e970-496b-b085-a1f979da7f80', '再逢虛中道士三首 三', '再逢虛中道士三首 三', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["吾道將君道且殊，君鬚全似老君鬚。","尋常有語爭堪信，愛說蟠桃似甕麤。"]', '["吾道將君道且殊，君鬚全似老君鬚。","尋常有語爭堪信，愛说蟠桃似甕麤。"]', '诗', 'shi', '', NULL, '再逢虛中道士三首 三 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('315e3e1e-5cff-4764-b34e-88b989b60706', '上盧使君二首 一', '上盧使君二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一領彤弓下赤墀，惟將清淨作藩籬。","馬卿山岳金相似，張緒風情柳不如。","心染煙霞新句出，筆驅奸蠹宿根隳。","鄱陽黎庶還堪羨，頭有重天足有氂。"]', '["一領彤弓下赤墀，惟將清淨作藩籬。","马卿山岳金相似，張緒风情柳不如。","心染煙霞新句出，笔驱奸蠹宿根隳。","鄱陽黎庶還堪羨，头有重天足有氂。"]', '诗', 'shi', '', NULL, '上盧使君二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd411ee-7154-4fb9-b6bf-4a4cb03b00db', '上盧使君二首 二', '上盧使君二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["司馬遷文亞聖人，三頭九陌碾香塵。","盡傳棣萼麟兼鳳，終作昌朝甫與申。","樓聳嬌歌疎雨過，風含和氣滿城春。","因知寰海昇平去，又見高宗夢裏人。"]', '["司马遷文亞聖人，三头九陌碾香塵。","尽傳棣萼麟兼鳳，終作昌朝甫與申。","楼聳嬌歌疎雨過，风含和氣满城春。","因知寰海昇平去，又见高宗梦裏人。"]', '诗', 'shi', '', NULL, '上盧使君二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fec40be-623a-4f2c-960f-7ca2976265e8', '陪馮使君遊六首 登干霄亭', '陪馮使君游六首 登干霄亭', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["擁翠捫蘿山屐輕，飄颻紅斾在青冥。","仙科朱紱言非貴，溪鳥林泉癖愛聽。","古桂林邊棊局濕，白雲堆裏茗煙青。","因思廬岳彌天客，手把金書倚石屏。"]', '["擁翠捫蘿山屐轻，飄颻紅斾在青冥。","仙科朱紱言非貴，溪鸟林泉癖愛听。","古桂林邊棊局濕，白云堆裏茗煙青。","因思廬岳彌天客，手把金书倚石屏。"]', '诗', 'shi', '', NULL, '陪馮使君遊六首 登干霄亭 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('364e597c-adf1-41f5-aa10-f3a8249b1c82', '陪馮使君遊六首 遊靈泉院', '陪馮使君游六首 游靈泉院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["珂珮喧喧滿路岐，亂泉聲裏扣禪扉。","對花語合希夷境，坐石苔黏黻黼衣。","鳥啄古杉雲冉冉，風吹清磬露霏霏。","惠巖亦有孤峯在，只戀繙經未得歸。"]', '["珂珮喧喧满路岐，亂泉声裏扣禪扉。","对花語合希夷境，坐石苔黏黻黼衣。","鸟啄古杉云冉冉，风吹清磬露霏霏。","惠巖亦有孤峯在，只戀繙經未得归。"]', '诗', 'shi', '', NULL, '陪馮使君遊六首 遊靈泉院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e19ff8f-b0c8-4b67-8cf7-adcfea1770ed', '陪馮使君遊六首 過相思嶺', '陪馮使君游六首 過相思嶺', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["譽自馨香道自怡，相思嶺上却無機。","荒蕖葉覆深霞在，片石人吟一鳥飛。","何處風砧傳古曲，誰家冢樹挂斜暉。","因思往事真堪笑，鶴背漁竿未是歸。"]', '["譽自馨香道自怡，相思嶺上却無機。","荒蕖葉覆深霞在，片石人吟一鸟飞。","何处风砧傳古曲，誰家冢樹挂斜暉。","因思往事真堪笑，鹤背漁竿未是归。"]', '诗', 'shi', '', NULL, '陪馮使君遊六首 過相思嶺 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0807c5b-ae76-4dba-9b13-a10bf22234ff', '陪馮使君遊六首 錦沙墩', '陪馮使君游六首 錦沙墩', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["臨水登山興自奇，錦沙墩上最多時。","雖云髮白孤峯好，其奈名清聖主知。","草媚蓮塘資逸步，雲生松壑有新詩。","翛然別是神仙趣，豈羨東山妓樂隨。"]', '["臨水登山兴自奇，錦沙墩上最多时。","雖云髮白孤峯好，其奈名清聖主知。","草媚蓮塘資逸步，云生松壑有新诗。","翛然別是神仙趣，豈羨东山妓乐隨。"]', '诗', 'shi', '', NULL, '陪馮使君遊六首 錦沙墩 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc173248-bc42-4c25-9a2b-ccf0fc0e24f9', '陪馮使君遊六首 釣罾潭', '陪馮使君游六首 釣罾潭', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["境靜江清無事時，紅旌畫鷁動漁磯。","心期只是行春去，日暮還應待鶴歸。","風破綺霞山寺出，人歌白雪島花飛。","自憐亦在仙舟上，玉浪翻翻濺草衣。"]', '["境静江清無事时，紅旌畫鷁动漁磯。","心期只是行春去，日暮還應待鹤归。","风破綺霞山寺出，人歌白雪島花飞。","自怜亦在仙舟上，玉浪翻翻濺草衣。"]', '诗', 'shi', '', NULL, '陪馮使君遊六首 釣罾潭 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bbe4e98-ee3e-4e1f-a428-a4e2ccbddf78', '陪馮使君遊六首 迎仙閣', '陪馮使君游六首 迎仙閣', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["澗香霞影遶樓臺，捲箔凭闌耳目開。","況從旌旗近鸞鳳，可憐談笑出塵埃。","火雲不入長松徑，露茗何須白玉杯。","誰道迎仙仙不至，今朝還有謝公來。"]', '["澗香霞影遶楼台，捲箔凭闌耳目开。","況從旌旗近鸾鳳，可怜談笑出塵埃。","火云不入长松徑，露茗何須白玉杯。","誰道迎仙仙不至，今朝還有謝公来。"]', '诗', 'shi', '', NULL, '陪馮使君遊六首 迎仙閣 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2409a641-89b0-4bc7-b055-f44ec862d0b7', '賀雨上王使君二首 一', '賀雨上王使君二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一片丹心合萬靈，應時甘雨帶龍腥。","驅塵煞燒連窮□，□電衝霓滿窅冥。","處處已知倉廩溢，家家皆歇管弦聽。","應須蚤勒南山石，黃霸清風滿內庭。"]', '["一片丹心合万靈，應时甘雨带龙腥。","驱塵煞燒連窮□，□電衝霓满窅冥。","处处已知倉廩溢，家家皆歇管弦听。","應須蚤勒南山石，黄霸清风满內庭。"]', '诗', 'shi', '', NULL, '賀雨上王使君二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91ca652b-c1af-4896-9f42-6715bb6ad7d0', '賀雨上王使君二首 二', '賀雨上王使君二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["由來天贊德唯馨，朋禱心期事盡行。","玄妙久聞談佛母，感通今日見神明。","破除秋熱飄蕭盡，還似春時散漫傾。","他日爲霖亦如此，諸生無不沐經營。"]', '["由来天贊德唯馨，朋禱心期事尽行。","玄妙久闻談佛母，感通今日见神明。","破除秋熱飄蕭尽，還似春时散漫傾。","他日爲霖亦如此，諸生無不沐經營。"]', '诗', 'shi', '', NULL, '賀雨上王使君二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abd241df-4d58-4f19-ac44-67a32fb03e5a', '感懷寄盧給事二首 一', '感懷寄盧給事二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["緜緜遠念近來多，喜鵲隨函到綠蘿。","雖匪二賢曾入洛，忽驚六義減沈疴。","童扳鄰杏隳牆瓦，燕啄花泥落砌莎。","好更因人寄消息，沃州歸去已蹉跎。"]', '["緜緜远念近来多，喜鵲隨函到綠蘿。","雖匪二賢曾入洛，忽驚六義減沈疴。","童扳鄰杏隳牆瓦，燕啄花泥落砌莎。","好更因人寄消息，沃州归去已蹉跎。"]', '诗', 'shi', '', NULL, '感懷寄盧給事二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3053742a-97b1-4121-950b-5e65420c0091', '感懷寄盧給事二首 二', '感懷寄盧給事二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常憶團圓繡像前，東歸經亂獨生全。","孤峯已住六七處，萬事無成三十年。","每想苑牆危逼路，更思鉢塔曉凌煙。","如今憔悴荆枝盡，一諷來書一愴然。"]', '["常憶團圓繡像前，东归經亂独生全。","孤峯已住六七处，万事無成三十年。","每想苑牆危逼路，更思鉢塔晓凌煙。","如今憔悴荆枝尽，一諷来书一愴然。"]', '诗', 'shi', '', NULL, '感懷寄盧給事二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e282b6db-9dff-4f40-bd98-0b97d81fdfad', '賀鄭使君', '賀鄭使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["三衢蜂蠆陷城池，八詠龍韜整武貔。","纔諭危亡書半幅，便思父母淚雙垂。","戈收甲束投仁境，汗浹魂飄拜虎旗。","死地再生知德重，精兵連譀覺山移。","人和美叶禎祥出，陣善深爲典教推。","仗信輸誠方始是，執俘折馘欲何爲。","清威嚴令無纖𡏖，長路深山不拾遺。","七邑恩波歌浩渺，一方雲物自鮮奇。","天文仰視同諸掌，劒術無前更數誰。","戰馬閑眠汀草遠，秋鼙乾揭岳霞隳。","義爲土地精靈伏，仁作金湯鐵石卑。","龔遂劉寬同煦嫗，張飛關羽太驅馳。","笙歌席上偏憐客，刀劒林中亦念詩。","縠渚美爲長飲水，金山高作受降碑。","時猶草草秋方盡，陳是堂堂孰敢窺。","寵渥豈唯分節鉞，勳庸須勒上鍾彝。","神資天贊誰堪比，名遂功成自不知。","捲箔倚闌雲欲雪，擁罏傾榼酒如飴。","扶堯社稷常憂老，到郭汾陽亦未遲。","釋子沾恩無以報，只將葑菲賀階墀。"]', '["三衢蜂蠆陷城池，八詠龙韜整武貔。","纔諭危亡书半幅，便思父母泪雙垂。","戈收甲束投仁境，汗浹魂飄拜虎旗。","死地再生知德重，精兵連譀覺山移。","人和美叶禎祥出，陣善深爲典教推。","仗信輸誠方始是，執俘折馘欲何爲。","清威嚴令無纖𡏖，长路深山不拾遺。","七邑恩波歌浩渺，一方云物自鲜奇。","天文仰視同諸掌，劒術無前更數誰。","戰马闲眠汀草远，秋鼙乾揭岳霞隳。","義爲土地精靈伏，仁作金湯鐵石卑。","龔遂劉寬同煦嫗，張飞关羽太驱驰。","笙歌席上偏怜客，刀劒林中亦念诗。","縠渚美爲长饮水，金山高作受降碑。","时猶草草秋方尽，陳是堂堂孰敢窺。","寵渥豈唯分節鉞，勳庸須勒上鍾彝。","神資天贊誰堪比，名遂功成自不知。","捲箔倚闌云欲雪，擁罏傾榼酒如飴。","扶堯社稷常憂老，到郭汾陽亦未遲。","釋子沾恩無以報，只將葑菲賀階墀。"]', '诗', 'shi', '', NULL, '賀鄭使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2823dfe3-4a12-47f1-bcc4-d295a66e0c4b', '送鄭使君', '送鄭使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["刺婺廉閩動帝臺，唯將清淨作梯媒。","綠沈槍卓妖星落，白玉壺澄苦霧開。","仁愛久懸溪上月，恩光又發領頭梅。","天資劉邵龔黃筆，神助韓彭衛霍才。","古驛劒江分掩映，畫旗花舫下喧豗。","鳳麟帟幕芙蓉坼，洞壑清威霹靂來。","禮樂封疆添禮樂，塵埃時節勿塵埃。","荔支花下驅千騎，薝葡林中禮萬迴。","視事蠻奴磨玉硯，邀賓海月射金杯。","謳歌合合千門樂，鼙角雄雄一閣雷。","君父恩深頭早白，子孫榮襲日難陪。","東陽緇素如何好，空向生祠祝上台。"]', '["刺婺廉閩动帝台，唯將清淨作梯媒。","綠沈槍卓妖星落，白玉壺澄苦霧开。","仁愛久懸溪上月，恩光又發領头梅。","天資劉邵龔黄笔，神助韓彭衛霍才。","古驛劒江分掩映，畫旗花舫下喧豗。","鳳麟帟幕芙蓉坼，洞壑清威霹靂来。","禮乐封疆添禮乐，塵埃时節勿塵埃。","荔支花下驱千騎，薝葡林中禮万迴。","視事蠻奴磨玉硯，邀賓海月射金杯。","謳歌合合千门乐，鼙角雄雄一閣雷。","君父恩深头早白，子孫榮襲日难陪。","东陽緇素如何好，空向生祠祝上台。"]', '诗', 'shi', '', NULL, '送鄭使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96876542-ffa7-4bfa-8eab-aaa2f6aa4ca1', '贈楊公杜之舅', '贈楊公杜之舅', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["分盡君憂一不遺，鳳書徵入萬民悲。","風雲終日如相逐，雨露前程即可知。","畫舸還盛江革石，秋山又看謝安棊。","談諧盡是經邦術，頭角由來出世姿。","天地事須歸橐籥，文章誰得到罘罳。","扣舷傍島清吟健，問俗看漁晚泊遲。","霞影滿江搖枕簟，鳥行和月下漣漪。","周秦漢魏書書在，麟鳳龜龍步步隨。","金殿恩波將浩浩，圭峯意緒謾孜孜。","郡中條令春常在，境外謌謠美更奇。","道者藥罏留要妙，林僧禪偈寄相思。","王楊盧駱真何者，房杜蕭張更是誰。","應念衢民千萬戶，家家皆置一生祠。"]', '["分尽君憂一不遺，鳳书徵入万民悲。","风云終日如相逐，雨露前程即可知。","畫舸還盛江革石，秋山又看謝安棊。","談諧尽是經邦術，头角由来出世姿。","天地事須归橐籥，文章誰得到罘罳。","扣舷傍島清吟健，问俗看漁晚泊遲。","霞影满江搖枕簟，鸟行和月下漣漪。","周秦漢魏书书在，麟鳳龟龙步步隨。","金殿恩波將浩浩，圭峯意緒謾孜孜。","郡中條令春常在，境外謌謠美更奇。","道者藥罏留要妙，林僧禪偈寄相思。","王楊盧駱真何者，房杜蕭張更是誰。","應念衢民千万戶，家家皆置一生祠。"]', '诗', 'shi', '', NULL, '贈楊公杜之舅 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36ccc72c-ccaa-4cea-9113-6766fabc8094', '遊金華山禪院', '游金华山禪院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["茲地曾棲菩薩僧，旃檀樓殿瀑崩騰。","因知境勝終難到，問著人來悉不曾。","斜谷暗藏千載雪，薄嵐常翳一龕燈。","多慙不及當時海，又下嵯峨一萬層。"]', '["茲地曾棲菩薩僧，旃檀楼殿瀑崩腾。","因知境勝終难到，问著人来悉不曾。","斜谷暗藏千載雪，薄嵐常翳一龕灯。","多慙不及當时海，又下嵯峨一万層。"]', '诗', 'shi', '', NULL, '遊金華山禪院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7831490-30bc-4ca7-a01a-18c32f92c280', '寄鄭道士二首 一', '寄鄭道士二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["常憶蘇耽好羽儀，信安山觀住多時。","不知玉質雙棲處，兩箇仙人是阿誰。"]', '["常憶蘇耽好羽儀，信安山观住多时。","不知玉質雙棲处，兩箇仙人是阿誰。"]', '诗', 'shi', '', NULL, '寄鄭道士二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daaf0474-5d00-4df4-afac-9620183b3215', '寄鄭道士二首 二', '寄鄭道士二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["誰帶金輪髻裏珠，何妨相逐去清都。","舊山大有閑田地，五色香茆有子無。"]', '["誰带金輪髻裏珠，何妨相逐去清都。","旧山大有闲田地，五色香茆有子無。"]', '诗', 'shi', '', NULL, '寄鄭道士二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b1b26e-21d7-47a4-a90a-1c050ce5f705', '送少年禪師二首 一', '送少年禪師二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["秀眉青目樹花衣，一鉢隨緣智不知。","佛與輪王嫌不作，世間剛有箇癡兒。"]', '["秀眉青目樹花衣，一鉢隨緣智不知。","佛與輪王嫌不作，世间剛有箇癡兒。"]', '诗', 'shi', '', NULL, '送少年禪師二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4568800d-6951-4c00-a1fc-98a9c28f4c5d', '送少年禪師二首 二', '送少年禪師二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["萬水千山一鶴飛，豈愁遊子暮何之。","古今此著無人會，王積新輸更不疑。"]', '["万水千山一鹤飞，豈愁游子暮何之。","古今此著無人會，王積新輸更不疑。"]', '诗', 'shi', '', NULL, '送少年禪師二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b249508-0611-4674-86bb-7ea073dabd98', '古劒池', '古劒池', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["秋水蓮花三四枝，我來慷慨步遲遲。","不決浮雲斬邪佞，真成龍去擬何爲。"]', '["秋水蓮花三四枝，我来慷慨步遲遲。","不決浮云斬邪佞，真成龙去擬何爲。"]', '诗', 'shi', '', NULL, '古劒池 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bead3a53-0606-4b5e-827a-35daa5f40fa8', '曹娥碑', '曹娥碑', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["高碑說爾孝應難，彈指端思白浪間。","堪歎行人不迴首，前山應是苧蘿山。"]', '["高碑说爾孝應难，彈指端思白浪间。","堪歎行人不迴首，前山應是苧蘿山。"]', '诗', 'shi', '', NULL, '曹娥碑 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1fcc4c3-a0c9-41f5-bb28-889e9ab1aa29', '比干傳', '比干傳', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["昏王亡國豈堪陳，只見明誠不見身。","想得先生也知自，欲將留與後來人。"]', '["昏王亡国豈堪陳，只见明誠不见身。","想得先生也知自，欲將留與後来人。"]', '诗', 'shi', '', NULL, '比干傳 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9474027-c994-4c16-a569-e1ecbcea2769', '送人遊茆山', '送人游茆山', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["鳥啼花笑煖紛紛，路入青雲白石門。","君到前頭好看好，老僧或恐是茆君。"]', '["鸟啼花笑煖紛紛，路入青云白石门。","君到前头好看好，老僧或恐是茆君。"]', '诗', 'shi', '', NULL, '送人遊茆山 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b67d1517-f383-45b5-bfe4-3867ef9d26b4', '聞杜宇', '闻杜宇', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["咽雨哀風更不停，春光於爾豈無情。","宜須喚得謝豹出，方始年年無此聲。"]', '["咽雨哀风更不停，春光於爾豈無情。","宜須喚得謝豹出，方始年年無此声。"]', '诗', 'shi', '', NULL, '聞杜宇 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eefe0f8-ef53-45d1-9bf4-43935fd784f9', '聽曉角', '听晓角', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["三會單于滿閣風，五行無忒月朦朧。","如何十萬家休戚，只在嗚嗚咽咽中。"]', '["三會單于满閣风，五行無忒月朦朧。","如何十万家休戚，只在嗚嗚咽咽中。"]', '诗', 'shi', '', NULL, '聽曉角 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9aa6ac4-66cc-4d19-9a12-061b8580c342', '宿赤松山觀題道人水閣兼寄郡守', '宿赤松山观題道人水閣兼寄郡守', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["珠殿香軿倚翠稜，寒棲吾道寄孫登。","豈應肘後終無分，見說仙中亦有僧。","雲斂石泉飛險竇，月明山鼠下枯藤。","還如華頂清談夜，因有新詩寄鄭弘。"]', '["珠殿香軿倚翠稜，寒棲吾道寄孫登。","豈應肘後終無分，见说仙中亦有僧。","云斂石泉飞險竇，月明山鼠下枯藤。","還如华頂清談夜，因有新诗寄鄭弘。"]', '诗', 'shi', '', NULL, '宿赤松山觀題道人水閣兼寄郡守 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bef28a93-ce6b-4710-859f-b00747c763a2', '春遊涼泉寺', '春游涼泉寺', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一到涼泉未擬歸，迸珠噴玉落階[墀]。","幾多僧祗因泉在，無限松如潑墨爲。","雲塹含香啼鳥細，茗甌擎乳落花遲。","青山看著不可上，多病多慵爭奈伊。"]', '["一到涼泉未擬归，迸珠噴玉落階[墀]。","幾多僧祗因泉在，無限松如潑墨爲。","云塹含香啼鸟細，茗甌擎乳落花遲。","青山看著不可上，多病多慵爭奈伊。"]', '诗', 'shi', '', NULL, '春遊涼泉寺 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff0a8bd0-7d58-4239-b835-867b5c0f235c', '經吳宮', '經吳宮', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["夫差昏暗霸圖傾，千古淒涼地不靈。","妖豔恩餘宮露濁，忠臣心苦海山青。","蕭條陵隴侵寒水，彷彿樓臺出杳冥。","此是前車況非遠，六朝何更不惺惺。"]', '["夫差昏暗霸圖傾，千古淒涼地不靈。","妖豔恩餘宮露濁，忠臣心苦海山青。","蕭條陵隴侵寒水，彷彿楼台出杳冥。","此是前车況非远，六朝何更不惺惺。"]', '诗', 'shi', '', NULL, '經吳宮 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c9ec1bf-b9a9-4f1b-a95e-e6990821b1d6', '送薛侍郎貶峽州司馬', '送薛侍郎貶峽州司马', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["得罪唯驚恩未酬，夷陵山誰稱閑遊。","人知八凱須當國，猨到三聲不用愁。","花落扁舟香冉冉，草侵公署雨脩脩。","因人好寄新詩好，不獨江東有沃州。"]', '["得罪唯驚恩未酬，夷陵山誰稱闲游。","人知八凱須當国，猨到三声不用愁。","花落扁舟香冉冉，草侵公署雨脩脩。","因人好寄新诗好，不独江东有沃州。"]', '诗', 'shi', '', NULL, '送薛侍郎貶峽州司馬 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d54aba44-4de7-4479-9938-44fe131616c1', '將入匡山宿韓判官宅', '將入匡山宿韓判官宅', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一宿蘭堂接上才，白雲歸去幾裴回。","黛青峯朵孤吟後，雪白猨兒必寄來。","簾卷茶煙縈墮葉，月明棊子落深苔。","明朝江上空迴首，始覺清風不可陪。"]', '["一宿蘭堂接上才，白云归去幾裴回。","黛青峯朵孤吟後，雪白猨兒必寄来。","簾卷茶煙縈墮葉，月明棊子落深苔。","明朝江上空迴首，始覺清风不可陪。"]', '诗', 'shi', '', NULL, '將入匡山宿韓判官宅 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d01b6b15-b0bd-437f-b3c5-90b87ff65d79', '送鄭侍郎騫赴闕', '送鄭侍郎騫赴闕', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["文章國器盡琅玕，朝騎駸駸歲欲殘。","彩筆祗宜天上用，繡衣偏稱雪中看。","休驚斷鴈離三楚，漸入祥煙下七槃。","翰苑舊知憑與說，紫金輪畔寄書難。"]', '["文章国器尽琅玕，朝騎駸駸歲欲殘。","彩笔祗宜天上用，繡衣偏稱雪中看。","休驚斷鴈離三楚，漸入祥煙下七槃。","翰苑旧知憑與说，紫金輪畔寄书难。"]', '诗', 'shi', '', NULL, '送鄭侍郎騫赴闕 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a350cc5e-3f0d-4a6a-b55e-113886e8fe32', '上盧使君', '上盧使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一別旌旗已一年，二林真子勸安禪。","常思雙戟華堂裏，還似孤峯峭壁前。","步出林泉多吉夢，帆侵分野入祥煙。","自憐酷似隨陽鴈，霜打風飄到日邊。"]', '["一別旌旗已一年，二林真子勸安禪。","常思雙戟华堂裏，還似孤峯峭壁前。","步出林泉多吉梦，帆侵分野入祥煙。","自怜酷似隨陽鴈，霜打风飄到日邊。"]', '诗', 'shi', '', NULL, '上盧使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c5033b1-2b3b-499e-8fcd-a0a86220d2e7', '寄匡山大願和尚', '寄匡山大願和尚', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["一聽玄音下竹亭，却思窗雪與囊螢。","祗將清淨酬恩德，敢信文章有性靈。","夢歷山牀聞鶴語，吟思海月上沙汀。","不堪迴首滄江上，萬仞廬峯在杳冥。"]', '["一听玄音下竹亭，却思窗雪與囊螢。","祗將清淨酬恩德，敢信文章有性靈。","梦歷山牀闻鹤語，吟思海月上沙汀。","不堪迴首滄江上，万仞廬峯在杳冥。"]', '诗', 'shi', '', NULL, '寄匡山大願和尚 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbff8bb7-1890-4df0-9e9c-ef9169544c04', '別盧使君歸東陽二首 一', '別盧使君归东陽二首 一', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["雨氣濛濛草滿庭，式微吟劇更誰聽。","詩逢匠化唯貪住，日覺恩深不易銘。","心苦祗應消鬢黑，夢遊頻入倚天青。","從茲還似歸回首，唯祝台星與福星。"]', '["雨氣濛濛草满庭，式微吟劇更誰听。","诗逢匠化唯貪住，日覺恩深不易銘。","心苦祗應消鬢黑，梦游頻入倚天青。","從茲還似归回首，唯祝台星與福星。"]', '诗', 'shi', '', NULL, '別盧使君歸東陽二首 一 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea3444e-8165-4907-9795-02e0f601fb28', '別盧使君歸東陽二首 二', '別盧使君归东陽二首 二', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["家在嚴陵釣渚旁，細漣嘉樹拂窗涼。","難醫林藪煙霞癖，又出芝蘭父母鄉。","孤帆好風千里煖，深花黃鳥一聲長。","終期金鼎調羹日，再近尼丘日月光。"]', '["家在嚴陵釣渚旁，細漣嘉樹拂窗涼。","难醫林藪煙霞癖，又出芝蘭父母乡。","孤帆好风千里煖，深花黄鸟一声长。","終期金鼎調羹日，再近尼丘日月光。"]', '诗', 'shi', '', NULL, '別盧使君歸東陽二首 二 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f58e728-9449-48f3-b276-a2b123235bf6', '溪寺水閣閑眺因寄宋使君', '溪寺水閣闲眺因寄宋使君', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["溪木蕭條一凭闌，玉霜飛後浪花寒。","釣魚船上風煙暝，古木林中砧杵乾。","至竟道心方始是，空耽山色亦無端。","誰如太守分憂外，時把西經盡日看。"]', '["溪木蕭條一凭闌，玉霜飞後浪花寒。","釣鱼船上风煙暝，古木林中砧杵乾。","至竟道心方始是，空耽山色亦無端。","誰如太守分憂外，时把西經尽日看。"]', '诗', 'shi', '', NULL, '溪寺水閣閑眺因寄宋使君 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f7ba2c9-3692-4cb7-9814-804ba910666d', '春送趙文觀送故合州座主神櫬歸洛', '春送趙文观送故合州座主神櫬归洛', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["喜繼于悲錦水東，還鄉仙騎却尋嵩。","再燒良玉堯雲動，方報深恩絳帳空。","遠道靈[輀]春欲盡，亂山羸馬恨無窮。","他年必立吾君側，好把書紳荅至公。"]', '["喜繼于悲錦水东，還乡仙騎却尋嵩。","再燒良玉堯云动，方報深恩絳帳空。","远道靈[輀]春欲尽，亂山羸马恨無窮。","他年必立吾君側，好把书紳荅至公。"]', '诗', 'shi', '', NULL, '春送趙文觀送故合州座主神櫬歸洛 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca1d5eb2-46e6-48a4-90b3-58e5e064e98d', '{巩/言}光大師草書歌', '{巩/言}光大師草书歌', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["雪壓千峯橫枕上，窮困雖多還激壯。","看師逸蹟兩相宜，高適歌行李白詩。","海上驚驅山猛燒，吹斷狂煙著沙草。","江樓曾見落星石，幾回試發將軍砲。","別有寒雕掠絕壁，提上玄猨更生力。","又見吳中磨角來，舞槊盤刀初觸擊。","好文天子揮宸翰，御製本多推玉案。","晨開水殿教題壁，題罷紫衣親寵錫。","僧家愛詩自拘束，僧家愛畫亦局促。","唯師草聖藝偏高，一掬山泉心便足。"]', '["雪壓千峯橫枕上，窮困雖多還激壯。","看師逸蹟兩相宜，高適歌行李白诗。","海上驚驱山猛燒，吹斷狂煙著沙草。","江楼曾见落星石，幾回試發將軍砲。","別有寒雕掠絕壁，提上玄猨更生力。","又见吳中磨角来，舞槊盤刀初觸擊。","好文天子揮宸翰，御製本多推玉案。","晨开水殿教題壁，題罷紫衣親寵錫。","僧家愛诗自拘束，僧家愛畫亦局促。","唯師草聖藝偏高，一掬山泉心便足。"]', '诗', 'shi', '', NULL, '{巩/言}光大師草書歌 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41002bdd-8178-4a0c-855a-04893a35a6ae', '題成都玉局觀孫位畫龍', '題成都玉局观孫位畫龙', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["我見蘇州崑山佛殿中，金城柱上有二龍。","老僧相傳道是僧繇手，尋常入海共龍鬬。","又聞蜀國玉局觀有孫遇蹟，蟠屈身長八十尺。","遊人爭看不敢近，頭覻寒泉萬丈碧。"]', '["我见蘇州崑山佛殿中，金城柱上有二龙。","老僧相傳道是僧繇手，尋常入海共龙鬬。","又闻蜀国玉局观有孫遇蹟，蟠屈身长八十尺。","游人爭看不敢近，头覻寒泉万丈碧。"]', '诗', 'shi', '', NULL, '題成都玉局觀孫位畫龍 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e33ac1-1d66-4f21-965d-6fd48693fee2', '觀地獄圖', '观地獄圖', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["峨峨非劒閣，有樹不堪攀。","佛手遮不得，人心似等閑。","周王應未雪，白起作何顏。","盡日空彈指，茫茫塵世間。"]', '["峨峨非劒閣，有樹不堪攀。","佛手遮不得，人心似等闲。","周王應未雪，白起作何顏。","尽日空彈指，茫茫塵世间。"]', '诗', 'shi', '', NULL, '觀地獄圖 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d604def2-02ce-45b6-99c2-9f8f0e1a7651', '贈雷卿張明府', '贈雷卿張明府', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["任官征戰後，度日寄閑身。","封卷還高客，飛書問野人。","廢田教種穀，生路遣尋薪。","若起柴桑興，無先漉酒巾。"]', '["任官征戰後，度日寄闲身。","封卷還高客，飞书问野人。","廢田教種穀，生路遣尋薪。","若起柴桑兴，無先漉酒巾。"]', '诗', 'shi', '', NULL, '贈雷卿張明府 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c39edcf7-7ab6-46a8-9bb0-ef3b5a628753', '獻錢尚父', '獻錢尚父', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["貴逼人來不自由，龍驤鳳翥勢難收。","滿堂花醉三千客，一劒霜寒十四州。","鼓角揭天嘉氣冷，風濤動地海山秋。","東南永作金天柱，誰羨當時萬戶侯。"]', '["貴逼人来不自由，龙驤鳳翥勢难收。","满堂花醉三千客，一劒霜寒十四州。","鼓角揭天嘉氣冷，风濤动地海山秋。","东南永作金天柱，誰羨當时万戶侯。"]', '诗', 'shi', '', NULL, '獻錢尚父 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c76f37f1-efad-4125-aa0a-a0da55b293ec', '繡州張相公見訪', '繡州張相公见訪', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["德符唐德瑞通天，曾叱讒諛玉座前。","千襲彩衣宮錦薄，數牀御札主恩偏。","出師暫放張良箸，得罪惟撐范蠡船。","未報君恩終必報，不妨金地禮青蓮。"]', '["德符唐德瑞通天，曾叱讒諛玉座前。","千襲彩衣宮錦薄，數牀御札主恩偏。","出師暫放張良箸，得罪惟撐范蠡船。","未報君恩終必報，不妨金地禮青蓮。"]', '诗', 'shi', '', NULL, '繡州張相公見訪 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1206a6b8-5634-4094-81a7-32a0caf50a83', '題某公宅', '題某公宅', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["宅成天下借圖看，始笑平生眼力慳。","地占百灣多是水，樓無一面不當山。","荷深似入苕溪路，石怪疑行鴈蕩間。","只恐中原方鼎沸，天心未遣主人閑。"]', '["宅成天下借圖看，始笑平生眼力慳。","地占百灣多是水，楼無一面不當山。","荷深似入苕溪路，石怪疑行鴈蕩间。","只恐中原方鼎沸，天心未遣主人闲。"]', '诗', 'shi', '', NULL, '題某公宅 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca22768e-68f7-49f6-9d79-8510fbde9b7f', '海覺禪師山院', '海覺禪師山院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["人言海覺老宗師，隱絕層巔世莫知。","青草不生行道跡，白雲常護坐禪扉。","六環金錫飛來後，一派銀河瀉落時。","借問大心能濟物，龍門風雹捲天池。"]', '["人言海覺老宗師，隐絕層巔世莫知。","青草不生行道跡，白云常護坐禪扉。","六环金錫飞来後，一派銀河瀉落时。","借问大心能濟物，龙门风雹捲天池。"]', '诗', 'shi', '', NULL, '海覺禪師山院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86db44bb-e795-46ea-93c8-1639f9d38bcb', '悼張道古', '悼張道古', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["清河逝水大悤悤，東觀無人失至公。","天上君恩三載隔，鑑中鸞影一時空。","墳生苦霧蒼茫外，門掩寒雲寂寞中。","惆悵斯人又如此，一聲蠻笛滿江風。"]', '["清河逝水大悤悤，东观無人失至公。","天上君恩三載隔，鑑中鸾影一时空。","墳生苦霧蒼茫外，门掩寒云寂寞中。","惆悵斯人又如此，一声蠻笛满江风。"]', '诗', 'shi', '', NULL, '悼張道古 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b14b868b-a12f-40f7-a9f9-40d3b976e7e6', '月夕', '月夕', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["霜月夜裴回，樓中羌笛催。","曉風吹不盡，江上落殘梅。"]', '["霜月夜裴回，楼中羌笛催。","晓风吹不尽，江上落殘梅。"]', '诗', 'shi', '', NULL, '月夕 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250caca0-1923-45da-af7c-b6e30bafe065', '夜雨', '夜雨', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["夜雨山草濕，爽籟雜枯木。","閑吟笁仙偈，清絕過于玉。"]', '["夜雨山草濕，爽籟杂枯木。","闲吟笁仙偈，清絕過于玉。"]', '诗', 'shi', '', NULL, '夜雨 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84290a47-4e78-4463-a1a5-59124b398cd7', '晚望', '晚望', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["落日碧江靜，蓮唱清且閑。","更尋花發處，借月過前灣。"]', '["落日碧江静，蓮唱清且闲。","更尋花發处，借月過前灣。"]', '诗', 'shi', '', NULL, '晚望 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('841abb9e-9d47-4d1b-ab12-e12faaaedb60', '早霜寄蔡大', '早霜寄蔡大', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["昨夜楚鐘鳴，飛霜下楚城。","定知遷客鬢，先向鑑中生。"]', '["昨夜楚鐘鳴，飞霜下楚城。","定知遷客鬢，先向鑑中生。"]', '诗', 'shi', '', NULL, '早霜寄蔡大 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34bd8a4d-e3b7-4da1-abbb-8fefa4256a05', '贈寫經僧楚雲', '贈寫經僧楚云', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["剔皮刺血誠何苦，爲寫靈山九會文。","十指瀝乾終七軸，後來求法更無君。"]', '["剔皮刺血誠何苦，爲寫靈山九會文。","十指瀝乾終七軸，後来求法更無君。"]', '诗', 'shi', '', NULL, '贈寫經僧楚雲 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('577c4ebf-a237-43c8-ace3-0f32a8418607', '寄題詮律師院', '寄題詮律師院', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["錦溪光裏聳樓臺，師院高凌積翠開。","深竹杪聞殘磐盡，一茶中見數帆來。","焚香只是看新律，幽步猶疑損綠苔。","莫訝題詩又東去，石房清冷在天台。"]', '["錦溪光裏聳楼台，師院高凌積翠开。","深竹杪闻殘磐尽，一茶中见數帆来。","焚香只是看新律，幽步猶疑損綠苔。","莫訝題诗又东去，石房清冷在天台。"]', '诗', 'shi', '', NULL, '寄題詮律師院 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ff4ac11-4a8f-4ad9-977e-d7deb6127bd1', '寄天台葉道士', '寄天台葉道士', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["負局高風不可陪，玉霄峯北置樓臺。","注參同契未將出，尋楖栗僧多宿來。","颼槭松風山棗落，閒關溪鳥朮花開。","終須肘後相傳好，莫便乘鸞去不迴。"]', '["負局高风不可陪，玉霄峯北置楼台。","注參同契未將出，尋楖栗僧多宿来。","颼槭松风山棗落，閒关溪鸟朮花开。","終須肘後相傳好，莫便乘鸾去不迴。"]', '诗', 'shi', '', NULL, '寄天台葉道士 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a502043-8347-4426-9f2f-d9ecce39a62e', '送道友歸天台', '送道友归天台', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蘚濃苔濕冷層層，珍重先生獨去登。","氣養三田傳未得，藥非八石許還曾。","雲根應狎玉斧子，月逕多尋銀地僧。","太守苦留終不住，可憐江上去騰騰。"]', '["蘚濃苔濕冷層層，珍重先生独去登。","氣養三田傳未得，藥非八石許還曾。","云根應狎玉斧子，月逕多尋銀地僧。","太守苦留終不住，可怜江上去腾腾。"]', '诗', 'shi', '', NULL, '送道友歸天台 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b99d516-4282-45fd-9abd-5ebbdbe1e8df', '陶種柑橙令山童買之', '陶種柑橙令山童買之', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["高步南山南，高歌北山北。","數載買柑橙，山資近又足。"]', '["高步南山南，高歌北山北。","數載買柑橙，山資近又足。"]', '诗', 'shi', '', NULL, '陶種柑橙令山童買之 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ae9b7d7-62ef-460a-a241-bdc13382c555', '春送僧', '春送僧', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["蜀魄關關花雨深，送師衝雨到江潯。","不能更折江頭柳，自有青青松柏心。"]', '["蜀魄关关花雨深，送師衝雨到江潯。","不能更折江头柳，自有青青松柏心。"]', '诗', 'shi', '', NULL, '春送僧 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9880c4d-e0a5-485c-8b1f-3c3553d38006', '律師', '律師', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["薝蔔花紅徑草青，雪膚冰骨步輕輕。","今朝暫到焚香處，只恐牀前有蝨聲。"]', '["薝蔔花紅徑草青，雪膚冰骨步轻轻。","今朝暫到焚香处，只恐牀前有蝨声。"]', '诗', 'shi', '', NULL, '律師 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e5d341d-73a5-4352-81b9-49dc9673e9b3', '書石壁禪居屋壁', '书石壁禪居屋壁', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["赤旃檀塔六七級，白菡萏花三四枝。","禪客相逢只彈指，此心能有幾人知。"]', '["赤旃檀塔六七級，白菡萏花三四枝。","禪客相逢只彈指，此心能有幾人知。"]', '诗', 'shi', '', NULL, '書石壁禪居屋壁 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82945f4b-9b24-4610-a96a-b61fb9bf0c4a', '句', '句', '5c0b571b-6de6-475b-8818-d8155d362f65', '唐', '["今日再三難更識，讖辭唯道待錢來。","鴈蕩經行雲漠漠，龍湫宴坐雨濛濛。","刻成箏柱鴈相挨。","黃昏風雨黑如磐，別我不知何處去。","郭尚父休誇塞北，裴中令莫說淮西。","萬計交人買，華軒保惜深。","如何忠爲主，至竟不封侯。","但看千騎去，知有幾人歸。","一生不蓄買田錢，華屋何心亦偶然。","客至多逢僧在坐，釣歸惟許鶴隨船。","家爲買琴添舊價，廚因養鶴減晨炊。","黏粉爲題棲鳳竹，帶香因洗落花泉。"]', '["今日再三难更識，讖辞唯道待錢来。","鴈蕩經行云漠漠，龙湫宴坐雨濛濛。","刻成箏柱鴈相挨。","黄昏风雨黑如磐，別我不知何处去。","郭尚父休誇塞北，裴中令莫说淮西。","万計交人買，华軒保惜深。","如何忠爲主，至竟不封侯。","但看千騎去，知有幾人归。","一生不蓄買田錢，华屋何心亦偶然。","客至多逢僧在坐，釣归惟許鹤隨船。","家爲買琴添旧價，廚因養鹤減晨炊。","黏粉爲題棲鳳竹，带香因洗落花泉。"]', '诗', 'shi', '', NULL, '句 貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d56305d8-52ec-43b1-bb8f-d31eabfd0185', '夏日草堂作', '夏日草堂作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["沙泉帶草堂，紙帳卷空牀。","靜是真消息，吟非俗肺腸。","園林坐清影，梅杏嚼紅香。","誰住原西寺，鐘聲送夕陽。"]', '["沙泉带草堂，紙帳卷空牀。","静是真消息，吟非俗肺腸。","园林坐清影，梅杏嚼紅香。","誰住原西寺，鐘声送夕陽。"]', '诗', 'shi', '', NULL, '夏日草堂作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc775ba-d10c-4bc5-80bd-44e37559a24d', '寄鏡湖方干處士', '寄镜湖方干处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["賀監舊山川，空來近百年。","聞君與琴鶴，終日在漁船。","島露深秋石，湖澄半夜天。","雲門幾迴去，題徧好林泉。"]', '["賀監旧山川，空来近百年。","闻君與琴鹤，終日在漁船。","島露深秋石，湖澄半夜天。","云门幾迴去，題徧好林泉。"]', '诗', 'shi', '', NULL, '寄鏡湖方干處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07ad9594-0b2f-4dbf-9e0a-15b78b3175c8', '送人歸吳', '送人归吳', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["比說歸耕釣，迢迢向海涯。","春寒游子路，村晚主人家。","□□□□□，□山綠過茶。","重尋舊鄰里，菱藕正開花。"]', '["比说归耕釣，迢迢向海涯。","春寒游子路，村晚主人家。","□□□□□，□山綠過茶。","重尋旧鄰里，菱藕正开花。"]', '诗', 'shi', '', NULL, '送人歸吳 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44dcf956-3bba-47c6-82e2-bbd2aa3dee77', '贈仰上人', '贈仰上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["避地依真境，安閒似舊溪。","干戈百里外，泉石亂峰西。","草瑞香難歇，松靈蓋盡低。","尋應報休馬，瓶錫向南攜。"]', '["避地依真境，安閒似旧溪。","干戈百里外，泉石亂峰西。","草瑞香难歇，松靈蓋尽低。","尋應報休马，瓶錫向南携。"]', '诗', 'shi', '', NULL, '贈仰上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b56350fa-e151-41c0-95e0-255f150fce02', '夜坐', '夜坐', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["百蟲聲裏坐，夜色共冥冥。","遠憶諸峰頂，曾栖此性靈。","月華澄有象，詩思在無形。","徹曙都忘寢，虛牕日照經。"]', '["百蟲声裏坐，夜色共冥冥。","远憶諸峰頂，曾栖此性靈。","月华澄有象，诗思在無形。","徹曙都忘寢，虛牕日照經。"]', '诗', 'shi', '', NULL, '夜坐 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('089af8ba-1989-4556-8c4a-bfad31509fee', '新栽松', '新栽松', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["野僧教種法，苒苒出蓬蒿。","百歲催人老，千年待爾高。","靜宜兼竹石，幽合近猨猱。","他日成陰後，秋風吹海濤。"]', '["野僧教種法，苒苒出蓬蒿。","百歲催人老，千年待爾高。","静宜兼竹石，幽合近猨猱。","他日成陰後，秋风吹海濤。"]', '诗', 'shi', '', NULL, '新栽松 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3437e6d0-4bc3-436e-a3bd-01819bd789dd', '期友人', '期友人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["早晚逐茲來，閑門日爲開。","亂蛩鳴白草，殘菊藉蒼苔。","困臥誰驚起，閑行自欲迴。","何時此攜手，吾子本多才。"]', '["早晚逐茲来，闲门日爲开。","亂蛩鳴白草，殘菊藉蒼苔。","困臥誰驚起，闲行自欲迴。","何时此携手，吾子本多才。"]', '诗', 'shi', '', NULL, '期友人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63a24942-856d-4cb0-8cff-9cf8ffd413be', '和鄭谷郎中看棊', '和鄭谷郎中看棊', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["箇是仙家事，何人合用心。","幾時終一局，萬木老千岑。","有路如飛出，無機似陸沈。","樵夫可能解，也此廢光陰。"]', '["箇是仙家事，何人合用心。","幾时終一局，万木老千岑。","有路如飞出，無機似陸沈。","樵夫可能解，也此廢光陰。"]', '诗', 'shi', '', NULL, '和鄭谷郎中看棊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc10952-f0bf-4d70-959a-34ae4379c98d', '寄錢塘羅給事', '寄錢塘羅給事', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["憤憤嘔讒書，無人誦子虛。","傷心天祐末，搔首懿宗初。","海樹青叢短，湖山翠點疎。","秋濤看足否，羅剎石邊居。"]', '["憤憤嘔讒书，無人誦子虛。","傷心天祐末，搔首懿宗初。","海樹青叢短，湖山翠点疎。","秋濤看足否，羅剎石邊居。"]', '诗', 'shi', '', NULL, '寄錢塘羅給事 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93a1791f-1127-44f0-bad8-4f18ea9f999f', '戊辰歲湘中寄鄭谷郎中', '戊辰歲湘中寄鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["白髮久慵簪，常聞病亦吟。","瘦應成鶴骨，閑想似禪心。","上國楊花亂，滄洲荻笋深。","不堪思翠巘，西望獨沾襟。"]', '["白髮久慵簪，常闻病亦吟。","瘦應成鹤骨，闲想似禪心。","上国楊花亂，滄洲荻笋深。","不堪思翠巘，西望独沾襟。"]', '诗', 'shi', '', NULL, '戊辰歲湘中寄鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e619aaab-2603-43fc-a3a5-2e222a37abe0', '寓言', '寓言', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["造化安能保，山川鑿欲翻。","精華銷地底，珠玉聚侯門。","始作驕奢本，終爲禍亂根。","亡家與亡國，云此更何言。"]', '["造化安能保，山川鑿欲翻。","精华銷地底，珠玉聚侯门。","始作驕奢本，終爲禍亂根。","亡家與亡国，云此更何言。"]', '诗', 'shi', '', NULL, '寓言 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e187a5bb-1427-43ed-8813-02fe5f7528db', '寄王振拾遺', '寄王振拾遺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["折檻意何如，平安信不虛。","近來焚諫草，深去覓山居。","□□□□□，□□□□餘。","分明知在處，難寄亂離書。"]', '["折檻意何如，平安信不虛。","近来焚諫草，深去覓山居。","□□□□□，□□□□餘。","分明知在处，难寄亂離书。"]', '诗', 'shi', '', NULL, '寄王振拾遺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71f16b34-f83a-4089-8b40-68a5da849811', '經賈島舊居', '經賈島旧居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["先生居處所，野燒幾爲灰。","若有吟魂在，應隨夜魄迴。","地寧銷志氣，天忍罪清才。","古木霜風晚，江禽共宿來。"]', '["先生居处所，野燒幾爲灰。","若有吟魂在，應隨夜魄迴。","地寧銷志氣，天忍罪清才。","古木霜风晚，江禽共宿来。"]', '诗', 'shi', '', NULL, '經賈島舊居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6b781b8-b71c-466e-8110-000e9973f48e', '送人游塞', '送人游塞', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["槐柳野橋邊，行塵暗馬前。","秋風來漢地，客路入胡天。","鴈聚河流濁，羊羣磧草膻。","那堪隴頭宿，鄉夢逐潺湲。"]', '["槐柳野橋邊，行塵暗马前。","秋风来漢地，客路入胡天。","鴈聚河流濁，羊羣磧草膻。","那堪隴头宿，乡梦逐潺湲。"]', '诗', 'shi', '', NULL, '送人游塞 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22293a4c-c4c3-4010-9948-a5c1ea760360', '桃花', '桃花', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["千株含露態，何處照人紅？","風暖仙源裏，春和水國中。","流鶯應見落，舞蜨未知空。","擬欲求圖畫，枝枝帶竹叢。"]', '["千株含露態，何处照人紅？","风暖仙源裏，春和水国中。","流鶯應见落，舞蜨未知空。","擬欲求圖畫，枝枝带竹叢。"]', '诗', 'shi', '', NULL, '桃花 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a5d50e-5aa3-43b9-a7cb-4572d868c088', '聞鴈', '闻鴈', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["何處人驚起，飛來過草堂。","丹心勞避弋，萬里念隨陽。","影斷風天月，聲孤荻岸霜。","明年趁春去，江上別鴛鴦。"]', '["何处人驚起，飞来過草堂。","丹心勞避弋，万里念隨陽。","影斷风天月，声孤荻岸霜。","明年趁春去，江上別鴛鴦。"]', '诗', 'shi', '', NULL, '聞鴈 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98e44f41-26bd-49f9-9e41-49910bf7953e', '送人遊南', '送人游南', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["南國多山水，君遊興可知。","船中江上景，晚泊早行時。","子美遺魂地，藏真舊墨池。","經過幾銷日，荒草裏尋碑。"]', '["南国多山水，君游兴可知。","船中江上景，晚泊早行时。","子美遺魂地，藏真旧墨池。","經過幾銷日，荒草裏尋碑。"]', '诗', 'shi', '', NULL, '送人遊南 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f3b4c5-9dd4-4e45-aaab-98566f58d8f0', '送益公歸舊居', '送益公归旧居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊隱終牽夢，春殘結束歸。","溪山無伴過，風雨有花飛。","片石留題字，孤潭照浣衣。","鄰僧喜相接，埽逕與開扉。"]', '["旧隐終牽梦，春殘結束归。","溪山無伴過，风雨有花飞。","片石留題字，孤潭照浣衣。","鄰僧喜相接，埽逕與开扉。"]', '诗', 'shi', '', NULL, '送益公歸舊居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec65acb-a2e6-4881-a6a3-41e47d8e4d95', '不睡', '不睡', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["永夜不欲睡，虛堂閉復開。","却離燈影去，待得月光來。","落葉逢巢住，飛螢值我迴。","天明拂經案，一炷白檀灰。"]', '["永夜不欲睡，虛堂閉复开。","却離灯影去，待得月光来。","落葉逢巢住，飞螢值我迴。","天明拂經案，一炷白檀灰。"]', '诗', 'shi', '', NULL, '不睡 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c5ac245-b8c6-4795-884b-5202a69f4395', '新秋雨後', '新秋雨後', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["夜雨洗河漢，詩懷覺有靈。","籬聲新蟋蟀，草影老蜻蜓。","靜引閑機發，涼吹遠思醒。","逍遙向誰說，時注漆園經。"]', '["夜雨洗河漢，诗懷覺有靈。","籬声新蟋蟀，草影老蜻蜓。","静引闲機發，涼吹远思醒。","逍遙向誰说，时注漆园經。"]', '诗', 'shi', '', NULL, '新秋雨後 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('387efba8-9b97-4768-95cb-f07d8280a5da', '送劉蛻秀才赴舉', '送劉蛻秀才赴舉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["百發百中□，□□□□年。","丹枝如計分，一箭的無偏。","文物兵銷國，關河雪霽天。","都人看春牓，韓字在誰前。"]', '["百發百中□，□□□□年。","丹枝如計分，一箭的無偏。","文物兵銷国，关河雪霽天。","都人看春牓，韓字在誰前。"]', '诗', 'shi', '', NULL, '送劉蛻秀才赴舉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8c4f85d-2248-4731-84ed-00a5a5cf804b', '留題仰山大師塔院', '留題仰山大師塔院', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["嵐光疊杳冥，曉翠濕窗明。","欲起遊方去，重來繞塔行。","亂雲開鳥道，羣木發秋聲。","曾約諸徒弟，香燈盡此生。"]', '["嵐光叠杳冥，晓翠濕窗明。","欲起游方去，重来繞塔行。","亂云开鸟道，羣木發秋声。","曾約諸徒弟，香灯尽此生。"]', '诗', 'shi', '', NULL, '留題仰山大師塔院 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652c3575-2ca8-4931-b0db-c4057eff07c8', '亂中聞鄭谷吳延保下世', '亂中闻鄭谷吳延保下世', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["小諫纔埋玉，星郎亦逝川。","國由多聚盜，天似不容賢。","兵火焚詩草，江流漲墓田。","長安已塗炭，追想更淒然。"]', '["小諫纔埋玉，星郎亦逝川。","国由多聚盜，天似不容賢。","兵火焚诗草，江流漲墓田。","长安已塗炭，追想更淒然。"]', '诗', 'shi', '', NULL, '亂中聞鄭谷吳延保下世 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2011e0a5-5b95-4c21-9a43-97c243e169d2', '送東林寺睦公往吳國', '送东林寺睦公往吳国', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["八月江行好，風帆日夜飄。","煙霞經北固，禾黍過南朝。","社客無宗炳，詩家有鮑昭。","莫因賢相請，不返舊山椒。"]', '["八月江行好，风帆日夜飄。","煙霞經北固，禾黍過南朝。","社客無宗炳，诗家有鲍昭。","莫因賢相請，不返旧山椒。"]', '诗', 'shi', '', NULL, '送東林寺睦公往吳國 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08296017-2fa9-4227-9fa5-850ad4db1833', '除夜', '除夜', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["夜久誰同坐，爐寒鼎亦澄。","亂松飄雨雪，一室掩香燈。","白髮添新歲，清吟減舊朋。","明朝待晴旭，池上看春冰。"]', '["夜久誰同坐，爐寒鼎亦澄。","亂松飄雨雪，一室掩香灯。","白髮添新歲，清吟減旧朋。","明朝待晴旭，池上看春冰。"]', '诗', 'shi', '', NULL, '除夜 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('121489aa-4a00-4dea-89eb-5516530db8dd', '送祕上人', '送祕上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["誰喜老閑身，春山起送君。","欲憑蓮社信，轉入洞庭雲。","道路長無阻，干戈漸不聞。","秋來向何處，相憶鴈成羣。"]', '["誰喜老闲身，春山起送君。","欲憑蓮社信，轉入洞庭云。","道路长無阻，干戈漸不闻。","秋来向何处，相憶鴈成羣。"]', '诗', 'shi', '', NULL, '送祕上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f2f7eda-d888-4c0d-9494-967e08ed3ea3', '寓居嶽麓謝進士沈彬再訪', '寓居嶽麓謝進士沈彬再訪', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["去歲來尋我，留題在蘚痕。","又因風雪夜，重宿古松門。","玉有疑休泣，詩無主且言。","明朝此相送，披褐入桃源。"]', '["去歲来尋我，留題在蘚痕。","又因风雪夜，重宿古松门。","玉有疑休泣，诗無主且言。","明朝此相送，披褐入桃源。"]', '诗', 'shi', '', NULL, '寓居嶽麓謝進士沈彬再訪 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c75267e1-beaa-44fb-81e8-98da18107f3a', '對雪', '对雪', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["松門堆復積，埋石亦埋莎。","爲瑞還難得，居貧莫厭多。","聽憐終夜落，吟惜一年過。","誰在江樓望，漫漫墮綠波。"]', '["松门堆复積，埋石亦埋莎。","爲瑞還难得，居貧莫厭多。","听怜終夜落，吟惜一年過。","誰在江楼望，漫漫墮綠波。"]', '诗', 'shi', '', NULL, '對雪 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb0a53de-28f1-4e0e-8d99-ac257ff10ff2', '和岷公送李評事往宜春', '和岷公送李評事往宜春', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["兵火銷鄰境，龍沙有去人。","江潭牽興遠，風物入題新。","雪湛將殘臘，霞明向早春。","郡侯開宴處，桃李照歌塵。"]', '["兵火銷鄰境，龙沙有去人。","江潭牽兴远，风物入題新。","雪湛將殘臘，霞明向早春。","郡侯开宴处，桃李照歌塵。"]', '诗', 'shi', '', NULL, '和岷公送李評事往宜春 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cab60911-500a-49ec-9f37-1889b03ebdec', '送僧', '送僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["老憶遊方日，天涯錫獨搖。","凌晨從北固，衝雪向南朝。","鬢髮泉邊剃，香燈樹下燒。","雙峰諸道友，夏滿有書招。"]', '["老憶游方日，天涯錫独搖。","凌晨從北固，衝雪向南朝。","鬢髮泉邊剃，香灯樹下燒。","雙峰諸道友，夏满有书招。"]', '诗', 'shi', '', NULL, '送僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('419b83aa-b19f-4f6e-bad8-e4a345b4c748', '過荆門', '過荆门', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["路出荆門遠，行行日欲西。","草枯蠻塚亂，山斷漢江低。","野店叢蒿短，煙村簇樹齊。","翻思故林去，在處有猨啼。"]', '["路出荆门远，行行日欲西。","草枯蠻塚亂，山斷漢江低。","野店叢蒿短，煙村簇樹齊。","翻思故林去，在处有猨啼。"]', '诗', 'shi', '', NULL, '過荆門 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d8b285b-6ca2-4e35-ac95-5fbd66b6238c', '山中荅人', '山中荅人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["謾道詩名出，何曾著苦吟。","忽來還有意，已過即無心。","夏月山長往，霜天寺獨尋。","故人憐拙朴，時復寄空林。"]', '["謾道诗名出，何曾著苦吟。","忽来還有意，已過即無心。","夏月山长往，霜天寺独尋。","故人怜拙朴，时复寄空林。"]', '诗', 'shi', '', NULL, '山中荅人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c8ec99-8d0c-4c2e-8735-5f7651ab7072', '贈盧明府閑居', '贈盧明府闲居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鬢霜垂七十，江國久辭官。","滿篋新風雅，何人舊歲寒。","閑居當野水，幽鳥宿漁竿。","終欲相尋去，兵戈時轉難。"]', '["鬢霜垂七十，江国久辞官。","满篋新风雅，何人旧歲寒。","闲居當野水，幽鸟宿漁竿。","終欲相尋去，兵戈时轉难。"]', '诗', 'shi', '', NULL, '贈盧明府閑居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61447f61-c0d4-47c4-ac26-1644ba239fd5', '幽庭', '幽庭', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["不放生纖草，從教徧綠苔。","還防長者至，未著牡丹栽。","蛺蝶空飛過，鶺鴒時下來。","南鄰折芳子，到此寂寥迴。"]', '["不放生纖草，從教徧綠苔。","還防长者至，未著牡丹栽。","蛺蝶空飞過，鶺鴒时下来。","南鄰折芳子，到此寂寥迴。"]', '诗', 'shi', '', NULL, '幽庭 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3262a25-fa6e-480c-b9e3-09e21358c1ba', '送休師歸長沙寧覲', '送休師归长沙寧覲', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["吾子此歸寧，風煙是舊經。","無窮芳草色，何處故山青？","偶泊鳴蟬島，難眠好月汀。","殷勤問安外，湘岸採詩靈。"]', '["吾子此归寧，风煙是旧經。","無窮芳草色，何处故山青？","偶泊鳴蟬島，难眠好月汀。","殷勤问安外，湘岸採诗靈。"]', '诗', 'shi', '', NULL, '送休師歸長沙寧覲 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07fd4fb1-ae0a-42e6-8d74-23a07217c46e', '將遊嵩華行次荆渚', '將游嵩华行次荆渚', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["蓮峰映敷水，嵩嶽壓伊河。","兩處思歸久，前賢隱去多。","閑身應絕跡，在世幸無他。","會向紅霞嶠，僧龕對薜蘿。"]', '["蓮峰映敷水，嵩嶽壓伊河。","兩处思归久，前賢隐去多。","闲身應絕跡，在世幸無他。","會向紅霞嶠，僧龕对薜蘿。"]', '诗', 'shi', '', NULL, '將遊嵩華行次荆渚 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a21b4ce5-902b-4668-aa27-d28892a8aaa2', '遠思', '远思', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["遠思極何處，南樓煙水長。","秋風過鴻鴈，遊子在瀟湘。","海面雲生白，天涯墮晚光。","徘徊古堤上，曾此贈垂楊。"]', '["远思極何处，南楼煙水长。","秋风過鴻鴈，游子在瀟湘。","海面云生白，天涯墮晚光。","徘徊古堤上，曾此贈垂楊。"]', '诗', 'shi', '', NULL, '遠思 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e270394-f4da-4491-b01a-213d4f2b57a1', '寄勉二三子', '寄勉二三子', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["不見二三子，悠然吳楚間。","盡應生白髮，幾箇在青山。","□□□□□，□□莫放閑。","君聞國風否，千秋詠關關。"]', '["不见二三子，悠然吳楚间。","尽應生白髮，幾箇在青山。","□□□□□，□□莫放闲。","君闻国风否，千秋詠关关。"]', '诗', 'shi', '', NULL, '寄勉二三子 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d52dbae-43b9-45c3-adf6-0254bdbc7f4d', '渚宮江亭寓目', '渚宮江亭寓目', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["津亭雖極望，未稱本心閑。","白有三江水，青無一點山。","新鴻喧夕浦，遠櫂聚空灣。","終遂歸匡社，孤帆即此還。"]', '["津亭雖極望，未稱本心闲。","白有三江水，青無一点山。","新鴻喧夕浦，远櫂聚空灣。","終遂归匡社，孤帆即此還。"]', '诗', 'shi', '', NULL, '渚宮江亭寓目 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b3b2817-a0d7-4afc-aa67-c88a6e8ead55', '蝴蝶', '蝴蝶', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["何處背繁紅，迷芳到檻重。","分飛還獨出，成隊偶相逢。","遠害終防雀，爭先不避蜂。","桃蹊牽往復，蘭徑引相從。","翠裛丹心冷，香凝粉翅濃。","可尋穿樹影，難覓宿花蹤。","日晚來仍急，春殘舞未慵。","西風舊池館，猶得採芙蓉。"]', '["何处背繁紅，迷芳到檻重。","分飞還独出，成隊偶相逢。","远害終防雀，爭先不避蜂。","桃蹊牽往复，蘭徑引相從。","翠裛丹心冷，香凝粉翅濃。","可尋穿樹影，难覓宿花蹤。","日晚来仍急，春殘舞未慵。","西风旧池館，猶得採芙蓉。"]', '诗', 'shi', '', NULL, '蝴蝶 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba3d0f58-a3e6-4985-8f8c-415e07bc59c0', '送劉秀才往東洛', '送劉秀才往东洛', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["羨子去東周，行行非旅遊。","煙霄有兄弟，事業盡曹劉。","洛水清奔夏，嵩雲白入秋。","來年遂鵬化，一舉上瀛洲。"]', '["羨子去东周，行行非旅游。","煙霄有兄弟，事業尽曹劉。","洛水清奔夏，嵩云白入秋。","来年遂鵬化，一舉上瀛洲。"]', '诗', 'shi', '', NULL, '送劉秀才往東洛 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c141ef3-f5b2-4382-b66a-d2724528f618', '移竹', '移竹', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊溪千萬竿，風雨夜珊珊。","白首來江國，黃金買歲寒。","乍移傷粉節，終遶著朱欄。","會得承春力，新抽錦籜看。"]', '["旧溪千万竿，风雨夜珊珊。","白首来江国，黄金買歲寒。","乍移傷粉節，終遶著朱欄。","會得承春力，新抽錦籜看。"]', '诗', 'shi', '', NULL, '移竹 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7891348a-8f0d-4d17-968c-78fa45a724ab', '雉', '雉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["角角類關關，春晴錦羽乾。","文呈五色異，瑞入九苞難。","暮宿紅蘭暖，朝飛綠野寒。","山梁從行者，錯解仲尼歎。"]', '["角角類关关，春晴錦羽乾。","文呈五色異，瑞入九苞难。","暮宿紅蘭暖，朝飞綠野寒。","山梁從行者，錯解仲尼歎。"]', '诗', 'shi', '', NULL, '雉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f263415a-363d-4b13-8abb-72952bbbfb52', '懷軒轅先生', '懷軒轅先生', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["不得先生信，空懷汗漫秋。","月華離鶴背，日影上鼇頭。","欲學孤雲去，其如重骨留。","槎程在何處，人世屢荒丘。"]', '["不得先生信，空懷汗漫秋。","月华離鹤背，日影上鼇头。","欲学孤云去，其如重骨留。","槎程在何处，人世屢荒丘。"]', '诗', 'shi', '', NULL, '懷軒轅先生 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50c91c7f-2ccd-44fa-939c-cb466c201378', '永夜感懷寄鄭谷郎中', '永夜感懷寄鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["展轉復展轉，所思安可論。","夜涼難就枕，月好重開門。","霜殺百草盡，蛩歸四壁根。","生來苦章句，早遇至公言。"]', '["展轉复展轉，所思安可論。","夜涼难就枕，月好重开门。","霜殺百草尽，蛩归四壁根。","生来苦章句，早遇至公言。"]', '诗', 'shi', '', NULL, '永夜感懷寄鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f88174-575a-4b67-b695-47ab2052791e', '賣松者', '賣松者', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["未得凌雲價，何慙所買真。","自知桃李世，有愛歲寒人。","瑟瑟初離澗，青青未識塵。","寧同買花者，貴逐片時春。"]', '["未得凌云價，何慙所買真。","自知桃李世，有愛歲寒人。","瑟瑟初離澗，青青未識塵。","寧同買花者，貴逐片时春。"]', '诗', 'shi', '', NULL, '賣松者 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3fb6171-5605-4094-90d1-9be740851bf4', '丙寅歲寄潘歸仁', '丙寅歲寄潘归仁', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["九土盡荒墟，干戈殺害餘。","更須憂去國，未可守貧居。","康泰終來在，編聯莫破除。","他年遇知己，無恥報襜褕。"]', '["九土尽荒墟，干戈殺害餘。","更須憂去国，未可守貧居。","康泰終来在，編聯莫破除。","他年遇知己，無恥報襜褕。"]', '诗', 'shi', '', NULL, '丙寅歲寄潘歸仁 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eced4d25-e7f5-4fcc-b147-f015978e7844', '嘗茶', '嘗茶', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["石屋晚煙生，松窗鐵碾聲。","因留來客試，共說寄僧名。","味擊詩魔亂，香搜睡思輕。","春風霅川上，憶傍綠叢行。"]', '["石屋晚煙生，松窗鐵碾声。","因留来客試，共说寄僧名。","味擊诗魔亂，香搜睡思轻。","春风霅川上，憶傍綠叢行。"]', '诗', 'shi', '', NULL, '嘗茶 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d662dbbb-8328-4253-83b9-fd5a5112e556', '楊花', '楊花', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["暖景照悠悠，遮空勢漸稠。","乍如飛雪遠，未似落花休。","萬帶都門外，千株渭水頭。","紛紜知近夏，銷歇恐成秋。","軟著朝簪去，狂隨別騎遊。","斾衝離館驛，鶯撲繞宮樓。","江國晴愁對，池塘晚見浮。","虛窗縈筆雅，深院藉苔幽。","靜墮王孫酒，繁黏客子裘。","詠吟何潔白，根本屬風流。","向日還輕舉，因風更自由。","不堪思汴岸，千里到揚州。"]', '["暖景照悠悠，遮空勢漸稠。","乍如飞雪远，未似落花休。","万带都门外，千株渭水头。","紛紜知近夏，銷歇恐成秋。","軟著朝簪去，狂隨別騎游。","斾衝離館驛，鶯撲繞宮楼。","江国晴愁对，池塘晚见浮。","虛窗縈笔雅，深院藉苔幽。","静墮王孫酒，繁黏客子裘。","詠吟何潔白，根本屬风流。","向日還轻舉，因风更自由。","不堪思汴岸，千里到揚州。"]', '诗', 'shi', '', NULL, '楊花 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('737cbc0b-05ce-43c2-bd8b-81672ec782f8', '詠影', '詠影', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["萬物患有象，不能逃大明。","始隨殘魄滅，又逐曉光生。","曲直寧相隱，洪纖必自呈。","還如至公世，洞鑒是非情。"]', '["万物患有象，不能逃大明。","始隨殘魄滅，又逐晓光生。","曲直寧相隐，洪纖必自呈。","還如至公世，洞鑒是非情。"]', '诗', 'shi', '', NULL, '詠影 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('631c2be7-61c4-4114-9ea8-d9aaf7debc88', '南歸舟中二首 一', '南归舟中二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["南歸乘客櫂，道路免崎嶇。","江上經時節，船中聽鷓鴣。","春容含衆岫，雨氣泛平蕪。","落日停舟望，王維未有圖。"]', '["南归乘客櫂，道路免崎嶇。","江上經时節，船中听鷓鴣。","春容含衆岫，雨氣泛平蕪。","落日停舟望，王維未有圖。"]', '诗', 'shi', '', NULL, '南歸舟中二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daaf6ed2-12c0-4fd7-ac88-9d33271666fb', '南歸舟中二首 二', '南归舟中二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["長江春氣寒，客況櫂聲閑。","夜泊諸村雨，程迴數郡山。","桑根垂斷岸，浪沫聚空灣。","已去鄰園近，隨緣是暫還。"]', '["长江春氣寒，客況櫂声闲。","夜泊諸村雨，程迴數郡山。","桑根垂斷岸，浪沫聚空灣。","已去鄰园近，隨緣是暫還。"]', '诗', 'shi', '', NULL, '南歸舟中二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dbbe7b3-77bc-400c-b6aa-3b60281b1da9', '送遷客', '送遷客', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["天涯即愛州，謫去莫多愁。","若似承恩好，何如傍主休。","瘴昏銅柱黑，草赤火山秋。","應想堯陰下，當時獬豸頭。"]', '["天涯即愛州，謫去莫多愁。","若似承恩好，何如傍主休。","瘴昏銅柱黑，草赤火山秋。","應想堯陰下，當时獬豸头。"]', '诗', 'shi', '', NULL, '送遷客 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acfebc9f-3e72-4ff2-8ecb-f7945e84df2e', '題中上人院', '題中上人院', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["高房占境幽，講退即冥搜。","欠鶴同支遁，多詩似惠休。","缾澄孤井浪，案白小窗秋。","莫道歸山字，朝賢日獻酬。"]', '["高房占境幽，講退即冥搜。","欠鹤同支遁，多诗似惠休。","缾澄孤井浪，案白小窗秋。","莫道归山字，朝賢日獻酬。"]', '诗', 'shi', '', NULL, '題中上人院 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c6e3ced-47a1-49cb-aadd-39f08ad60e4a', '逢鄉友', '逢乡友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["無況來江島，逢君話滯留。","生緣同一國，相識共他州。","竹影斜青蘚，茶香在白甌。","猶憐心道合，多事亦冥搜。"]', '["無況来江島，逢君話滯留。","生緣同一国，相識共他州。","竹影斜青蘚，茶香在白甌。","猶怜心道合，多事亦冥搜。"]', '诗', 'shi', '', NULL, '逢鄉友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('500b7d8b-97ce-407e-a53f-4dde875fd4fb', '自勉', '自勉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["試筭平生事，中年欠五年。","知非未落後，讀易尚加前。","分受詩魔役，寧容俗態牽。","閑吟見秋水，數隻釣魚船。"]', '["試筭平生事，中年欠五年。","知非未落後，读易尚加前。","分受诗魔役，寧容俗態牽。","闲吟见秋水，數隻釣鱼船。"]', '诗', 'shi', '', NULL, '自勉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41138879-7e8f-4d84-b81c-58dac438a9f5', '寄詩友', '寄诗友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["天地有萬物，盡應輸苦心。","他人雖欲解，此道奈何深。","返朴遺時態，關門度歲陰。","相思去秋夕，共對冷燈吟。"]', '["天地有万物，尽應輸苦心。","他人雖欲解，此道奈何深。","返朴遺时態，关门度歲陰。","相思去秋夕，共对冷灯吟。"]', '诗', 'shi', '', NULL, '寄詩友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a01f571-9285-4d69-b9c0-4079095aab72', '居道林寺書懷', '居道林寺书懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["花落水喧喧，端居信晝昏。","誰來看山寺，自要埽松門。","是事皆能諱，唯詩未嬾言。","傳聞好時世，亦欲背啼猨。"]', '["花落水喧喧，端居信晝昏。","誰来看山寺，自要埽松门。","是事皆能諱，唯诗未嬾言。","傳闻好时世，亦欲背啼猨。"]', '诗', 'shi', '', NULL, '居道林寺書懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('095bbae9-6326-4c3f-ad15-7e8a8b77177a', '經吳平觀', '經吳平观', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["中元齋醮後，殘燼滿空壇。","老鶴心何待，尊師鬢已乾。","幡燈古殿夜，霜霰大椿寒。","誰見長生路，人間事萬端。"]', '["中元斋醮後，殘燼满空壇。","老鹤心何待，尊師鬢已乾。","幡灯古殿夜，霜霰大椿寒。","誰见长生路，人间事万端。"]', '诗', 'shi', '', NULL, '經吳平觀 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ac8299d-72ec-4370-baf0-2626058066f5', '劒客', '劒客', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["拔劒遶殘樽，歌終便出門。","西風滿天雪，何處報人恩。","勇死尋常事，輕讐不足論。","翻嫌易水上，細碎動離魂。"]', '["拔劒遶殘樽，歌終便出门。","西风满天雪，何处報人恩。","勇死尋常事，轻讐不足論。","翻嫌易水上，細碎动離魂。"]', '诗', 'shi', '', NULL, '劒客 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('840831a9-a13c-4449-85c2-7fb9b1a7ec31', '白髮', '白髮', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫染亦莫鑷，任從伊滿頭。","白雖無耐藥，黑也不禁秋。","靜枕聽蟬臥，閑垂看水流。","浮生未達此，多爲爾爲愁。"]', '["莫染亦莫鑷，任從伊满头。","白雖無耐藥，黑也不禁秋。","静枕听蟬臥，闲垂看水流。","浮生未達此，多爲爾爲愁。"]', '诗', 'shi', '', NULL, '白髮 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61b4087-6df3-4f7b-9acf-9c908ef38b83', '秋興寄胤公', '秋兴寄胤公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["風聲吹竹健，涼氣著身輕。","誰有閑心去，江邊看水行。","村遙紅樹遠，野闊白煙平。","試裂芭蕉片，題詩問竺卿。"]', '["风声吹竹健，涼氣著身轻。","誰有闲心去，江邊看水行。","村遙紅樹远，野闊白煙平。","試裂芭蕉片，題诗问竺卿。"]', '诗', 'shi', '', NULL, '秋興寄胤公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('264a1f1d-f76b-4d14-a28d-a5d9b59e5cd7', '野步', '野步', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["城裏無閑處，却尋城外行。","田園經雨水，鄉國憶桑耕。","傍澗蕨薇老，隔村岡隴橫。","何窮此心興，時復鷓鴣聲。"]', '["城裏無闲处，却尋城外行。","田园經雨水，乡国憶桑耕。","傍澗蕨薇老，隔村岡隴橫。","何窮此心兴，时复鷓鴣声。"]', '诗', 'shi', '', NULL, '野步 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('391d1b26-301e-481a-b98d-644efc8f499f', '殘春', '殘春', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["三月看無也，芳時此可嗟。","園林欲向夕，風雨更吹花。","影亂衝人蝶，聲繁遶塹蛙。","那堪傍楊柳，飛絮滿鄰家。"]', '["三月看無也，芳时此可嗟。","园林欲向夕，风雨更吹花。","影亂衝人蝶，声繁遶塹蛙。","那堪傍楊柳，飞絮满鄰家。"]', '诗', 'shi', '', NULL, '殘春 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c23e4b45-c7f6-4d15-a223-d2f49605dfe1', '酬尚顏', '酬尚顏', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["取盡風騷妙，名高身倍閑。","久離王者闕，欲向祖師山。","幕府秋招去，溪鄰日望還。","伊余豈酬敵，來往踏苔斑。"]', '["取尽风騷妙，名高身倍闲。","久離王者闕，欲向祖師山。","幕府秋招去，溪鄰日望還。","伊余豈酬敵，来往踏苔斑。"]', '诗', 'shi', '', NULL, '酬尚顏 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21000c47-63d8-4d83-b09a-86954a265e4c', '苦熱', '苦熱', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雲勢嶮於峰，金流斷竹風。","萬方應望雨，片景欲焚空。","毒害芙蓉死，煩蒸瀑布紅。","恩多是團扇，出入畫屏中。"]', '["云勢嶮於峰，金流斷竹风。","万方應望雨，片景欲焚空。","毒害芙蓉死，煩蒸瀑布紅。","恩多是團扇，出入畫屏中。"]', '诗', 'shi', '', NULL, '苦熱 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e4b0eca-5e02-46dd-a635-5b2376e98f61', '送歐陽秀才赴舉', '送歐陽秀才赴舉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫疑空手去，無援取高科。","直是文章好，爭如德行多。","煙霄心一寸，霜雪路千坡。","稱意東歸後，交親那喜何。"]', '["莫疑空手去，無援取高科。","直是文章好，爭如德行多。","煙霄心一寸，霜雪路千坡。","稱意东归後，交親那喜何。"]', '诗', 'shi', '', NULL, '送歐陽秀才赴舉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba5ff7e1-d6b9-4987-b75a-81a556dcb65c', '放鷺鷥', '放鷺鷥', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["潔白雖堪愛，腥膻不那何。","到頭從所欲，還汝舊滄波。"]', '["潔白雖堪愛，腥膻不那何。","到头從所欲，還汝旧滄波。"]', '诗', 'shi', '', NULL, '放鷺鷥 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afb290e4-6e86-4d10-9ff2-a4661c387d99', '謝王秀才見示詩卷', '謝王秀才见示诗卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["誰見少年心，低摧向苦吟。","後須離影響，得必洞精深。","道院春苔徑，僧樓夏竹林。","天如愛才子，何慮未知音。"]', '["誰见少年心，低摧向苦吟。","後須離影响，得必洞精深。","道院春苔徑，僧楼夏竹林。","天如愛才子，何慮未知音。"]', '诗', 'shi', '', NULL, '謝王秀才見示詩卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4d1bbf4-5ac5-4acf-8cc1-d4e9e4d07b1c', '送徐秀才之吳', '送徐秀才之吳', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["吳都霸道昌，才子去觀光。","望闕雲天近，朝宗水路長。","海門收片雨，建業泊殘陽。","欲問淮王信，仙都即帝鄉。"]', '["吳都霸道昌，才子去观光。","望闕云天近，朝宗水路长。","海门收片雨，建業泊殘陽。","欲问淮王信，仙都即帝乡。"]', '诗', 'shi', '', NULL, '送徐秀才之吳 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5ab1300-c686-4d94-8eac-beb9c6279856', '獨院偶作', '独院偶作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["風篁清一院，坐臥潤肌膚。","此境終拋去，鄰房肯信無。","身非王者役，門是祖師徒。","畢竟伊雲鳥，從來我友于。"]', '["风篁清一院，坐臥潤肌膚。","此境終拋去，鄰房肯信無。","身非王者役，门是祖師徒。","畢竟伊云鸟，從来我友于。"]', '诗', 'shi', '', NULL, '獨院偶作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0062af4-dce3-4e01-b5c4-885f9b605ca7', '酬元員外見寄', '酬元員外见寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["僻巷誰相訪，風籬翠蔓牽。","易中通性命，貧裏過流年。","且有吟情撓，都無俗事煎。","時聞得新意，多是此忘緣。"]', '["僻巷誰相訪，风籬翠蔓牽。","易中通性命，貧裏過流年。","且有吟情撓，都無俗事煎。","时闻得新意，多是此忘緣。"]', '诗', 'shi', '', NULL, '酬元員外見寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e92fabf-a06d-4881-a2e3-4836d3ca5c5e', '寄文秀大師', '寄文秀大師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["皎然靈一時，還有屈於詩。","世豈無英主，天何惜大師。","道終歸正始，心莫問多岐。","覽卷堪驚立，貞風喜未衰。"]', '["皎然靈一时，還有屈於诗。","世豈無英主，天何惜大師。","道終归正始，心莫问多岐。","覽卷堪驚立，貞风喜未衰。"]', '诗', 'shi', '', NULL, '寄文秀大師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83bbd59-59ca-4db7-8d71-77335922d563', '夏雨', '夏雨', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["霮䨴蔽穹蒼，冥濛自一方。","當時消酷毒，隨處有清涼。","著物聲雖暴，滋農潤即長。","乍紅縈急電，微白露殘陽。","應禱尤難得，經旬甚不妨。","吟聽喧竹樹，立見漲池塘。","衆類聲休出，羣峰色盡藏。","頹沱來洞壑，汗漫入瀟湘。","下叶黎甿望，高祛旱暵光。","幽齋飄臥簟，極浦灑歸檣。","蘚在堦從濕，花衰苑任傷。","閑思濟時力，謌詠發哀腸。"]', '["霮䨴蔽穹蒼，冥濛自一方。","當时消酷毒，隨处有清涼。","著物声雖暴，滋農潤即长。","乍紅縈急電，微白露殘陽。","應禱尤难得，經旬甚不妨。","吟听喧竹樹，立见漲池塘。","衆類声休出，羣峰色尽藏。","頹沱来洞壑，汗漫入瀟湘。","下叶黎甿望，高祛旱暵光。","幽斋飄臥簟，極浦灑归檣。","蘚在堦從濕，花衰苑任傷。","闲思濟时力，謌詠發哀腸。"]', '诗', 'shi', '', NULL, '夏雨 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f51e1a65-b210-48bc-a6d7-28dec1a0e01b', '謝興公上人寄山水簇子', '謝兴公上人寄山水簇子', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["半幅古潺顏，看來心意閑。","何須尋鳥道，即此出人間。","巘暮疑啼狖，松深認掩關。","知君遠相惠，免我憶歸山。"]', '["半幅古潺顏，看来心意闲。","何須尋鸟道，即此出人间。","巘暮疑啼狖，松深認掩关。","知君远相惠，免我憶归山。"]', '诗', 'shi', '', NULL, '謝興公上人寄山水簇子 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3b0d997-32c9-4f59-aa2b-6ecbe66b8142', '酬微上人', '酬微上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["古律皆深妙，新吟復造微。","搜難窮月窟，琢苦盡天機。","晚檜清蟬咽，寒江白鳥飛。","他年舊山去，爲子遠攜歸。"]', '["古律皆深妙，新吟复造微。","搜难窮月窟，琢苦尽天機。","晚檜清蟬咽，寒江白鸟飞。","他年旧山去，爲子远携归。"]', '诗', 'shi', '', NULL, '酬微上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f01b1f52-8147-464f-b6e5-855da05e3251', '同光歲送人及第東歸', '同光歲送人及第东归', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["西笑道何光，新朝舊桂堂。","春官如白傅，內試似文皇。","變化龍三十，升騰鳳一行。","還家幾多興，滿袖月中香。"]', '["西笑道何光，新朝旧桂堂。","春官如白傅，內試似文皇。","变化龙三十，升腾鳳一行。","還家幾多兴，满袖月中香。"]', '诗', 'shi', '', NULL, '同光歲送人及第東歸 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a56c542-7938-4a57-8852-891af32e3b9f', '寄江居耿處士', '寄江居耿处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["野癖雖相似，生涯即不同。","紅霞禪石上，明月釣船中。","醉倒蘆花白，吟緣蓼岸紅。","相思何以寄，吾道本空空。"]', '["野癖雖相似，生涯即不同。","紅霞禪石上，明月釣船中。","醉倒蘆花白，吟緣蓼岸紅。","相思何以寄，吾道本空空。"]', '诗', 'shi', '', NULL, '寄江居耿處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930240ab-8807-4b0b-a308-2ecc3115eab0', '病起二首 一', '病起二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一臥四十日，起來秋氣深。","已甘長逝魄，還見舊交心。","撐拄筇猶重，枝梧力未任。","終將此形陋，歸死故丘林。"]', '["一臥四十日，起来秋氣深。","已甘长逝魄，還见旧交心。","撐拄筇猶重，枝梧力未任。","終將此形陋，归死故丘林。"]', '诗', 'shi', '', NULL, '病起二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a53fc624-ef50-44ce-9793-50e6356a04f2', '病起二首 二', '病起二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["秋風已傷骨，更帶竹聲吹。","抱疾關門久，扶羸傍砌時。","無生即不可，有死必相隨。","除却歸真覺，何由擬免之。"]', '["秋风已傷骨，更带竹声吹。","抱疾关门久，扶羸傍砌时。","無生即不可，有死必相隨。","除却归真覺，何由擬免之。"]', '诗', 'shi', '', NULL, '病起二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e7b35d7-de37-4191-bef9-8abf211f564d', '送中觀進公歸巴陵', '送中观進公归巴陵', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一論破雙空，持行大國中。","不知從此去，何處挫邪宗。","晝雨懸帆黑，殘陽泊島紅。","應游到㴩岸，相憶遶茶叢。"]', '["一論破雙空，持行大国中。","不知從此去，何处挫邪宗。","晝雨懸帆黑，殘陽泊島紅。","應游到㴩岸，相憶遶茶叢。"]', '诗', 'shi', '', NULL, '送中觀進公歸巴陵 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41412043-048c-4772-bf29-a537e0950c2a', '寄鄭谷郎中', '寄鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["高名喧省闥，雅頌出吾唐。","疊巘供秋望，無雲到夕陽。","自封修藥院，別埽著僧牀。","幾夢中朝事，依依鵷鷺行。"]', '["高名喧省闥，雅頌出吾唐。","叠巘供秋望，無云到夕陽。","自封修藥院，別埽著僧牀。","幾梦中朝事，依依鵷鷺行。"]', '诗', 'shi', '', NULL, '寄鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97aad611-14bf-4160-a186-25f4075cf155', '歸鴈', '归鴈', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["塞門春已暖，連影起蘋風。","雲夢千行去，瀟湘一夜空。","江人休舉網，虜將又虛弓。","莫失南來伴，衡陽樹即紅。"]', '["塞门春已暖，連影起蘋风。","云梦千行去，瀟湘一夜空。","江人休舉網，虜將又虛弓。","莫失南来伴，衡陽樹即紅。"]', '诗', 'shi', '', NULL, '歸鴈 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14287725-784a-42bd-bdf9-e6b3f93e4724', '登大林寺觀白太傅題版', '登大林寺观白太傅題版', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["九疊蒼崖裏，禪家鑿翠開。","清時誰夢到，白傅獨尋來。","怪石和僧定，閑雲共鶴迴。","任茲休去者，心是不然灰。"]', '["九叠蒼崖裏，禪家鑿翠开。","清时誰梦到，白傅独尋来。","怪石和僧定，闲云共鹤迴。","任茲休去者，心是不然灰。"]', '诗', 'shi', '', NULL, '登大林寺觀白太傅題版 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38cb69f5-11dc-413a-9fb7-acc8020739b0', '贈曹松先輩', '贈曹松先輩', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["今歲赴春闈，達如夫子稀。","山中把卷去，榜下注官歸。","楚月吟前落，江禽酒外飛。","閑遊向諸寺，却看白麻衣。"]', '["今歲赴春闈，達如夫子稀。","山中把卷去，榜下注官归。","楚月吟前落，江禽酒外飞。","闲游向諸寺，却看白麻衣。"]', '诗', 'shi', '', NULL, '贈曹松先輩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('820e3835-770a-4b29-a3dd-da246e6831e5', '夏日江寺寄無上人', '夏日江寺寄無上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["講終齋磬罷，何處稱真心。","古寺高杉下，炎天獨院深。","燕和江鳥語，牆奪暮花陰。","大府多才子，閑過在竹林。"]', '["講終斋磬罷，何处稱真心。","古寺高杉下，炎天独院深。","燕和江鸟語，牆奪暮花陰。","大府多才子，闲過在竹林。"]', '诗', 'shi', '', NULL, '夏日江寺寄無上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('618fe135-f216-4ccd-a809-869ba1b5bc4c', '夏日梅雨中寄睦公', '夏日梅雨中寄睦公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["梅月來林寺，冥冥各閉門。","已應雙履跡，全沒亂雲根。","琢句心無味，看經眼亦昏。","何時見清霽，招我憑巖軒。"]', '["梅月来林寺，冥冥各閉门。","已應雙履跡，全沒亂云根。","琢句心無味，看經眼亦昏。","何时见清霽，招我憑巖軒。"]', '诗', 'shi', '', NULL, '夏日梅雨中寄睦公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78ce4ca7-6aba-4866-b990-87f0a21867c0', '傷鄭谷郎中', '傷鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鍾陵千首作，筆絕亦身終。","知落干戈裏，誰家煨燼中。","吟齋春長蕨，釣渚夜鳴鴻。","惆悵秋江月，曾招我看同。"]', '["鍾陵千首作，笔絕亦身終。","知落干戈裏，誰家煨燼中。","吟斋春长蕨，釣渚夜鳴鴻。","惆悵秋江月，曾招我看同。"]', '诗', 'shi', '', NULL, '傷鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c39b309-75de-424f-a99c-590abb846075', '臨行題友生壁', '臨行題友生壁', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["山衲宜何處，經行避暑深。","峰西多古寺，日午亂松陰。","鶴默堪分靜，蟬涼解助吟。","慇懃題壁去，秋早此相尋。"]', '["山衲宜何处，經行避暑深。","峰西多古寺，日午亂松陰。","鹤默堪分静，蟬涼解助吟。","慇懃題壁去，秋早此相尋。"]', '诗', 'shi', '', NULL, '臨行題友生壁 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b734d4d1-1989-4634-b163-f9b0e7ee6fbe', '別東林後迴寄修睦', '別东林後迴寄修睦', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["昨夜從香社，辭君出薜蘿。","晚來巾舃上，已覺俗塵多。","遠路縈芳草，遙空共白波。","南朝在天末，此去重經過。"]', '["昨夜從香社，辞君出薜蘿。","晚来巾舃上，已覺俗塵多。","远路縈芳草，遙空共白波。","南朝在天末，此去重經過。"]', '诗', 'shi', '', NULL, '別東林後迴寄修睦 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b63b43cb-5c7a-4985-8a3d-c9cafb3fc2f0', '古松', '古松', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雷電不敢伐，鱗皴勢萬端。","蠹依枯節死，蛇入朽根盤。","影浸僧禪濕，聲吹鶴夢寒。","尋常風雨夜，應有鬼神看。"]', '["雷電不敢伐，鱗皴勢万端。","蠹依枯節死，蛇入朽根盤。","影浸僧禪濕，声吹鹤梦寒。","尋常风雨夜，應有鬼神看。"]', '诗', 'shi', '', NULL, '古松 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f49e0176-dd11-48a8-8006-04eba01eaa8b', '夏日西霞寺書懷寄張逸人', '夏日西霞寺书懷寄張逸人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["人中林下現，名自有閑忙。","建業紅塵熱，栖霞白石涼。","倚身檉几穩，灑面瀑流香。","不似高齋裏，花連竹影長。"]', '["人中林下現，名自有闲忙。","建業紅塵熱，栖霞白石涼。","倚身檉几穩，灑面瀑流香。","不似高斋裏，花連竹影长。"]', '诗', 'shi', '', NULL, '夏日西霞寺書懷寄張逸人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9733437-6629-4215-8344-4fa9afba429c', '訪自牧上人不遇', '訪自牧上人不遇', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["然諾竟如何，諸侯見重多。","高房度江雨，經月長寒莎。","道本同騷雅，書曾到薜蘿。","相尋未相見，危閣望滄波。"]', '["然諾竟如何，諸侯见重多。","高房度江雨，經月长寒莎。","道本同騷雅，书曾到薜蘿。","相尋未相见，危閣望滄波。"]', '诗', 'shi', '', NULL, '訪自牧上人不遇 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9152e5d5-6c15-4533-a0aa-f53031270229', '題東林白蓮', '題东林白蓮', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["大士生兜率，空池滿白蓮。","秋風明月下，齋日影堂前。","色後羣芳拆，香殊百和燃。","誰知不染性，一片好心田。"]', '["大士生兜率，空池满白蓮。","秋风明月下，斋日影堂前。","色後羣芳拆，香殊百和燃。","誰知不染性，一片好心田。"]', '诗', 'shi', '', NULL, '題東林白蓮 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aaeae4d-d712-45fe-8611-f677db61a8b5', '寄懷江西徵岷二律師', '寄懷江西徵岷二律師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["亂後江邊寺，堪懷二律師。","幾番新弟子，一樣舊威儀。","院影連春竹，窗聲接雨池。","共緣山水癖，久別共題詩。"]', '["亂後江邊寺，堪懷二律師。","幾番新弟子，一樣旧威儀。","院影連春竹，窗声接雨池。","共緣山水癖，久別共題诗。"]', '诗', 'shi', '', NULL, '寄懷江西徵岷二律師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c650154c-a623-48dd-aaf5-724ee45f924e', '東林作寄金陵知己', '东林作寄金陵知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["十八賢真在，時來拂榻看。","已知前事遠，更結後人難。","泉滴勝清磬，松香掩白檀。","憑君聽朝貴，誰欲厭簪冠。"]', '["十八賢真在，时来拂榻看。","已知前事远，更結後人难。","泉滴勝清磬，松香掩白檀。","憑君听朝貴，誰欲厭簪冠。"]', '诗', 'shi', '', NULL, '東林作寄金陵知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e97e4d1-f28c-4d67-8251-ace8c1094b30', '山寺喜道者至', '山寺喜道者至', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["閏年春過後，山寺始花開。","還有無心者，閑尋此境來。","鳥幽聲忽斷，茶好味重迴。","知住南巖久，冥心坐綠苔。"]', '["閏年春過後，山寺始花开。","還有無心者，闲尋此境来。","鸟幽声忽斷，茶好味重迴。","知住南巖久，冥心坐綠苔。"]', '诗', 'shi', '', NULL, '山寺喜道者至 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a593bcb-b63f-4247-b759-983809edb915', '再遊匡山', '再游匡山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["紫霄兼二老，相對倚空寒。","久別成衰病，重來更上難。","徑危雲母滑，崖旱瀑流乾。","目斷嵐煙際，神仙有石壇。"]', '["紫霄兼二老，相对倚空寒。","久別成衰病，重来更上难。","徑危云母滑，崖旱瀑流乾。","目斷嵐煙際，神仙有石壇。"]', '诗', 'shi', '', NULL, '再遊匡山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('262cc8a0-eba5-4075-afde-44bdbb5d983a', '贈浙西李推官', '贈浙西李推官', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["他皆恃勳貴，君獨愛詩玄。","終日秋光裏，無人竹影邊。","東樓生倚月，北固積吟煙。","聞說鴛行裏，多才復少年。"]', '["他皆恃勳貴，君独愛诗玄。","終日秋光裏，無人竹影邊。","东楼生倚月，北固積吟煙。","闻说鴛行裏，多才复少年。"]', '诗', 'shi', '', NULL, '贈浙西李推官 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1479ec-7014-41b0-a192-6431d84ecdb4', '題終南山隱者室', '題終南山隐者室', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["終南山北面，直下是長安。","自埽青苔室，閑攲白石看。","風吹窗樹老，日曬竇雲乾。","時向圭峰宿，僧房瀑布寒。"]', '["終南山北面，直下是长安。","自埽青苔室，闲攲白石看。","风吹窗樹老，日曬竇云乾。","时向圭峰宿，僧房瀑布寒。"]', '诗', 'shi', '', NULL, '題終南山隱者室 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26e38b06-5654-486d-b664-12fa01489504', '禪庭蘆竹十二韻呈鄭谷郎中', '禪庭蘆竹十二韻呈鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["錯錯在禪庭，高宜與竹名。","健添秋雨響，乾助夜風清。","雀靜如枯折，僧閑見笋生。","對吟殊灑落，負氣甚孤貞。","密謝編欄固，齊由灌溉平。","松姿真可敵，柳態薄難幷。","映帶兼苔石，參差近畫楹。","雪霜消後色，蟲鳥默時聲。","遠憶滄洲岸，寒連暮角城。","幽根狂亂迸，勁葉動相撐。","避暑須臨坐，逃眠必遶行。","未逢仙手詠，俗眼見猶輕。"]', '["錯錯在禪庭，高宜與竹名。","健添秋雨响，乾助夜风清。","雀静如枯折，僧闲见笋生。","对吟殊灑落，負氣甚孤貞。","密謝編欄固，齊由灌溉平。","松姿真可敵，柳態薄难幷。","映带兼苔石，參差近畫楹。","雪霜消後色，蟲鸟默时声。","远憶滄洲岸，寒連暮角城。","幽根狂亂迸，勁葉动相撐。","避暑須臨坐，逃眠必遶行。","未逢仙手詠，俗眼见猶轻。"]', '诗', 'shi', '', NULL, '禪庭蘆竹十二韻呈鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f109dd-2b1c-46fb-8a9f-0f1ae5f8c2d3', '送孫鳳秀才赴舉', '送孫鳳秀才赴舉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["九重方側席，四海仰文明。","好把孤吟去，便隨公道行。","梁園浮雪氣，汴水漲春聲。","此日登仙衆，君應最後生。"]', '["九重方側席，四海仰文明。","好把孤吟去，便隨公道行。","梁园浮雪氣，汴水漲春声。","此日登仙衆，君應最後生。"]', '诗', 'shi', '', NULL, '送孫鳳秀才赴舉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73aca2c7-9fe1-4545-b8d6-c2cdfc25df49', '落花', '落花', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["朝開暮亦衰，雨打復風吹。","古屋無人處，殘陽滿地時。","靜依青蘚片，閑綴綠莎枝。","繁豔根枝在，明年向此期。"]', '["朝开暮亦衰，雨打复风吹。","古屋無人处，殘陽满地时。","静依青蘚片，闲綴綠莎枝。","繁豔根枝在，明年向此期。"]', '诗', 'shi', '', NULL, '落花 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d6fa5c9-4dc0-47ee-86a7-c443a5d14ed3', '秋苔', '秋苔', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["獨憐蒼翠文，長與寂寥存。","鶴靜窺秋片，僧閑踏冷痕。","月明疎竹徑，雨歇敗莎根。","別有深宮裏，兼花鎖斷魂。"]', '["独怜蒼翠文，长與寂寥存。","鹤静窺秋片，僧闲踏冷痕。","月明疎竹徑，雨歇敗莎根。","別有深宮裏，兼花鎖斷魂。"]', '诗', 'shi', '', NULL, '秋苔 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('250bdae6-d4d8-409f-87fd-30a0764af24a', '老將', '老將', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["破虜與平戎，曾居第一功。","明時不用武，白首向秋風。","馬病霜飛草，弓閑鴈過空。","兒孫已成立，膽氣亦英雄。"]', '["破虜與平戎，曾居第一功。","明时不用武，白首向秋风。","马病霜飞草，弓闲鴈過空。","兒孫已成立，膽氣亦英雄。"]', '诗', 'shi', '', NULL, '老將 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a646a58-94de-4878-9c27-6de558b5d4cf', '城中示友人', '城中示友人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["久與寒灰合，人中亦覺閑。","重城不鎖夢，每夜自歸山。","雨破冥鴻出，桐枯井月還。","唯君道心在，來往寂寥間。"]', '["久與寒灰合，人中亦覺闲。","重城不鎖梦，每夜自归山。","雨破冥鴻出，桐枯井月還。","唯君道心在，来往寂寥间。"]', '诗', 'shi', '', NULL, '城中示友人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ae1b9fa-fadc-477d-bc72-4e4176da1e41', '送友人遊湘中', '送友人游湘中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["懷才難自住，此去亦如僧。","何處西風夜，孤吟旅舍燈。","路沿湘樹疊，山入楚雲層。","若有東來札，歸鴻亦可憑。"]', '["懷才难自住，此去亦如僧。","何处西风夜，孤吟旅舍灯。","路沿湘樹叠，山入楚云層。","若有东来札，归鴻亦可憑。"]', '诗', 'shi', '', NULL, '送友人遊湘中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78ffe2f1-93c1-4917-b1ef-88240977548f', '經費徵君舊居', '經費徵君旧居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["高眠當聖代，雲鳥未爲孤。","天子徵不起，閑人親得無。","猿猱狂欲墜，水石怪難圖。","寂寞荒齋外，松杉相倚枯。"]', '["高眠當聖代，云鸟未爲孤。","天子徵不起，闲人親得無。","猿猱狂欲墜，水石怪难圖。","寂寞荒斋外，松杉相倚枯。"]', '诗', 'shi', '', NULL, '經費徵君舊居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ac169d-b7d9-43a6-bfb7-3c58d0f0802c', '嚴陵釣臺', '嚴陵釣台', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["夫子垂竿處，空江照古臺。","無人更如此，白浪自成堆。","鶴靜尋僧去，魚狂入海迴。","登臨秋值晚，樹石盡多苔。"]', '["夫子垂竿处，空江照古台。","無人更如此，白浪自成堆。","鹤静尋僧去，鱼狂入海迴。","登臨秋值晚，樹石尽多苔。"]', '诗', 'shi', '', NULL, '嚴陵釣臺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c11bbe3c-f0e1-4dab-9d9c-3e8dbe1753b0', '原上晚望', '原上晚望', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["倚杖聊攄望，寒原遠近分。","夜來何處火，燒出古人墳。","野勢盤空澤，江流合暮雲。","殘陽催百鳥，各自著栖羣。"]', '["倚杖聊攄望，寒原远近分。","夜来何处火，燒出古人墳。","野勢盤空澤，江流合暮云。","殘陽催百鸟，各自著栖羣。"]', '诗', 'shi', '', NULL, '原上晚望 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86913720-5fcf-40e3-ae04-2e96ba4b2df2', '送惠空上人歸', '送惠空上人归', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["塵中名利熱，鳥外水雲閑。","吾子多高趣，秋風獨自還。","空囊隨客櫂，幾宿泊湖山。","應有吟僧在，鄰居樹影間。"]', '["塵中名利熱，鸟外水云闲。","吾子多高趣，秋风独自還。","空囊隨客櫂，幾宿泊湖山。","應有吟僧在，鄰居樹影间。"]', '诗', 'shi', '', NULL, '送惠空上人歸 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec69b0e2-6bac-4fe2-9e72-3f58c1a2ed55', '酬章水知己', '酬章水知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["新吟忽有寄，千里到荆門。","落日雲初碧，殘年眼正昏。","已爲難敵手，誰更入深論。","後信多相寄，吾生重此言。"]', '["新吟忽有寄，千里到荆门。","落日云初碧，殘年眼正昏。","已爲难敵手，誰更入深論。","後信多相寄，吾生重此言。"]', '诗', 'shi', '', NULL, '酬章水知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a8a2e84-cea6-4b79-b32a-da7885fb3252', '閑居', '闲居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["漸覺春光媚，塵銷作土膏。","微寒放楊柳，纖草入風騷。","睡少全無病，身輕乍去袍。"]', '["漸覺春光媚，塵銷作土膏。","微寒放楊柳，纖草入风騷。","睡少全無病，身轻乍去袍。"]', '诗', 'shi', '', NULL, '閑居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8014ab61-8204-4083-81bd-768ba3e8b865', '次韻酬鄭谷郎中', '次韻酬鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["林下高眠起，相招得句時。","開門流水入，靜話鷺鷥知。","每許題成晚，多嫌雪阻期。","西齋坐來久，風竹撼疎籬。"]', '["林下高眠起，相招得句时。","开门流水入，静話鷺鷥知。","每許題成晚，多嫌雪阻期。","西斋坐来久，风竹撼疎籬。"]', '诗', 'shi', '', NULL, '次韻酬鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7d7d478-a9c7-4297-baa7-4e16a5d28822', '思遊峨嵋寄林下諸友', '思游峨嵋寄林下諸友', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["剛有峨嵋念，秋來錫欲飛。","會拋湘寺去，便逐蜀帆歸。","難世堪言善，閑人合見機。","殷勤別諸友，莫厭楚江薇。"]', '["剛有峨嵋念，秋来錫欲飞。","會拋湘寺去，便逐蜀帆归。","难世堪言善，闲人合见機。","殷勤別諸友，莫厭楚江薇。"]', '诗', 'shi', '', NULL, '思遊峨嵋寄林下諸友 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fad6db7-6fab-426a-b96a-ba9cc0b86de1', '送劉秀才南遊', '送劉秀才南游', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["南去謁諸侯，名山亦得遊。","便應尋瀑布，乘興上岣嶁。","高鳥隨雲起，寒星向地流。","相思應北望，天晚石橋頭。"]', '["南去謁諸侯，名山亦得游。","便應尋瀑布，乘兴上岣嶁。","高鸟隨云起，寒星向地流。","相思應北望，天晚石橋头。"]', '诗', 'shi', '', NULL, '送劉秀才南遊 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a78a910-aa30-487f-8bcf-61f667b8aee3', '示諸姪', '示諸姪', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫問年將朽，加餐已不多。","形容渾瘦削，行止強牽拖。","死也何憂惱，生而有詠歌。","侯門終謝去，却埽舊松蘿。"]', '["莫问年將朽，加餐已不多。","形容渾瘦削，行止強牽拖。","死也何憂惱，生而有詠歌。","侯门終謝去，却埽旧松蘿。"]', '诗', 'shi', '', NULL, '示諸姪 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a7f9958-dbb5-4147-b420-7031562c25ed', '荆渚病中因思匡廬遂成三百字寄梁先輩', '荆渚病中因思匡廬遂成三百字寄梁先輩', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["生老病死者，早聞天竺書。","相隨幾汩沒，不了堪欷歔。","自理自可適，他人誰與袪。","應當入寂滅，乃得長銷除。","前月已骨立，今朝還貌舒。","披衣試步履，倚策聊躊躇。","江月青眸冷，秋風白髮疎。","新題憶剡硾，舊約懷匡廬。","張野久絕跡，樂[天]曾卜居。","空龕掩薜荔，瀑布歕蟾蜍。","古檜鳴玄鶴，涼泉躍錦魚。","狂吟樹蔭映，縱踏花蔫菸。","脣舌既已閑，心脾亦散攄。","松窗有偃息，石徑無趦趄。","夢冷通仙闕，神融合太虛。","千峰杳靄際，萬壑明清初。","長往期非晚，半生閑有餘。","依劉未是詠，訪戴寧忘諸。","稽古堪求己，觀時好笑渠。","埋頭逐小利，沒脚拖長裾。","道種將閑養，情田把藥鉏。","幽香發蘭蕙，穢莽摧丘墟。","敢謂囊盈物，那言庾滿儲。","微煙動晨爨，細雨滋園蔬。","蘚亂珍禽羽，門稀長者車。","冥機坐兀兀，著履行徐徐。","每許親朱履，多憐奉隼旟。","簪嫌紅玳瑁，社念金芙蕖。","海內競鐵馬，篋中藏紙驢。","常言謝時去，此意將何如。"]', '["生老病死者，早闻天竺书。","相隨幾汩沒，不了堪欷歔。","自理自可適，他人誰與袪。","應當入寂滅，乃得长銷除。","前月已骨立，今朝還貌舒。","披衣試步履，倚策聊躊躇。","江月青眸冷，秋风白髮疎。","新題憶剡硾，旧約懷匡廬。","張野久絕跡，乐[天]曾卜居。","空龕掩薜荔，瀑布歕蟾蜍。","古檜鳴玄鹤，涼泉躍錦鱼。","狂吟樹蔭映，縱踏花蔫菸。","脣舌既已闲，心脾亦散攄。","松窗有偃息，石徑無趦趄。","梦冷通仙闕，神融合太虛。","千峰杳靄際，万壑明清初。","长往期非晚，半生闲有餘。","依劉未是詠，訪戴寧忘諸。","稽古堪求己，观时好笑渠。","埋头逐小利，沒脚拖长裾。","道種將闲養，情田把藥鉏。","幽香發蘭蕙，穢莽摧丘墟。","敢謂囊盈物，那言庾满儲。","微煙动晨爨，細雨滋园蔬。","蘚亂珍禽羽，门稀长者车。","冥機坐兀兀，著履行徐徐。","每許親朱履，多怜奉隼旟。","簪嫌紅玳瑁，社念金芙蕖。","海內競鐵马，篋中藏紙驢。","常言謝时去，此意將何如。"]', '诗', 'shi', '', NULL, '荆渚病中因思匡廬遂成三百字寄梁先輩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a864a0a5-f045-4bf5-abe2-ca6f6272338d', '竟陵遇晝公', '竟陵遇晝公', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["高跡何來此，遊方漸老身。","欲投蓮岳夏，初過竟陵春。","錫影離雲遠，衣痕拂蘚新。","無言即相別，此處不迷津。"]', '["高跡何来此，游方漸老身。","欲投蓮岳夏，初過竟陵春。","錫影離云远，衣痕拂蘚新。","無言即相別，此处不迷津。"]', '诗', 'shi', '', NULL, '竟陵遇晝公 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70b7197d-3d90-4302-965c-34442ce5f857', '聞貫休下世', '闻貫休下世', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["吾師詩匠者，真箇碧雲流。","爭得梁太子，重爲文選樓。","錦江新塚樹，婺女舊山秋。","欲去焚香禮，啼猨峽阻修。"]', '["吾師诗匠者，真箇碧云流。","爭得梁太子，重爲文選楼。","錦江新塚樹，婺女旧山秋。","欲去焚香禮，啼猨峽阻修。"]', '诗', 'shi', '', NULL, '聞貫休下世 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62492b1a-dfba-4cf0-a21a-80bec4558b82', '金山寺', '金山寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["山帶金名遠，樓臺壓翠層。","魚龍光照像，風浪影搖燈。","檻外揚州樹，船通建業僧。","塵埃何所到，青石坐如冰。"]', '["山带金名远，楼台壓翠層。","鱼龙光照像，风浪影搖灯。","檻外揚州樹，船通建業僧。","塵埃何所到，青石坐如冰。"]', '诗', 'shi', '', NULL, '金山寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cc0a488-6891-4e6a-a5b2-561b4e0a6b1d', '早秋雨後晚望', '早秋雨後晚望', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["暑氣時將薄，蟲聲夜轉稠。","江湖經一雨，日月換新秋。","有景堪援筆，何人未上樓。","欲承涼冷興，西向碧嵩遊。"]', '["暑氣时將薄，蟲声夜轉稠。","江湖經一雨，日月換新秋。","有景堪援笔，何人未上楼。","欲承涼冷兴，西向碧嵩游。"]', '诗', 'shi', '', NULL, '早秋雨後晚望 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9129bbf3-e9a8-44d5-a65d-5a9413e314b7', '過西塞山', '過西塞山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["空江平野流，風島葦颼颼。","殘日銜西塞，孤帆向北洲。","邊鴻渡漢口，楚樹出吳頭。","終入高雲裏，身依片石休。"]', '["空江平野流，风島葦颼颼。","殘日銜西塞，孤帆向北洲。","邊鴻渡漢口，楚樹出吳头。","終入高云裏，身依片石休。"]', '诗', 'shi', '', NULL, '過西塞山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('703f5f44-4147-45e8-880a-6adadcaee339', '溪齋二首 一', '溪斋二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["豈敢言招隱，歸休喜自安。","一溪雲臥穩，四海路行難。","瑞獸藏頭角，幽禽惜羽翰。","子猷何處在，老盡碧琅玕。"]', '["豈敢言招隐，归休喜自安。","一溪云臥穩，四海路行难。","瑞獸藏头角，幽禽惜羽翰。","子猷何处在，老尽碧琅玕。"]', '诗', 'shi', '', NULL, '溪齋二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fccc8dc4-a7a9-4fc6-8766-19575d39b2df', '溪齋二首 二', '溪斋二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["杉竹映溪關，修修共歲寒。","幽人眠日晏，花雨落春殘。","道妙言何強，詩玄論甚難。","閑居有親賦，搔首憶潘安。"]', '["杉竹映溪关，修修共歲寒。","幽人眠日晏，花雨落春殘。","道妙言何強，诗玄論甚难。","闲居有親賦，搔首憶潘安。"]', '诗', 'shi', '', NULL, '溪齋二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5d0f225-4bcd-4dec-87d7-06126a3edaf6', '新秋', '新秋', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["始驚三伏盡，又遇立秋時。","露彩朝還冷，雲峰晚更奇。","壠香禾半熟，原迥草微衰。","幸好清光裏，安仁謾起悲。"]', '["始驚三伏尽，又遇立秋时。","露彩朝還冷，云峰晚更奇。","壠香禾半熟，原迥草微衰。","幸好清光裏，安仁謾起悲。"]', '诗', 'shi', '', NULL, '新秋 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('607e7fb0-5f9a-41db-b60c-57c3e87dbfda', '寄上荆渚因夢廬岳乃圖壁賦詩', '寄上荆渚因梦廬岳乃圖壁賦诗', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["夢繞嵯峨裏，神疎骨亦寒。","覺來誰共說，壁上自圖看。","古翠松藏寺，春紅杏濕壇。","歸心幾時遂，日向漸衰殘。"]', '["梦繞嵯峨裏，神疎骨亦寒。","覺来誰共说，壁上自圖看。","古翠松藏寺，春紅杏濕壇。","归心幾时遂，日向漸衰殘。"]', '诗', 'shi', '', NULL, '寄上荆渚因夢廬岳乃圖壁賦詩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a402db-0387-4111-b58f-e8a10436a2ef', '己卯歲值凍阻歸有作', '己卯歲值凍阻归有作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["河冰連地凍，朔氣壓春寒。","開戶思歸遠，出門移步難。","湖雲黏鴈重，廟樹刮風乾。","坐看孤燈焰，微微向曉殘。"]', '["河冰連地凍，朔氣壓春寒。","开戶思归远，出门移步难。","湖云黏鴈重，廟樹刮风乾。","坐看孤灯焰，微微向晓殘。"]', '诗', 'shi', '', NULL, '己卯歲值凍阻歸有作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee09a2ce-0bf7-49a5-80ad-ecbd8dd79279', '送盧說亂後投知己', '送盧说亂後投知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["兵寇殘江墅，生涯盡蕩除。","事堪煎桂玉，時莫倚詩書。","暮狖啼空半，春山列雨餘。","舟中有新作，迴寄示慵疎。"]', '["兵寇殘江墅，生涯尽蕩除。","事堪煎桂玉，时莫倚诗书。","暮狖啼空半，春山列雨餘。","舟中有新作，迴寄示慵疎。"]', '诗', 'shi', '', NULL, '送盧說亂後投知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d7b2a22-ef4d-4435-b366-b39b71777d35', '讀峴山碑', '读峴山碑', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["三載羊公政，千年峴首碑。","何人更墮淚，此道亦殊時。","兵火燒文缺，江雲觸蘚滋。","那堪望黎庶，匝地是瘡痍。"]', '["三載羊公政，千年峴首碑。","何人更墮泪，此道亦殊时。","兵火燒文缺，江云觸蘚滋。","那堪望黎庶，匝地是瘡痍。"]', '诗', 'shi', '', NULL, '讀峴山碑 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da77c41f-d9b3-4eb9-b3b9-94374d78d223', '過鹿門作', '過鹿门作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["鹿門埋孟子，峴首載羊公。","萬古千秋裏，青山明月中。","政從襄沔絕，詩過洞庭空。","塵路誰迴眼，松聲兩處風。"]', '["鹿门埋孟子，峴首載羊公。","万古千秋裏，青山明月中。","政從襄沔絕，诗過洞庭空。","塵路誰迴眼，松声兩处风。"]', '诗', 'shi', '', NULL, '過鹿門作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f2f43c-8878-4a91-84a6-7ba018f0ca42', '題玉泉寺大師影堂', '題玉泉寺大師影堂', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["大化終華頂，靈蹤示玉泉。","由來負高尚，合向好山川。","洞壑藏諸怪，杉松列瘦煙。","千秋空樹影，猶似覆長禪。"]', '["大化終华頂，靈蹤示玉泉。","由来負高尚，合向好山川。","洞壑藏諸怪，杉松列瘦煙。","千秋空樹影，猶似覆长禪。"]', '诗', 'shi', '', NULL, '題玉泉寺大師影堂 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26f64c5-8dd3-422f-bdd2-70c90ca09de2', '秋日錢塘作', '秋日錢塘作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["秋光明水國，遊子倚長亭。","海浸全吳白，山澄百越青。","英雄貴黎庶，封土絕精靈。","句踐魂如在，應懸戰血腥。"]', '["秋光明水国，游子倚长亭。","海浸全吳白，山澄百越青。","英雄貴黎庶，封土絕精靈。","句踐魂如在，應懸戰血腥。"]', '诗', 'shi', '', NULL, '秋日錢塘作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb5da6b0-aa8b-40e5-9b60-0ffec5d1f4d9', '送人赴舉', '送人赴舉', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["分有爭忘得，時來須出山。","白雲終許在，清世莫空還。","驛樹秋聲健，行衣雨點斑。","明年從月裏，滿握度春關。"]', '["分有爭忘得，时来須出山。","白云終許在，清世莫空還。","驛樹秋声健，行衣雨点斑。","明年從月裏，满握度春关。"]', '诗', 'shi', '', NULL, '送人赴舉 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c895152-ae26-46ae-b986-3c4eaaa046b6', '友人寒夜所寄', '友人寒夜所寄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["通宵亦孤坐，但念舊峰雲。","白日還如此，清閑本共君。","二毛凋一半，百歲去三分。","早晚尋流水，同歸麋鹿羣。"]', '["通宵亦孤坐，但念旧峰云。","白日還如此，清闲本共君。","二毛凋一半，百歲去三分。","早晚尋流水，同归麋鹿羣。"]', '诗', 'shi', '', NULL, '友人寒夜所寄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5166c6dc-aaf9-4853-bb3a-8ecf0206ba71', '酬洞庭陳秀才', '酬洞庭陳秀才', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["何必要識面，見詩驚苦心。","此門從自古，難學至如今。","青草湖雲闊，黃陵廟木深。","精搜當好景，得即動知音。"]', '["何必要識面，见诗驚苦心。","此门從自古，难学至如今。","青草湖云闊，黄陵廟木深。","精搜當好景，得即动知音。"]', '诗', 'shi', '', NULL, '酬洞庭陳秀才 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2114783f-a3be-4a5e-a083-ed83565b40bf', '題鶴鳴泉八韻', '題鹤鳴泉八韻', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["嘹淚遺蹤去，澄明物掩難。","噴開山面碧，飛落寺門寒。","汲引隨缾滿，分流逐處安。","幽蟲乘葉過，渴狖擁條看。","上有危峰疊，旁宜怪石盤。","冷吞雙樹影，甘潤百毛端。","異早聞鐫玉，靈終別建壇。","瀟湘在何處，終日自波瀾。"]', '["嘹泪遺蹤去，澄明物掩难。","噴开山面碧，飞落寺门寒。","汲引隨缾满，分流逐处安。","幽蟲乘葉過，渴狖擁條看。","上有危峰叠，旁宜怪石盤。","冷吞雙樹影，甘潤百毛端。","異早闻鐫玉，靈終別建壇。","瀟湘在何处，終日自波瀾。"]', '诗', 'shi', '', NULL, '題鶴鳴泉八韻 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47a6342f-35f9-4d5a-864e-23b53f858cef', '登金山寺', '登金山寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["四面白波聲，中流翠嶠橫。","望來堪目斷，上徹始心平。","鳥向天涯去，雲連水國生。","重來與誰約，題罷自吟行。"]', '["四面白波声，中流翠嶠橫。","望来堪目斷，上徹始心平。","鸟向天涯去，云連水国生。","重来與誰約，題罷自吟行。"]', '诗', 'shi', '', NULL, '登金山寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ee5fa87-75d1-4cbb-8298-fc27a4e9403e', '寄吳都沈員外彬', '寄吳都沈員外彬', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["歸休興若何，朱紱盡還他。","自有園林闊，誰爭山水多。","村煙晴莽蒼，僧磬晚嵯峨。","野醉題招隱，相思可寄麽。"]', '["归休兴若何，朱紱尽還他。","自有园林闊，誰爭山水多。","村煙晴莽蒼，僧磬晚嵯峨。","野醉題招隐，相思可寄麽。"]', '诗', 'shi', '', NULL, '寄吳都沈員外彬 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f073b5a0-ea41-40d3-a224-ac0f3f6a71a5', '寄明月山僧', '寄明月山僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["山稱明月好，月出徧山明。","要上諸峰去，無妨半夜行。","白猨真雪色，幽鳥古琴聲。","吾子居來久，應忘我在城。"]', '["山稱明月好，月出徧山明。","要上諸峰去，無妨半夜行。","白猨真雪色，幽鸟古琴声。","吾子居来久，應忘我在城。"]', '诗', 'shi', '', NULL, '寄明月山僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69688924-edb0-4941-9f20-53a7ae6ee1f8', '寄哭西川壇長廣濟大師', '寄哭西川壇长廣濟大師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["千萬僧中寶，三朝帝寵身。","還源未化火，舉國葬全真。","文集編金在，碑銘刻玉新。","有誰於異代，彈指禮遺塵。"]', '["千万僧中寶，三朝帝寵身。","還源未化火，舉国葬全真。","文集編金在，碑銘刻玉新。","有誰於異代，彈指禮遺塵。"]', '诗', 'shi', '', NULL, '寄哭西川壇長廣濟大師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('535133d5-b507-4169-8e91-d827439a68bd', '酬西川楚巒上人卷', '酬西川楚巒上人卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["玉壘峨嵋秀，岷江錦水清。","古人搜不盡，吾子得何精。","可信由前習，堪聞正後生。","東西五千里，多謝寄無成。"]', '["玉壘峨嵋秀，岷江錦水清。","古人搜不尽，吾子得何精。","可信由前習，堪闻正後生。","东西五千里，多謝寄無成。"]', '诗', 'shi', '', NULL, '酬西川楚巒上人卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('418b5309-1378-4234-a1cf-fc8b182ee11a', '覽延栖上人卷', '覽延栖上人卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["今體雕鏤妙，古風研考精。","何人忘律韻，爲子辨詩聲。","賈島苦兼此，孟郊清獨行。","荆門見編集，媿我老無成。"]', '["今體雕鏤妙，古风研考精。","何人忘律韻，爲子辨诗声。","賈島苦兼此，孟郊清独行。","荆门见編集，媿我老無成。"]', '诗', 'shi', '', NULL, '覽延栖上人卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6735a02-79de-412e-81c4-464a4f5c099f', '寄洛下王彝訓先輩二首 一', '寄洛下王彝訓先輩二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["賈島存正始，王維留格言。","千篇千古在，一詠一驚魂。","離別無他寄，相思共此門。","陽春堪永恨，郢路轉塵昏。"]', '["賈島存正始，王維留格言。","千篇千古在，一詠一驚魂。","離別無他寄，相思共此门。","陽春堪永恨，郢路轉塵昏。"]', '诗', 'shi', '', NULL, '寄洛下王彝訓先輩二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea764679-765d-4a26-9198-05f970928ee2', '寄洛下王彝訓先輩二首 二', '寄洛下王彝訓先輩二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["北極新英主，高科舊少年。","風流傳貴達，談笑取榮遷。","洛水秋空底，嵩峰曉翠巔。","尋常誰竝馬，橋上戲成篇。"]', '["北極新英主，高科旧少年。","风流傳貴達，談笑取榮遷。","洛水秋空底，嵩峰晓翠巔。","尋常誰竝马，橋上戲成篇。"]', '诗', 'shi', '', NULL, '寄洛下王彝訓先輩二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b831a058-979b-4187-bfba-080262df35c7', '酬岳陽李主簿卷', '酬岳陽李主簿卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["把卷思高興，瀟湘闊浸門。","無雲生翠浪，有月動清魂。","倚檻應窮底，凝情合到源。","爲君吟所寄，難甚至忘筌。"]', '["把卷思高兴，瀟湘闊浸门。","無云生翠浪，有月动清魂。","倚檻應窮底，凝情合到源。","爲君吟所寄，难甚至忘筌。"]', '诗', 'shi', '', NULL, '酬岳陽李主簿卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('239cb3cb-7ca2-4264-b21c-b8177b957751', '寄懷江西僧達禪翁', '寄懷江西僧達禪翁', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["長憶舊山日，與君同聚沙。","未能精貝葉，便學詠楊花。","苦甚傷心骨，清還切齒牙。","何妨繼餘習，前世是詩家。"]', '["长憶旧山日，與君同聚沙。","未能精貝葉，便学詠楊花。","苦甚傷心骨，清還切齒牙。","何妨繼餘習，前世是诗家。"]', '诗', 'shi', '', NULL, '寄懷江西僧達禪翁 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20cab7f6-b799-4144-a75b-71fd5cc55f80', '送吳守明先輩遊蜀', '送吳守明先輩游蜀', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["憑君遊蜀去，細爲話幽奇。","喪亂嘉陵驛，塵埃賈島詩。","未應過錦府，且合上峨嵋。","既逐高科後，東西任所之。"]', '["憑君游蜀去，細爲話幽奇。","喪亂嘉陵驛，塵埃賈島诗。","未應過錦府，且合上峨嵋。","既逐高科後，东西任所之。"]', '诗', 'shi', '', NULL, '送吳守明先輩遊蜀 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75708e2b-13dd-4377-bc8d-95b3b86ea1d8', '寄普明大師可準', '寄普明大師可準', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["蓮嶽三徵者，論詩舊與君。","相留曾幾歲，酬唱有新文。","翠竇容閑憇，嵐峰許共分。","當年若同訪，合得伴吟雲。"]', '["蓮嶽三徵者，論诗旧與君。","相留曾幾歲，酬唱有新文。","翠竇容闲憇，嵐峰許共分。","當年若同訪，合得伴吟云。"]', '诗', 'shi', '', NULL, '寄普明大師可準 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99d4d0ce-823d-4c94-8d4d-bfb6b1200752', '還黃平素秀才卷', '還黄平素秀才卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["求己甚忘筌，得之經渾然。","僻能離詭差，清不尚妖妍。","冷澹聞姚監，精奇見浪仙。","如君好風格，自可繼前賢。"]', '["求己甚忘筌，得之經渾然。","僻能離詭差，清不尚妖妍。","冷澹闻姚監，精奇见浪仙。","如君好风格，自可繼前賢。"]', '诗', 'shi', '', NULL, '還黃平素秀才卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3c65f71-2984-4336-bd52-a97b4f120a69', '與張先輩話別', '與張先輩話別', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["爲□□□者，各自話離心。","及第還全蜀，遊方歸二林。","巴江□□漲，楚野入吳深。","他日傳消息，東西不易尋。"]', '["爲□□□者，各自話離心。","及第還全蜀，游方归二林。","巴江□□漲，楚野入吳深。","他日傳消息，东西不易尋。"]', '诗', 'shi', '', NULL, '與張先輩話別 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59418ffd-76a9-4e5f-afda-16c75b6e98ae', '寄朱拾遺', '寄朱拾遺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一聞歸闕下，幾番熟金桃。","滄海期仍晚，清資路漸高。","研冰濡諫筆，賦雪擁朝袍。","豈念空林下，冥心坐石勞。"]', '["一闻归闕下，幾番熟金桃。","滄海期仍晚，清資路漸高。","研冰濡諫笔，賦雪擁朝袍。","豈念空林下，冥心坐石勞。"]', '诗', 'shi', '', NULL, '寄朱拾遺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c19824c-d4dd-4ab7-b431-29743afdf86d', '荆門送興禪師', '荆门送兴禪師', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["灑落南宗子，遊方跡似雲。","青山尋處處，赤葉路紛紛。","虎共松巖宿，猨和石溜聞。","何峰一迴首，憶我在人羣。"]', '["灑落南宗子，游方跡似云。","青山尋处处，赤葉路紛紛。","虎共松巖宿，猨和石溜闻。","何峰一迴首，憶我在人羣。"]', '诗', 'shi', '', NULL, '荆門送興禪師 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc27d6e-1ed4-4180-9c7e-be7b03ea9627', '過西山施肩吾舊居', '過西山施肩吾旧居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["大志終難起，西峰臥翠堆。","牀前倒秋壑，枕上過春雷。","鶴見丹成去，僧聞栗熟來。","荒齋松竹老，鸞鶴自裴回。"]', '["大志終难起，西峰臥翠堆。","牀前倒秋壑，枕上過春雷。","鹤见丹成去，僧闻栗熟来。","荒斋松竹老，鸾鹤自裴回。"]', '诗', 'shi', '', NULL, '過西山施肩吾舊居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5b01055-2065-45e1-81db-a01df4856499', '喜夏雨', '喜夏雨', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["四郊雲影合，千里雨聲來。","盡洗紅埃去，併將清氣迴。","潺湲浮楚甸，蕭散露荆臺。","欲賦隨車瑞，濡毫渴謏才。"]', '["四郊云影合，千里雨声来。","尽洗紅埃去，併將清氣迴。","潺湲浮楚甸，蕭散露荆台。","欲賦隨车瑞，濡毫渴謏才。"]', '诗', 'shi', '', NULL, '喜夏雨 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73c9f292-3c6b-4957-83d2-ee44996d494b', '酬元員外見寄八韻', '酬元員外见寄八韻', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊隱夢牽仍，歸心只似蒸。","遠青憐島峭，輕白愛雲騰。","豔冶叢翻蝶，腥膻地聚蠅。","雨聲連灑竹，詩興繼填膺。","訪戴情彌切，依劉力不勝。","衆人忘苦苦，獨自媿兢兢。","處世無他望，流年有病僧。","時慙大雅客，遺韻許相承。"]', '["旧隐梦牽仍，归心只似蒸。","远青怜島峭，轻白愛云腾。","豔冶叢翻蝶，腥膻地聚蠅。","雨声連灑竹，诗兴繼填膺。","訪戴情彌切，依劉力不勝。","衆人忘苦苦，独自媿兢兢。","处世無他望，流年有病僧。","时慙大雅客，遺韻許相承。"]', '诗', 'shi', '', NULL, '酬元員外見寄八韻 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('092e8280-28f0-4491-b5de-94b3aded6d07', '浣口泊舟曉望天柱峰', '浣口泊舟晓望天柱峰', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["根盤潛岳半，頂逼日輪邊。","冷碧無雲點，危稜有瀑懸。","秀輕毛女下，名與鼎湖偏。","誰見扶持力，峨峨出後天。"]', '["根盤潛岳半，頂逼日輪邊。","冷碧無云点，危稜有瀑懸。","秀轻毛女下，名與鼎湖偏。","誰见扶持力，峨峨出後天。"]', '诗', 'shi', '', NULL, '浣口泊舟曉望天柱峰 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aa8b28e-83ef-42cd-94ef-24466d056a07', '寄楚萍上人', '寄楚萍上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["北面香爐秀，南邊瀑布寒。","自來還獨去，夏滿又秋殘。","日影松杉亂，雲容洞壑寬。","何峰是鄰側，片石許相安。"]', '["北面香爐秀，南邊瀑布寒。","自来還独去，夏满又秋殘。","日影松杉亂，云容洞壑寬。","何峰是鄰側，片石許相安。"]', '诗', 'shi', '', NULL, '寄楚萍上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1832cc7e-500e-436f-acd4-2a2e2c8a6a1e', '竹裏作六韻', '竹裏作六韻', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["我來深處坐，剩覺有吟思。","忽似瀟湘岸，欲生風雨時。","冷煙濛古屋，乾籜墮秋墀。","徑熟因頻入，身閑得徧欹。","踏多鞭節損，題亂粉痕隳。","猶見前山疊，微茫隔短籬。"]', '["我来深处坐，剩覺有吟思。","忽似瀟湘岸，欲生风雨时。","冷煙濛古屋，乾籜墮秋墀。","徑熟因頻入，身闲得徧欹。","踏多鞭節損，題亂粉痕隳。","猶见前山叠，微茫隔短籬。"]', '诗', 'shi', '', NULL, '竹裏作六韻 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fb192db-b56d-4098-ab81-601aae5b9c0a', '寄江西幕中孫魴員外', '寄江西幕中孫魴員外', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["簪履爲官興，芙蓉結社緣。","應思陶令醉，時訪遠公禪。","茶影中殘月，松聲裏落泉。","此門曾共說，知未遂終焉。"]', '["簪履爲官兴，芙蓉結社緣。","應思陶令醉，时訪远公禪。","茶影中殘月，松声裏落泉。","此门曾共说，知未遂終焉。"]', '诗', 'shi', '', NULL, '寄江西幕中孫魴員外 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08836432-4823-47b9-805a-ac82d7d511ae', '盆池', '盆池', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["盆沼陷花邊，孤明似玉泉。","涵虛心不淺，待月底長圓。","平穩承天澤，依微泛曙煙。","何須照菱鏡，即此鑒媸妍。"]', '["盆沼陷花邊，孤明似玉泉。","涵虛心不淺，待月底长圓。","平穩承天澤，依微泛曙煙。","何須照菱镜，即此鑒媸妍。"]', '诗', 'shi', '', NULL, '盆池 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3bc2075-7661-4f31-babb-957eb3c0e6f7', '喜乾晝上人遠相訪', '喜乾晝上人远相訪', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["彼此垂七十，相逢意若何。","聖明殊未至，離亂更應多。","澹泊門難到，從容日易過。","餘生消息外，只合聽詩魔。"]', '["彼此垂七十，相逢意若何。","聖明殊未至，離亂更應多。","澹泊门难到，從容日易過。","餘生消息外，只合听诗魔。"]', '诗', 'shi', '', NULL, '喜乾晝上人遠相訪 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4c04d80-df58-43aa-971d-4afcab2e8008', '過陳陶處士舊居', '過陳陶处士旧居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["一室貯琴尊，詩皆大雅言。","夜過秋竹寺，醉打老僧門。","遠燒來籬下，寒蔬簇石根。","閑庭除鶴跡，半是杖頭痕。"]', '["一室貯琴尊，诗皆大雅言。","夜過秋竹寺，醉打老僧门。","远燒来籬下，寒蔬簇石根。","闲庭除鹤跡，半是杖头痕。"]', '诗', 'shi', '', NULL, '過陳陶處士舊居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7af4fe5-c45b-4b09-a5bb-474baaa93502', '寄敬亭清越', '寄敬亭清越', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["敬亭山色古，廟與寺松連。","住此修行過，春風四十年。","鼎嘗天柱茗，詩硾剡溪牋。","冥目應思著，終南北闕前。"]', '["敬亭山色古，廟與寺松連。","住此修行過，春风四十年。","鼎嘗天柱茗，诗硾剡溪牋。","冥目應思著，終南北闕前。"]', '诗', 'shi', '', NULL, '寄敬亭清越 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c661efb-f02f-4f2b-ab86-f31ee3a7fbab', '湘江漁父', '湘江漁父', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["湘潭春水滿，岸遠草青青。","有客釣煙月，無人論醉醒。","門前蛟蜃氣，蓑上蕙蘭馨。","曾受蒙莊子，逍遙一卷經。"]', '["湘潭春水满，岸远草青青。","有客釣煙月，無人論醉醒。","门前蛟蜃氣，蓑上蕙蘭馨。","曾受蒙莊子，逍遙一卷經。"]', '诗', 'shi', '', NULL, '湘江漁父 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42962339-76b9-4a3f-9fde-8d77c90881d9', '書古寺僧房', '书古寺僧房', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["綠樹深深處，長明焰焰燈。","春時遊寺客，花落閉門僧。","萬法心中寂，孤泉石上澄。","勞生莫相問，喧默不相應。"]', '["綠樹深深处，长明焰焰灯。","春时游寺客，花落閉门僧。","万法心中寂，孤泉石上澄。","勞生莫相问，喧默不相應。"]', '诗', 'shi', '', NULL, '書古寺僧房 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca3f054-1b49-4fa8-90e3-9d6ed2c079cf', '湖西逸人', '湖西逸人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["老隱洞庭西，漁樵共一溪。","琴前孤鶴影，石上遠僧題。","橘柚園林熟，蒹葭徑路迷。","君能許鄰並，分藥斸春畦。"]', '["老隐洞庭西，漁樵共一溪。","琴前孤鹤影，石上远僧題。","橘柚园林熟，蒹葭徑路迷。","君能許鄰並，分藥斸春畦。"]', '诗', 'shi', '', NULL, '湖西逸人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c5b1d0-e828-4ef4-9bd5-bb23c18e6d39', '瀟湘二十韻', '瀟湘二十韻', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["二水遠難論，從離向坎奔。","冷穿千嶂脈，清過幾州門。","闊去都凝白，傍來盡帶渾。","經游聞舜禹，表裏見乾坤。","浦靜魚閑釣，灣涼鴈自屯。","月來分夜底，雲度見秋痕。","暮氣藏鄰寺，寒濤聒近村。","離騷傳永恨，鼓瑟奏遺魂。","霧擁魚龍窟，槎欹島嶼根。","秋風帆上下，落日樹沈昏。","柳少沙洲缺，苔多古岸存。","禽巢依橘柚，獺逕入蘭蓀。","色自江南絕，名聞海內尊。","吳頭雄莫遏，漢口壯堪吞。","寥泬晴方映，馮夷信忽翻。","渡遙峰翠疊，汀小荻花繁。","勢接湖煙漲，聲和瘴雨歕。","急搖吟客舫，狂濺野人樽。","疎鑿誰窮本，澄鮮自有源。","對茲傷九曲，含濁出崑崙。"]', '["二水远难論，從離向坎奔。","冷穿千嶂脈，清過幾州门。","闊去都凝白，傍来尽带渾。","經游闻舜禹，表裏见乾坤。","浦静鱼闲釣，灣涼鴈自屯。","月来分夜底，云度见秋痕。","暮氣藏鄰寺，寒濤聒近村。","離騷傳永恨，鼓瑟奏遺魂。","霧擁鱼龙窟，槎欹島嶼根。","秋风帆上下，落日樹沈昏。","柳少沙洲缺，苔多古岸存。","禽巢依橘柚，獺逕入蘭蓀。","色自江南絕，名闻海內尊。","吳头雄莫遏，漢口壯堪吞。","寥泬晴方映，馮夷信忽翻。","渡遙峰翠叠，汀小荻花繁。","勢接湖煙漲，声和瘴雨歕。","急搖吟客舫，狂濺野人樽。","疎鑿誰窮本，澄鲜自有源。","对茲傷九曲，含濁出崑崙。"]', '诗', 'shi', '', NULL, '瀟湘二十韻 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00c6fdc4-baa7-4a49-8922-f1c1974b3265', '江行早發', '江行早發', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舟子相呼起，長江未五更。","幾看星月在，猶帶夢魂行。","鳥亂村林迥，人喧水柵橫。","蒼茫平野外，漸認遠峰名。"]', '["舟子相呼起，长江未五更。","幾看星月在，猶带梦魂行。","鸟亂村林迥，人喧水柵橫。","蒼茫平野外，漸認远峰名。"]', '诗', 'shi', '', NULL, '江行早發 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e978d0f5-2e55-47f1-9478-e895a40aca75', '宜陽道中作', '宜陽道中作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["宜陽南面路，下嶽又經過。","楓葉紅遮店，芒花白滿坡。","猨無山漸薄，鴈衆水還多。","日落猶前去，諸村牧豎歌。"]', '["宜陽南面路，下嶽又經過。","楓葉紅遮店，芒花白满坡。","猨無山漸薄，鴈衆水還多。","日落猶前去，諸村牧豎歌。"]', '诗', 'shi', '', NULL, '宜陽道中作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6da6efcd-4019-4f21-b820-d90cbf86ce31', '落日', '落日', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["晚照背高臺，殘鐘殘角催。","能銷幾度落，已是半生來。","吹葉陰風發，漫空暝色迴。","因思古人事，更變盡塵埃。"]', '["晚照背高台，殘鐘殘角催。","能銷幾度落，已是半生来。","吹葉陰风發，漫空暝色迴。","因思古人事，更变尽塵埃。"]', '诗', 'shi', '', NULL, '落日 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93e329a4-bbb9-4f72-acfb-5ea783db7db0', '春興', '春兴', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["柳暖鶯多語，花明草盡長。","風流在詩句，牽率遶池塘。","叫切禽名宇，飛忙蝶姓莊。","時來真可惜，自勉掇蘭芳。"]', '["柳暖鶯多語，花明草尽长。","风流在诗句，牽率遶池塘。","叫切禽名宇，飞忙蝶姓莊。","时来真可惜，自勉掇蘭芳。"]', '诗', 'shi', '', NULL, '春興 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb938ee6-61a4-4fab-831e-5b6a1d11f326', '遠山', '远山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["天際雲根破，寒山列翠迴。","幽人當立久，白鳥背飛來。","瀑濺何州地，僧尋幾嶠苔。","終須拂巾履，獨去謝塵埃。"]', '["天際云根破，寒山列翠迴。","幽人當立久，白鸟背飞来。","瀑濺何州地，僧尋幾嶠苔。","終須拂巾履，独去謝塵埃。"]', '诗', 'shi', '', NULL, '遠山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83d6e735-fde0-4a30-98d6-04ede7f05c2c', '和鄭谷郎中幽棲之什', '和鄭谷郎中幽棲之什', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["誰知閑退跡，門逕入寒汀。","靜倚雲僧杖，孤看野燒星。","墨霑吟石黑，苔染釣船青。","相對唯溪寺，初宵聞念經。"]', '["誰知闲退跡，门逕入寒汀。","静倚云僧杖，孤看野燒星。","墨霑吟石黑，苔染釣船青。","相对唯溪寺，初宵闻念經。"]', '诗', 'shi', '', NULL, '和鄭谷郎中幽棲之什 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41795542-a684-461f-8b8a-b88b74899034', '勉道林謙光鴻蘊二姪', '勉道林謙光鴻蘊二姪', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊林諸姪在，還住本師房。","共埽焚修地，同聞水石香。","莫將閑世界，擬敵好時光。","須看南山下，無名塚滿岡。"]', '["旧林諸姪在，還住本師房。","共埽焚修地，同闻水石香。","莫將闲世界，擬敵好时光。","須看南山下，無名塚满岡。"]', '诗', 'shi', '', NULL, '勉道林謙光鴻蘊二姪 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7850763-3f51-410b-b499-97a70cb74184', '渚宮自勉二首 一', '渚宮自勉二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["晨午殊豐足，伊何撓肺腸。","形容侵老病，山水憶韜藏。","必謝金臺去，還攜鐵錫將。","東林露壇畔，舊對白蓮房。"]', '["晨午殊豐足，伊何撓肺腸。","形容侵老病，山水憶韜藏。","必謝金台去，還携鐵錫將。","东林露壇畔，旧对白蓮房。"]', '诗', 'shi', '', NULL, '渚宮自勉二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7865e6e-0d8b-46a3-8f1a-1a063ed9044f', '渚宮自勉二首 二', '渚宮自勉二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["畢竟擬何求，隨緣去住休。","天涯遊勝境，海上宿仙洲。","夢好尋無跡，詩成旋不留。","從他笑輕事，獨自憶莊周。"]', '["畢竟擬何求，隨緣去住休。","天涯游勝境，海上宿仙洲。","梦好尋無跡，诗成旋不留。","從他笑轻事，独自憶莊周。"]', '诗', 'shi', '', NULL, '渚宮自勉二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('650ad76c-dc6b-48bb-91a5-37a4d90aea1c', '謝㴩湖茶', '謝㴩湖茶', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["㴩湖唯上貢，何以惠尋常。","還是詩心苦，堪消蠟面香。","碾聲通一室，烹色帶殘陽。","若有新春者，西來信勿忘。"]', '["㴩湖唯上貢，何以惠尋常。","還是诗心苦，堪消蠟面香。","碾声通一室，烹色带殘陽。","若有新春者，西来信勿忘。"]', '诗', 'shi', '', NULL, '謝㴩湖茶 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d67b7439-eef5-436d-80e9-c7c6a19e15ff', '寄歸州馬判官', '寄归州马判官', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["郡帶女𡡓名，民康境亦寧。","晏梳秋鬢白，閑坐暮山青。","贈客椒初熟，尋僧酒半醒。","應懷舊居處，歌管隔牆聽。"]', '["郡带女𡡓名，民康境亦寧。","晏梳秋鬢白，闲坐暮山青。","贈客椒初熟，尋僧酒半醒。","應懷旧居处，歌管隔牆听。"]', '诗', 'shi', '', NULL, '寄歸州馬判官 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20b83822-4c15-4540-a81b-5e4d4fa283ff', '倦客', '倦客', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["閉眼即開門，人間事倦聞。","如何迎好客，不似看閑雲。","少欲資三要，多言讓十分。","疎慵本吾性，任笑早離羣。"]', '["閉眼即开门，人间事倦闻。","如何迎好客，不似看闲云。","少欲資三要，多言讓十分。","疎慵本吾性，任笑早離羣。"]', '诗', 'shi', '', NULL, '倦客 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d114de5-b582-4563-b2c3-5763ed9b8fa0', '送靈{巩/言}上人遊五臺', '送靈{巩/言}上人游五台', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["此去清涼頂，期瞻大聖容。","便應過洛水，即未上嵩峰。","殘照催行影，幽林惜駐蹤。","想登金閣望，東北極兵鋒。"]', '["此去清涼頂，期瞻大聖容。","便應過洛水，即未上嵩峰。","殘照催行影，幽林惜駐蹤。","想登金閣望，东北極兵鋒。"]', '诗', 'shi', '', NULL, '送靈{巩/言}上人遊五臺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e59b0761-8246-4b26-8826-766359671ea0', '靜坐', '静坐', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["坐臥與行住，入禪還出吟。","也應長日月，消得箇身心。","默論相如少，黃梅付囑深。","門前古松徑，時起步清陰。"]', '["坐臥與行住，入禪還出吟。","也應长日月，消得箇身心。","默論相如少，黄梅付囑深。","门前古松徑，时起步清陰。"]', '诗', 'shi', '', NULL, '靜坐 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1391f0de-1bcc-499f-b434-6ff4063d84ca', '謝虛中上人寄示題天策閣詩', '謝虛中上人寄示題天策閣诗', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["天策二首作，境幽搜亦玄。","閣橫三楚上，題挂九霄邊。","寺額因標勝，詩人合遇賢。","他時誰倚檻，吟此豈忘筌。"]', '["天策二首作，境幽搜亦玄。","閣橫三楚上，題挂九霄邊。","寺額因標勝，诗人合遇賢。","他时誰倚檻，吟此豈忘筌。"]', '诗', 'shi', '', NULL, '謝虛中上人寄示題天策閣詩 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f28d134-8d67-484b-a588-45740f08b0bb', '荆門寄懷章供奉兼呈幕中知己', '荆门寄懷章供奉兼呈幕中知己', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["紫衣居貴上，青衲老關中。","事佛門相似，朝天路不同。","神凝無惡夢，詩澹老真風。","聞道知音在，官高信莫通。"]', '["紫衣居貴上，青衲老关中。","事佛门相似，朝天路不同。","神凝無惡梦，诗澹老真风。","闻道知音在，官高信莫通。"]', '诗', 'shi', '', NULL, '荆門寄懷章供奉兼呈幕中知己 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1cc2535-5f6e-4faa-904b-dce571a5c9fd', '江令石', '江令石', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["思量江令意，愛石甚悠悠。","貪向深宮去，死同亡國休。","兩株荒草裏，千古暮江頭。","若似黃金貴，隋軍也不留。"]', '["思量江令意，愛石甚悠悠。","貪向深宮去，死同亡国休。","兩株荒草裏，千古暮江头。","若似黄金貴，隋軍也不留。"]', '诗', 'shi', '', NULL, '江令石 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83bccb39-1507-41b6-ba47-d7168124db92', '月下作', '月下作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["良夜如清晝，幽人在小庭。","滿空垂列宿，那箇是文星。","世界歸誰是，心魂向自寧。","何當見堯舜，重爲造生靈。"]', '["良夜如清晝，幽人在小庭。","满空垂列宿，那箇是文星。","世界归誰是，心魂向自寧。","何當见堯舜，重爲造生靈。"]', '诗', 'shi', '', NULL, '月下作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ca9e66-99e0-4919-a270-ab66a60d1354', '遊道林寺四絕亭觀宋杜詩版', '游道林寺四絕亭观宋杜诗版', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["宋杜詩題在，風騷到此真。","獨來終日看，一爲拂秋塵。","古石生寒仞，春松脫老鱗。","高僧眼根靜，應見客吟神。"]', '["宋杜诗題在，风騷到此真。","独来終日看，一爲拂秋塵。","古石生寒仞，春松脫老鱗。","高僧眼根静，應见客吟神。"]', '诗', 'shi', '', NULL, '遊道林寺四絕亭觀宋杜詩版 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbf07096-03b8-4c17-b214-14daf96efc3b', '勉詩僧', '勉诗僧', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["莫把毛生刺，低佪謁李膺。","須防知佛者，解笑愛名僧。","道性宜如水，詩情合似冰。","還同蓮社客，聯唱遶香燈。"]', '["莫把毛生刺，低佪謁李膺。","須防知佛者，解笑愛名僧。","道性宜如水，诗情合似冰。","還同蓮社客，聯唱遶香灯。"]', '诗', 'shi', '', NULL, '勉詩僧 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d890812-78b8-4fb7-926a-13a28f78cc4a', '謝人墨', '謝人墨', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["珍重歲寒煙，攜來路幾千。","只應真典誥，消得苦磨研。","正色浮端硯，精光動蜀牋。","因君強濡染，捨此即忘筌。"]', '["珍重歲寒煙，携来路幾千。","只應真典誥，消得苦磨研。","正色浮端硯，精光动蜀牋。","因君強濡染，捨此即忘筌。"]', '诗', 'shi', '', NULL, '謝人墨 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('892cf82d-9cd9-48b3-a671-ae332cea8afe', '送人遊玉泉寺', '送人游玉泉寺', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["西峰大雪開，萬疊向空堆。","客貴猶尋去，僧高肯不來。","潭澄猨覰月，竇冷鹿眠苔。","公子將才子，聯題興未迴。"]', '["西峰大雪开，万叠向空堆。","客貴猶尋去，僧高肯不来。","潭澄猨覰月，竇冷鹿眠苔。","公子將才子，聯題兴未迴。"]', '诗', 'shi', '', NULL, '送人遊玉泉寺 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd28c4a2-034a-4f2e-801b-0ba34830854e', '寄鄭谷郎中', '寄鄭谷郎中', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["詩心何以傳，所證自同禪。","覓句如探虎，逢知似得仙。","神清太古在，字好雅風全。","曾沐星郎許，終慙是斐然。"]', '["诗心何以傳，所證自同禪。","覓句如探虎，逢知似得仙。","神清太古在，字好雅风全。","曾沐星郎許，終慙是斐然。"]', '诗', 'shi', '', NULL, '寄鄭谷郎中 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408b97c2-539c-45dd-90e1-e03935b04202', '春雨', '春雨', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["欲布如膏勢，先聞動地雷。","雲龍相得起，風電一時來。","霢霂農桑野，冥濛楊柳臺。","何人待晴暖，庭有牡丹開。"]', '["欲布如膏勢，先闻动地雷。","云龙相得起，风電一时来。","霢霂農桑野，冥濛楊柳台。","何人待晴暖，庭有牡丹开。"]', '诗', 'shi', '', NULL, '春雨 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('629c6e7b-3662-444b-a22b-8df30f90b1a7', '明月峰', '明月峰', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["明月峰頭石，曾聞學月明。","別舒長夜彩，高照一村耕。","頗亂無私理，徒驚鄙俗情。","傳云遭鑿後，頑白在崢嶸。"]', '["明月峰头石，曾闻学月明。","別舒长夜彩，高照一村耕。","頗亂無私理，徒驚鄙俗情。","傳云遭鑿後，頑白在崢嶸。"]', '诗', 'shi', '', NULL, '明月峰 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('347ff74b-3ac5-4a01-b2c4-a15222b967c7', '謝人惠紫栗拄杖', '謝人惠紫栗拄杖', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["仙掌峰前得，何當此見遺。","百年衰朽骨，六尺歲寒姿。","雪外兼松凭，泉邊待月欹。","他時出山去，猶謝見相隨。"]', '["仙掌峰前得，何當此见遺。","百年衰朽骨，六尺歲寒姿。","雪外兼松凭，泉邊待月欹。","他时出山去，猶謝见相隨。"]', '诗', 'shi', '', NULL, '謝人惠紫栗拄杖 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9132ae-c791-4d4c-9ffd-034199d38222', '送人遊湘湖', '送人游湘湖', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["君遊南國去，旅夢若爲寧。","一路隨鴻鴈，千峰遶洞庭。","林明楓盡落，野黑燒初經。","有興尋僧否，湘西寺最靈。"]', '["君游南国去，旅梦若爲寧。","一路隨鴻鴈，千峰遶洞庭。","林明楓尽落，野黑燒初經。","有兴尋僧否，湘西寺最靈。"]', '诗', 'shi', '', NULL, '送人遊湘湖 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f969d44e-8927-4fb8-869b-be86c2234ebb', '小松', '小松', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["發地纔過膝，蟠根已有靈。","嚴霜百草白，深院一林青。","後夜蕭騷動，空階蟋蟀聽。","誰於千歲外，吟遶老龍形。"]', '["發地纔過膝，蟠根已有靈。","嚴霜百草白，深院一林青。","後夜蕭騷动，空階蟋蟀听。","誰於千歲外，吟遶老龙形。"]', '诗', 'shi', '', NULL, '小松 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc51ba0-80f6-44d9-8a2b-57ecbc59e8a4', '金江寓居', '金江寓居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["考槃應未永，聊此養閑疎。","野趣今何似，詩題舊不如。","春篁離籜盡，陂藕折花初。","終要秋雲是，從風恣卷舒。"]', '["考槃應未永，聊此養闲疎。","野趣今何似，诗題旧不如。","春篁離籜尽，陂藕折花初。","終要秋云是，從风恣卷舒。"]', '诗', 'shi', '', NULL, '金江寓居 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abbbd055-7935-417b-9ea6-db52300d5806', '晚夏金江寓居答友生', '晚夏金江寓居答友生', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["日日衝殘熱，相尋入亂蒿。","閑中滋味遠，詩裏是非高。","碧聳新生竹，紅垂半熟桃。","時難未可出，且欲淬豪曹。"]', '["日日衝殘熱，相尋入亂蒿。","闲中滋味远，诗裏是非高。","碧聳新生竹，紅垂半熟桃。","时难未可出，且欲淬豪曹。"]', '诗', 'shi', '', NULL, '晚夏金江寓居答友生 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5a855ad-92d2-495f-afc6-8a692eeed140', '寄李洞秀才', '寄李洞秀才', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["到處聽時論，知君屈最深。","秋風幾西笑，抱玉但傷心。","野水翻紅藕，滄江老白禽。","相思未相識，聞在蜀中吟。"]', '["到处听时論，知君屈最深。","秋风幾西笑，抱玉但傷心。","野水翻紅藕，滄江老白禽。","相思未相識，闻在蜀中吟。"]', '诗', 'shi', '', NULL, '寄李洞秀才 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0068feff-a674-4cda-b330-8ea23ab56a1c', '過商山', '過商山', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["疊疊疊嵐寒，紅塵翠裏盤。","前程有名利，此路莫艱難。","雲水侵天老，輪蹄到月殘。","何能尋四皓，過盡見長安。"]', '["叠叠叠嵐寒，紅塵翠裏盤。","前程有名利，此路莫艱难。","云水侵天老，輪蹄到月殘。","何能尋四皓，過尽见长安。"]', '诗', 'shi', '', NULL, '過商山 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd5c1942-a090-468c-a456-6c4c5a2f49d2', '蟬八韻', '蟬八韻', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["咽咽復啾啾，多來自早秋。","園林涼正好，風雨思相收。","在處聲無別，何人淚欲流。","冷憐天露滴，傷共野禽遊。","靜息深依竹，驚移瞥過樓。","分明晴渡口，淒切暮關頭。","時節推應定，飛鳴即未休。","年年聞爾苦，遠憶所居幽。"]', '["咽咽复啾啾，多来自早秋。","园林涼正好，风雨思相收。","在处声無別，何人泪欲流。","冷怜天露滴，傷共野禽游。","静息深依竹，驚移瞥過楼。","分明晴渡口，淒切暮关头。","时節推應定，飞鳴即未休。","年年闻爾苦，远憶所居幽。"]', '诗', 'shi', '', NULL, '蟬八韻 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af9018bc-b647-4429-9b00-413fa12bfc69', '鷺鷥二首 一', '鷺鷥二首 一', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["日日滄江去，時時得意歸。","自能終潔白，何處悞翻飛。","晚立銀塘闊，秋栖玉露微。","殘陽葦花畔，雙下釣魚磯。"]', '["日日滄江去，时时得意归。","自能終潔白，何处悞翻飞。","晚立銀塘闊，秋栖玉露微。","殘陽葦花畔，雙下釣鱼磯。"]', '诗', 'shi', '', NULL, '鷺鷥二首 一 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b09d4d44-088a-4694-9263-549fc3af24f9', '鷺鷥二首 二', '鷺鷥二首 二', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["雪裏曾迷我，籠中舊養君。","忽從紅蓼岸，飛出白鷗羣。","影照翹灘浪，翎濡宿島雲。","鴛鴻解相憶，天上列紛紛。"]', '["雪裏曾迷我，籠中旧養君。","忽從紅蓼岸，飞出白鷗羣。","影照翹灘浪，翎濡宿島云。","鴛鴻解相憶，天上列紛紛。"]', '诗', 'shi', '', NULL, '鷺鷥二首 二 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ff20737-ba4e-482e-b1d6-b053ecd0c713', '送僧歸南岳', '送僧归南岳', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["濁世住終難，孤峰念永安。","逆風眉磔磔，衝雪錫珊珊。","石室關霞嫩，松枝拂蘚乾。","巖猨應認得，連臂下句欄。"]', '["濁世住終难，孤峰念永安。","逆风眉磔磔，衝雪錫珊珊。","石室关霞嫩，松枝拂蘚乾。","巖猨應認得，連臂下句欄。"]', '诗', 'shi', '', NULL, '送僧歸南岳 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f086365-2930-4dde-9ac3-a922af30550c', '夏日林下作', '夏日林下作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["煩暑莫相煎，森森在眼前。","暫來還盡日，獨坐只聞蟬。","草媚終難死，花飛卒未蔫。","秋風捨此去，滿篋貯新篇。"]', '["煩暑莫相煎，森森在眼前。","暫来還尽日，独坐只闻蟬。","草媚終难死，花飞卒未蔫。","秋风捨此去，满篋貯新篇。"]', '诗', 'shi', '', NULL, '夏日林下作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1b41c40-52db-462b-a6e0-543cdc5ffe5a', '村居寄懷', '村居寄懷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["風雨如堯代，何心欲退藏。","諸侯行教化，下國自耕桑。","道挫時機盡，禪留話路長。","前溪久不過，忽覺早禾香。"]', '["风雨如堯代，何心欲退藏。","諸侯行教化，下国自耕桑。","道挫时機尽，禪留話路长。","前溪久不過，忽覺早禾香。"]', '诗', 'shi', '', NULL, '村居寄懷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7386ed93-4b1f-4618-a5bd-93f18f55b0f0', '酬王秀才', '酬王秀才', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["相於分倍親，靜論到吟真。","王澤曾無外，風騷甚少人。","鴻隨秋過盡，雪向臘飛頻。","何處多幽勝，期君作近鄰。"]', '["相於分倍親，静論到吟真。","王澤曾無外，风騷甚少人。","鴻隨秋過尽，雪向臘飞頻。","何处多幽勝，期君作近鄰。"]', '诗', 'shi', '', NULL, '酬王秀才 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32c9245c-8730-4b81-b133-5427f14946ce', '贈無本上人', '贈無本上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["往年吟月社，因亂散揚州。","未免無端事，何妨出世流。","洞庭禪過臘，衡岳坐經秋。","終說將衣鉢，天台老去休。"]', '["往年吟月社，因亂散揚州。","未免無端事，何妨出世流。","洞庭禪過臘，衡岳坐經秋。","終说將衣鉢，天台老去休。"]', '诗', 'shi', '', NULL, '贈無本上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b9e51e7-dd6e-4fdb-a12c-dd083ebea766', '寄華山司空圖', '寄华山司空圖', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["天下艱難際，全家入華山。","幾勞丹詔問，空見使臣還。","瀑布寒吹夢，蓮峰翠濕關。","兵戈阻相訪，身老瘴雲間。"]', '["天下艱难際，全家入华山。","幾勞丹詔问，空见使臣還。","瀑布寒吹梦，蓮峰翠濕关。","兵戈阻相訪，身老瘴云间。"]', '诗', 'shi', '', NULL, '寄華山司空圖 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0147be6-bd00-47a4-b53d-841accddaa08', '題真州精舍', '題真州精舍', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["波心精舍好，那岸是繁華。","礙目無高樹，當門即遠沙。","晨齋來海客，夜磬到漁家。","石鼎秋濤靜，禪回有岳茶。"]', '["波心精舍好，那岸是繁华。","礙目無高樹，當门即远沙。","晨斋来海客，夜磬到漁家。","石鼎秋濤静，禪回有岳茶。"]', '诗', 'shi', '', NULL, '題真州精舍 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff75ba70-8fcb-434d-ba52-cecff1bfd2f7', '懷道林寺因寄仁用二上人', '懷道林寺因寄仁用二上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["名山知不遠，長憶寺門松。","昨晚登樓見，前年過夏峰。","雨餘雲脚樹，風外日西鐘。","莫更來東岸，紅塵沒馬蹤。"]', '["名山知不远，长憶寺门松。","昨晚登楼见，前年過夏峰。","雨餘云脚樹，风外日西鐘。","莫更来东岸，紅塵沒马蹤。"]', '诗', 'shi', '', NULL, '懷道林寺因寄仁用二上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb216bc4-0d81-479f-a3ef-2ee9faa1ed11', '尋陽道中作', '尋陽道中作', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["秋聲連岳樹，草色徧汀洲。","多事時爲客，無人處上樓。","雲疎片雨歇，野闊九江流。","欲向南朝去，詩僧有惠休。"]', '["秋声連岳樹，草色徧汀洲。","多事时爲客，無人处上楼。","云疎片雨歇，野闊九江流。","欲向南朝去，诗僧有惠休。"]', '诗', 'shi', '', NULL, '尋陽道中作 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74054d40-b588-4403-a595-55698869fc34', '東林雨後望香爐峰', '东林雨後望香爐峰', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["翠濕僧窗裏，寒堆鳥道邊。","靜思尋去路，急遶落來泉。","暮雨開青壁，朝陽照紫煙。","二林多長老，誰憶上頭禪。"]', '["翠濕僧窗裏，寒堆鸟道邊。","静思尋去路，急遶落来泉。","暮雨开青壁，朝陽照紫煙。","二林多长老，誰憶上头禪。"]', '诗', 'shi', '', NULL, '東林雨後望香爐峰 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('576da9e4-fb3f-47ca-8b1b-ee3171a66d33', '寄雙泉大師師兄', '寄雙泉大師師兄', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["清泉流眼底，白道倚巖稜。","後夜禪初入，前溪樹折冰。","南涼來的的，北魏去騰騰。","敢把吾師意，密傳門外僧。"]', '["清泉流眼底，白道倚巖稜。","後夜禪初入，前溪樹折冰。","南涼来的的，北魏去腾腾。","敢把吾師意，密傳门外僧。"]', '诗', 'shi', '', NULL, '寄雙泉大師師兄 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24875964-dec1-410b-8bb8-f10fb93eb57d', '送人潤州尋兄弟', '送人潤州尋兄弟', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["君話南徐去，迢迢過建康。","弟兄新得信，鴻鴈久離行。","木落空林浪，秋殘漸雪霜。","閑遊登北固，東望海蒼蒼。"]', '["君話南徐去，迢迢過建康。","弟兄新得信，鴻鴈久離行。","木落空林浪，秋殘漸雪霜。","闲游登北固，东望海蒼蒼。"]', '诗', 'shi', '', NULL, '送人潤州尋兄弟 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d79dd82d-2f37-4304-b510-62b446485d1d', '貽張生', '貽張生', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["日日見入寺，未曾含酒容。","閑聽老僧語，坐到夕陽鐘。","竹裏行多影，花邊偶過蹤。","猶言謝生計，隨我去孤峰。"]', '["日日见入寺，未曾含酒容。","闲听老僧語，坐到夕陽鐘。","竹裏行多影，花邊偶過蹤。","猶言謝生計，隨我去孤峰。"]', '诗', 'shi', '', NULL, '貽張生 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acc06edc-6b58-4a25-a462-d4541e9a2fb2', '送人遊雍京', '送人游雍京', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["君來乞詩別，聊與愴前程。","九野未無事，少年何遠行。","商雲盤翠險，秦甸下煙平。","應見周南化，如今在雍京。"]', '["君来乞诗別，聊與愴前程。","九野未無事，少年何远行。","商云盤翠險，秦甸下煙平。","應见周南化，如今在雍京。"]', '诗', 'shi', '', NULL, '送人遊雍京 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('700b5dfc-8c45-40b4-a559-20494d5ff44f', '春草', '春草', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["處處碧萋萋，平原帶日西。","堪隨遊子路，遠入鷓鴣啼。","金谷園應沒，夫差國已迷。","欲尋蘭蕙徑，荒穢滿汀畦。"]', '["处处碧萋萋，平原带日西。","堪隨游子路，远入鷓鴣啼。","金谷园應沒，夫差国已迷。","欲尋蘭蕙徑，荒穢满汀畦。"]', '诗', 'shi', '', NULL, '春草 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6db9572-1035-4fdf-9e29-efca749f51e5', '懷華頂道人', '懷华頂道人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["華頂星邊出，真宜上士家。","無人觸牀榻，滿屋貯煙霞。","坐臥臨天井，晴明見海涯。","禪餘石橋去，屐齒印松花。"]', '["华頂星邊出，真宜上士家。","無人觸牀榻，满屋貯煙霞。","坐臥臨天井，晴明见海涯。","禪餘石橋去，屐齒印松花。"]', '诗', 'shi', '', NULL, '懷華頂道人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32216375-4854-487a-b2be-b89a6d9f8148', '寄自牧上人', '寄自牧上人', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["五老迴無計，三峰去不成。","何言謝雲鳥，此地識公卿。","夢媿將僧說，心嫌觸類生。","南朝古山寺，曾憶共尋行。"]', '["五老迴無計，三峰去不成。","何言謝云鸟，此地識公卿。","梦媿將僧说，心嫌觸類生。","南朝古山寺，曾憶共尋行。"]', '诗', 'shi', '', NULL, '寄自牧上人 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26ef4d65-5bc5-4d4f-b157-4f41b66b81e5', '靜坐', '静坐', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["日日只騰騰，心機何以興。","詩魔苦不利，禪寂頗相應。","硯滿塵埃點，衣多作臥稜。","如斯自消息，合是箇閑僧。"]', '["日日只腾腾，心機何以兴。","诗魔苦不利，禪寂頗相應。","硯满塵埃点，衣多作臥稜。","如斯自消息，合是箇闲僧。"]', '诗', 'shi', '', NULL, '靜坐 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('532305fe-18ed-4cf1-b2b3-6a8efee3512d', '送人遊衡岳', '送人游衡岳', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["荆楚臘將殘，江湖蒼莽間。","孤舟載高興，千里向名山。","雪浪來無定，風帆去是閑。","石橋僧問我，應寄岳茶還。"]', '["荆楚臘將殘，江湖蒼莽间。","孤舟載高兴，千里向名山。","雪浪来無定，风帆去是闲。","石橋僧问我，應寄岳茶還。"]', '诗', 'shi', '', NULL, '送人遊衡岳 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef031c67-5e6e-441e-a405-b9c8dbef1c45', '荅知己自闕下寄書', '荅知己自闕下寄书', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["故人勞札翰，千里寄荆臺。","知戀文明在，來尋江漢來。","羣機喧白晝，陸海漲黃埃。","得路應相笑，無成守死灰。"]', '["故人勞札翰，千里寄荆台。","知戀文明在，来尋江漢来。","羣機喧白晝，陸海漲黄埃。","得路應相笑，無成守死灰。"]', '诗', 'shi', '', NULL, '荅知己自闕下寄書 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ade9e4-a623-4b61-978d-6aff8147a113', '新笋', '新笋', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["亂迸苔錢破，參差出小欄。","層層離錦籜，節節露琅玕。","直上心終勁，四垂煙漸寬。","欲知含古律，試剪鳳簫看。"]', '["亂迸苔錢破，參差出小欄。","層層離錦籜，節節露琅玕。","直上心終勁，四垂煙漸寬。","欲知含古律，試剪鳳簫看。"]', '诗', 'shi', '', NULL, '新笋 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ffa383-10c1-4ef6-8ea8-e9848276aed2', '寄唐洙處士', '寄唐洙处士', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["行僧去湘水，歸鴈度荆門。","彼此亡家國，東西役夢魂。","多慵如長傲，久住不生根。","曾問興亡事，丁寧寄勿言。"]', '["行僧去湘水，归鴈度荆门。","彼此亡家国，东西役梦魂。","多慵如长傲，久住不生根。","曾问兴亡事，丁寧寄勿言。"]', '诗', 'shi', '', NULL, '寄唐洙處士 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faaae310-4449-42da-ae3c-d5b44769c6ec', '謝人惠竹蠅拂', '謝人惠竹蠅拂', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["妙刮筠篁製，纖柔玉柄同。","拂蠅聲滿室，指月影搖空。","敢捨經行外，常將宴坐中。","揮談一無取，千萬媿生公。"]', '["妙刮筠篁製，纖柔玉柄同。","拂蠅声满室，指月影搖空。","敢捨經行外，常將宴坐中。","揮談一無取，千万媿生公。"]', '诗', 'shi', '', NULL, '謝人惠竹蠅拂 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaa53729-5851-4d2a-8b41-990b07014c9b', '新燕', '新燕', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["燕燕知何事，年年應候來。","却緣華屋在，長得好時催。","花外銜泥去，空中接食迴。","不同黃雀意，迷逐網羅媒。"]', '["燕燕知何事，年年應候来。","却緣华屋在，长得好时催。","花外銜泥去，空中接食迴。","不同黄雀意，迷逐網羅媒。"]', '诗', 'shi', '', NULL, '新燕 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd1e51d-7705-4ddb-98a2-ecb9b56bee62', '謝王先輩寄氈', '謝王先輩寄氈', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["深謝高科客，名氈寄惠重。","靜思生朔漠，和雪長蒙茸。","摺坐資禪悅，鋪眠減病容。","他年從破碎，擔去臥孤峰。"]', '["深謝高科客，名氈寄惠重。","静思生朔漠，和雪长蒙茸。","摺坐資禪悅，鋪眠減病容。","他年從破碎，擔去臥孤峰。"]', '诗', 'shi', '', NULL, '謝王先輩寄氈 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b9c7c5b-3e12-427a-b6fc-564760456159', '寄還闕下高輦先輩卷', '寄還闕下高輦先輩卷', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["去歲逢京使，因還所寄詩。","難留天上作，曾換月中枝。","趣極僧迷旨，功深鬼不知。","仍聞得名後，特地更忘疲。"]', '["去歲逢京使，因還所寄诗。","难留天上作，曾換月中枝。","趣極僧迷旨，功深鬼不知。","仍闻得名後，特地更忘疲。"]', '诗', 'shi', '', NULL, '寄還闕下高輦先輩卷 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b7b986e-cd7d-4350-82ef-1a7d0d662a4b', '和孫支使惠示院中庭竹之什', '和孫支使惠示院中庭竹之什', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["憶就江僧乞，和煙得一莖。","剪黃憎舊本，科綠惜新生。","護噪蟬身穩，資吟客眼明。","星郎有佳詠，雅合此君聲。"]', '["憶就江僧乞，和煙得一莖。","剪黄憎旧本，科綠惜新生。","護噪蟬身穩，資吟客眼明。","星郎有佳詠，雅合此君声。"]', '诗', 'shi', '', NULL, '和孫支使惠示院中庭竹之什 齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab29e751-dee0-4fa2-ab51-9fc2b6a76058', '苦熱中江上懷爐峰舊居', '苦熱中江上懷爐峰旧居', '7fc0424d-5546-4ecc-a5dc-11a7b08d8228', '唐', '["舊寄爐峰下，杉松遶石房。","年年五六月，江上憶清涼。","久別應荒廢，終歸隔渺茫。","何當便搖落，披衲玩秋光。"]', '["旧寄爐峰下，杉松遶石房。","年年五六月，江上憶清涼。","久別應荒廢，終归隔渺茫。","何當便搖落，披衲玩秋光。"]', '诗', 'shi', '', NULL, '苦熱中江上懷爐峰舊居 齊己 shi');
